def _import_pyhxexpress_hxex_module():
    """Load pyHXExpress (repo-local checkout preferred over pip)."""
    import importlib

    if os.path.isdir(_LOCAL_PYHX_DIR) and _LOCAL_PYHX_DIR not in sys.path:
        # Parent of the pyhxexpress package (not the inner pyhxexpress/ folder).
        sys.path.insert(0, _LOCAL_PYHX_DIR)
    errors = []
    for label in ('pyhxexpress.hxex',):
        try:
            return importlib.import_module(label), ''
        except Exception as exc:
            errors.append(f'{label}: {exc}')
    return None, '; '.join(errors) if errors else 'unknown import failure'


