# Default Comet executable: project root (build with `make`)
def _default_comet_exe() -> str:
    # Prefer platform-specific binary (comet.linux.exe on Streamlit Cloud)
    candidates = ['comet.exe', 'comet']
    if sys.platform.startswith('linux'):
        candidates = ['comet.linux.exe', 'comet.exe', 'comet']
    for name in candidates:
        path = os.path.join(_SCRIPT_DIR, name)
        if os.path.exists(path) and os.access(path, os.X_OK):
            return path
    return os.path.join(_SCRIPT_DIR, 'comet.exe')  # fallback for user to correct


@st.cache_data(ttl=900, max_entries=32, show_spinner=False)
def _get_trfp_version_info(exe_path: str) -> dict[str, str]:
    """
    Best-effort ThermoRawFileParser version probe.
    Strategy:
    1) parse executable output (--version/-v/--help),
    2) fallback to conda package metadata filename.
    """
    p = str(exe_path or "").strip()
    if not p:
        return {"version": "unknown", "source": "no executable path provided"}

    version_rx = re.compile(r"\b(\d+\.\d+\.\d+(?:[-+._a-zA-Z0-9]*)?)\b")
    cmd_candidates = [
        [p, "--version"],
        [p, "-v"],
        [p, "--help"],
    ]
    for cmd in cmd_candidates:
        try:
            res = subprocess.run(cmd, text=True, capture_output=True, timeout=4)
        except Exception:
            continue
        text = ((res.stdout or "") + "\n" + (res.stderr or "")).strip()
        if not text:
            continue
        for raw_line in text.splitlines():
            line = str(raw_line).strip()
            if not line:
                continue
            if "thermorawfileparser" in line.lower():
                m = version_rx.search(line)
                if m:
                    return {"version": m.group(1), "source": f"from executable output: `{' '.join(cmd[1:]) or '(default)'}`"}
        m_any = version_rx.search(text)
        if m_any:
            return {"version": m_any.group(1), "source": f"from executable output: `{' '.join(cmd[1:]) or '(default)'}`"}

    # Conda fallback (works when wrapper script requires mono and direct probe fails).
    try:
        real_p = os.path.realpath(p)
        bin_dir = os.path.dirname(real_p)
        env_prefix = os.path.dirname(bin_dir) if os.path.basename(bin_dir) == "bin" else os.path.dirname(bin_dir)
        conda_meta = os.path.join(env_prefix, "conda-meta")
        if os.path.isdir(conda_meta):
            prefix = "thermorawfileparser-"
            candidates = [
                fn for fn in os.listdir(conda_meta)
                if fn.lower().startswith(prefix) and fn.lower().endswith(".json")
            ]
            if candidates:
                candidates.sort(
                    key=lambda fn: os.path.getmtime(os.path.join(conda_meta, fn)),
                    reverse=True,
                )
                best = candidates[0]
                stem = best[:-5]  # drop .json
                parts = stem.split("-")
                if len(parts) >= 3:
                    return {
                        "version": parts[1],
                        "source": f"from conda package metadata: `{best}`",
                    }
    except Exception:
        pass

    return {"version": "unknown", "source": "could not parse executable output or package metadata"}


def _get_trfp_version(exe_path: str) -> str:
    """Backward-compatible alias for older call sites."""
    info = _get_trfp_version_info(exe_path)
    return str(info.get("version", "unknown") or "unknown")

