def _workspace_scan_targets(root_dir: str) -> list[str]:
    """
    Constrain broad scans to known workspace scaffold folders.
    If root_dir looks like a workspace root, return only scaffold subdirs (+ root itself);
    otherwise return [root_dir].
    """
    root = os.path.abspath(str(root_dir or '').strip()) if root_dir else ''
    if not root or not os.path.isdir(root):
        return []
    rel_dirs = sorted(set(str(v).strip() for v in TAB_WORKDIR_DIRS.values() if str(v).strip()))
    scaffold_dirs: list[str] = []
    for rel in rel_dirs:
        p = os.path.join(root, rel)
        if os.path.isdir(p):
            scaffold_dirs.append(os.path.abspath(p))
    # Heuristic: treat as workspace root only when several scaffold dirs exist.
    # Performance: return scaffold dirs only (not root + scaffold dirs), otherwise
    # recursive scans traverse the same trees repeatedly and app reruns get slow.
    if len(scaffold_dirs) >= 4:
        return scaffold_dirs
    return [root]


