@st.cache_data(ttl=300, max_entries=512, show_spinner=False)
def _find_files_cached(data_dir: str, extensions: tuple[str, ...]) -> list[str]:
    """Cached fast local finder: root + immediate subdirectories only."""
    d = str(data_dir or '').strip()
    if not d or not os.path.isdir(d):
        return []
    exts = tuple(str(e).lower() for e in (extensions or tuple()))
    skip_dirnames = {
        '.git',
        '__pycache__',
        'node_modules',
        '.venv',
        'venv',
        '.mypy_cache',
        '.pytest_cache',
        'raw_conversion_plots',
        'plots_versions',
        'thumbnails',
        'images',
        'figures',
        'plots',
        'htmlcov',
        'dist',
        'build',
    }
    out: list[str] = []
    seen: set[str] = set()
    subdirs: list[str] = []
    try:
        for entry in os.scandir(d):
            try:
                nm = str(entry.name or '')
                low = nm.lower()
                if entry.is_file(follow_symlinks=False):
                    if any(low.endswith(ext) for ext in exts):
                        ap = os.path.abspath(entry.path)
                        if ap not in seen:
                            seen.add(ap)
                            out.append(ap)
                elif entry.is_dir(follow_symlinks=False):
                    if low in skip_dirnames or nm.startswith('.'):
                        continue
                    subdirs.append(entry.path)
            except Exception:
                continue
    except Exception:
        return []
    # Immediate subdirectories only (local recursive policy).
    for sub in subdirs:
        try:
            for entry in os.scandir(sub):
                try:
                    if not entry.is_file(follow_symlinks=False):
                        continue
                    low = str(entry.name or '').lower()
                    if any(low.endswith(ext) for ext in exts):
                        ap = os.path.abspath(entry.path)
                        if ap not in seen:
                            seen.add(ap)
                            out.append(ap)
                except Exception:
                    continue
        except Exception:
            continue
    return sorted(p for p in out if os.path.isfile(p))


def _clear_workspace_file_caches() -> None:
    """Drop cached file listings after workspace data-root changes (symlink migration, etc.)."""
    for fn in (
        _find_files_cached,
        _list_files_shallow_plus_one_cached,
        _list_mzml_dirs_depth2_cached,
        _targeted_mzml_subdirs_depth2_cached,
    ):
        try:
            fn.clear()
        except Exception:
            pass


def _find_files(data_dir: str, extensions: tuple) -> list[str]:
    """Find files with given extensions under data_dir (recursive). Returns full paths."""
    return _find_files_cached(str(data_dir), tuple(extensions))


def _list_files_shallow(data_dir: str, extensions: tuple[str, ...]) -> list[str]:
    """Fast non-recursive file listing for immediate directory only."""
    d = str(data_dir or '').strip()
    if not d or not os.path.isdir(d):
        return []
    exts = tuple(str(e).lower() for e in (extensions or tuple()))
    out: list[str] = []
    try:
        for name in os.listdir(d):
            p = os.path.join(d, name)
            if not os.path.isfile(p):
                continue
            low = str(name).lower()
            if any(low.endswith(ext) for ext in exts):
                out.append(p)
    except Exception:
        return []
    return _sort_existing_paths_by_mtime_desc(out)


@st.cache_data(ttl=90, max_entries=256, show_spinner=False)
def _list_files_shallow_plus_one_cached(data_dir: str, extensions: tuple[str, ...]) -> list[str]:
    """Fast cached listing: directory + immediate subdirectories only."""
    d = str(data_dir or '').strip()
    if not d or not os.path.isdir(d):
        return []
    out = list(_list_files_shallow(d, extensions))
    try:
        for nm in os.listdir(d):
            sub = os.path.join(d, nm)
            if os.path.isdir(sub):
                out.extend(_list_files_shallow(sub, extensions))
    except Exception:
        pass
    return _sort_existing_paths_by_mtime_desc(out)


@st.cache_data(ttl=90, max_entries=128, show_spinner=False)
def _list_mzml_dirs_depth2_cached(root_dir: str) -> list[str]:
    """Cached mzML directory discovery up to two levels deep."""
    root = str(root_dir or '').strip()
    if not root or not os.path.isdir(root):
        return []
    dirs: list[str] = []
    if _list_files_shallow(root, MZML_EXT):
        dirs.append(os.path.abspath(root))
    try:
        for d1 in os.listdir(root):
            p1 = os.path.abspath(os.path.join(root, d1))
            if not os.path.isdir(p1):
                continue
            if _list_files_shallow(p1, MZML_EXT):
                dirs.append(p1)
            try:
                for d2 in os.listdir(p1):
                    p2 = os.path.abspath(os.path.join(p1, d2))
                    if os.path.isdir(p2) and _list_files_shallow(p2, MZML_EXT):
                        dirs.append(p2)
            except Exception:
                pass
    except Exception:
        pass
    return sorted(set(dirs))


def _targeted_mzml_root_dir(working_dir: str) -> str:
    """Canonical targeted mzML root used by directory selectors."""
    wd = str(working_dir or '').strip()
    if not wd:
        return ''
    return os.path.abspath(os.path.join(wd, 'data', 'mzml'))


@st.cache_data(ttl=90, max_entries=128, show_spinner=False)
def _targeted_mzml_subdirs_depth2_cached(working_dir: str) -> list[str]:
    """Subdirectories under working_directory/data/mzml that contain mzML files."""
    opts, _, _ = _targeted_mzml_dropdown_dirs_with_counts(working_dir)
    return opts


@st.cache_data(ttl=90, max_entries=128, show_spinner=False)
def _targeted_mzml_dropdown_dirs_with_counts(working_dir: str) -> tuple[list[str], dict[str, int], dict[str, int]]:
    """mzML folder options (including root ``.``) plus direct/nested file counts per folder."""
    root = _targeted_mzml_root_dir(working_dir)
    if not root or not os.path.isdir(root):
        return [], {}, {}
    root_abs = os.path.abspath(root)
    mzml_paths: list[str] = []
    try:
        mzml_paths.extend(_list_files_shallow(root_abs, MZML_EXT))
        for d1 in os.listdir(root_abs):
            p1 = os.path.abspath(os.path.join(root_abs, d1))
            if not os.path.isdir(p1):
                continue
            mzml_paths.extend(_list_files_shallow(p1, MZML_EXT))
            try:
                for d2 in os.listdir(p1):
                    p2 = os.path.abspath(os.path.join(p1, d2))
                    if os.path.isdir(p2):
                        mzml_paths.extend(_list_files_shallow(p2, MZML_EXT))
            except Exception:
                pass
    except Exception:
        mzml_paths = []
    mzml_paths = sorted({os.path.abspath(p) for p in mzml_paths if os.path.isfile(p)})
    direct_counts: dict[str, int] = {}
    nested_counts: dict[str, int] = {}
    dir_options: set[str] = set()
    for fp in mzml_paths:
        parent = os.path.abspath(os.path.dirname(fp))
        direct_counts[parent] = direct_counts.get(parent, 0) + 1
        cur = parent
        while True:
            nested_counts[cur] = nested_counts.get(cur, 0) + 1
            dir_options.add(cur)
            if cur == root_abs:
                break
            parent_dir = os.path.abspath(os.path.dirname(cur))
            if parent_dir == cur or not str(cur).startswith(root_abs + os.sep):
                break
            cur = parent_dir
    if mzml_paths:
        dir_options.add(root_abs)
    return sorted(dir_options), direct_counts, nested_counts


def _targeted_mzml_dir_dropdown_label(
    path_in: str,
    working_dir: str,
    direct_counts: dict[str, int] | None = None,
    nested_counts: dict[str, int] | None = None,
) -> str:
    """Relative path under data/mzml with optional direct/nested mzML counts."""
    rel = _targeted_mzml_rel_label(path_in, working_dir)
    d_abs = os.path.abspath(str(path_in or '').strip())
    if direct_counts is not None and nested_counts is not None and d_abs:
        direct_n = int(direct_counts.get(d_abs, 0) or 0)
        nested_n = int(nested_counts.get(d_abs, 0) or 0)
        return f'{rel} (comet direct: {direct_n}, nested: {nested_n})'
    return rel


def _targeted_mzml_rel_label(path_in: str, working_dir: str) -> str:
    """Display label relative to working_directory/data/mzml."""
    p = str(path_in or '').strip()
    if not p:
        return '(none)'
    root = _targeted_mzml_root_dir(working_dir)
    try:
        if root and os.path.isdir(root):
            rel = os.path.relpath(os.path.abspath(p), os.path.abspath(root))
            return str(rel or os.path.basename(p))
    except Exception:
        pass
    return os.path.basename(p)


def _render_targeted_mzml_dropdown_caption() -> None:
    st.caption('Select from working_directory/data/mzml :')


def _has_supported_files_fast(data_dir: str, extensions: tuple[str, ...], max_subdirs: int = 60) -> bool:
    """Fast existence probe: shallow root + capped immediate subdirs."""
    d = str(data_dir or '').strip()
    if not d or not os.path.isdir(d):
        return False
    if _list_files_shallow(d, extensions):
        return True
    checked = 0
    try:
        for nm in os.listdir(d):
            sub = os.path.join(d, nm)
            if not os.path.isdir(sub):
                continue
            checked += 1
            if _list_files_shallow(sub, extensions):
                return True
            if checked >= int(max_subdirs):
                break
    except Exception:
        return False
    return False


# ---------------------------------------------------------------------------
# Dropdown discovery policy (performance/stability)
# ---------------------------------------------------------------------------
# For this app, dropdown options should be populated from designated tab folders
# using targeted shallow discovery (selected folder + immediate subfolders).
# Avoid broad recursive _find_files(...) calls in UI selectors, because large
# directory walks can cause slow reruns and instability.
#
# Preferred pattern for selectors:
# 1) _list_files_shallow(<tab_root>, <exts>)
# 2) _list_files_shallow(<immediate_subdir>, <exts>) for each child folder
# 3) de-duplicate + mtime sort
# 4) include '' as "(none)" as needed
#
# Use deep recursive scans only for explicit run actions where users request it.

def _sort_existing_paths_by_mtime_desc(paths: list[str]) -> list[str]:
    """Sort paths by mtime descending, skipping paths that no longer exist."""
    existing = [str(p) for p in (paths or []) if str(p).strip() and os.path.exists(str(p))]
    return sorted(existing, key=lambda p: os.path.getmtime(p), reverse=True)


def _ensure_local_workspace_data_root(base_dir: str) -> tuple[str, bool]:
    """Ensure ``<workspace>/data`` is a real local folder, not an external symlink (e.g. iCloud backup).

    Returns ``(data_root_path, migrated)``.
    """
    base = os.path.abspath(str(base_dir or '').strip())
    if not base:
        return '', False
    data_path = os.path.join(base, 'data')
    migrated = False
    old_data_real = ''
    try:
        if os.path.islink(data_path):
            old_data_real = os.path.realpath(data_path)
            if (not old_data_real.startswith(base + os.sep)) and old_data_real != base:
                backup = os.path.join(base, 'data_icloud_symlink_backup')
                if os.path.lexists(backup):
                    os.unlink(data_path)
                else:
                    os.rename(data_path, backup)
                os.makedirs(data_path, exist_ok=True)
                migrated = True
        elif not os.path.isdir(data_path):
            os.makedirs(data_path, exist_ok=True)
    except Exception:
        return data_path, False
    if migrated and old_data_real:
        try:
            old_ube2 = os.path.join(old_data_real, 'raw', 'Ube2D3')
            new_ube2 = os.path.join(data_path, 'raw', 'Ube2D3')
            if os.path.isdir(old_ube2) and not os.path.exists(new_ube2):
                shutil.copytree(old_ube2, new_ube2, symlinks=False)
        except Exception:
            pass
        for sub in ('fasta', 'csv', 'mzml'):
            try:
                old_sub = os.path.join(old_data_real, sub)
                new_sub = os.path.join(data_path, sub)
                os.makedirs(new_sub, exist_ok=True)
                if not os.path.isdir(old_sub):
                    continue
                for name in os.listdir(old_sub):
                    src = os.path.join(old_sub, name)
                    dst = os.path.join(new_sub, name)
                    if os.path.isfile(src) and not os.path.exists(dst):
                        shutil.copy2(src, dst)
            except Exception:
                continue
    return data_path, migrated


def _workspace_tab_dirs(base_dir: str) -> dict[str, str]:
    """
    Ensure per-tab folder architecture exists under working directory.
    Returns absolute paths keyed by TAB_WORKDIR_DIRS keys.
    """
    base = os.path.abspath(str(base_dir or '').strip()) if base_dir else ''
    if not base:
        return {}
    _data_root, _data_migrated = _ensure_local_workspace_data_root(base)
    if _data_migrated:
        st.session_state['_workspace_data_migrated_from_symlink'] = True
        _clear_workspace_file_caches()
    out: dict[str, str] = {}
    for key, rel in TAB_WORKDIR_DIRS.items():
        p = os.path.join(base, rel)
        os.makedirs(p, exist_ok=True)
        out[key] = p
    return out


def _resolve_work_root_with_mzml_candidates() -> str:
    """
    Resolve an active work root from session paths by selecting the first
    directory whose mzML root contains discoverable mzML directories.
    """
    seeds: list[str] = []
    for rv in [
        st.session_state.get('working_dir'),
        st.session_state.get('uploaded_data_dir'),
        st.session_state.get('sidebar_output_dir'),
        st.session_state.get('create_working_dir_path'),
    ]:
        p = str(rv or '').strip()
        if p and os.path.isdir(p):
            seeds.append(os.path.abspath(p))
    seeds = list(dict.fromkeys(seeds))
    candidates: list[str] = []
    for s in seeds:
        cur = s
        for _ in range(7):
            if cur and os.path.isdir(cur):
                candidates.append(cur)
            parent = os.path.abspath(os.path.dirname(cur))
            if (not parent) or (parent == cur):
                break
            cur = parent
    candidates = list(dict.fromkeys(candidates))
    for root in candidates:
        try:
            ws_probe = _workspace_tab_dirs(root)
        except Exception:
            ws_probe = {}
        probe = str(ws_probe.get('mzml', '') or '').strip()
        if probe and os.path.isdir(probe) and bool(_list_mzml_dirs_depth2_cached(probe)):
            return root
    # Fallback to current working_dir only when no mzML-bearing root is discovered.
    wd = str(st.session_state.get('working_dir') or '').strip()
    return os.path.abspath(wd) if wd and os.path.isdir(wd) else ''


def _resolve_hdx_fits_output_dir(work_root: str) -> str:
    """
    Resolve HDX Fits output folder, preferring workspace `working_directory/hdx_fits`.
    """
    candidates: list[str] = []
    wr = os.path.abspath(str(work_root or '').strip()) if work_root else ''
    if wr:
        candidates.extend([wr, os.path.join(wr, 'working_directory')])
    wd = str(st.session_state.get('working_dir') or '').strip()
    if wd:
        wd_abs = os.path.abspath(wd)
        candidates.extend([wd_abs, os.path.join(wd_abs, 'working_directory')])
    candidates.append(os.path.abspath(DEFAULT_WORKING_DIR))

    workspace_root = ''
    for cand in list(dict.fromkeys([c for c in candidates if str(c).strip()])):
        if os.path.basename(cand) == 'working_directory' and os.path.isdir(cand):
            workspace_root = cand
            break
    if not workspace_root:
        # If no existing workspace root is found, fall back to default working_directory path.
        workspace_root = os.path.abspath(DEFAULT_WORKING_DIR)
    try:
        os.makedirs(workspace_root, exist_ok=True)
    except Exception:
        pass

    out_dir = os.path.join(workspace_root, 'hdx_fits')
    try:
        os.makedirs(out_dir, exist_ok=True)
    except Exception:
        pass
    return out_dir


def _sanitize_name_token(value: str) -> str:
    token = re.sub(r'[^A-Za-z0-9._-]+', '_', str(value or '').strip()).strip('_')
    return token


def _fragment_subsequence_from_ion_identity(ion_identity: object, peptide_seq: str) -> str:
    """
    Infer fragment subsequence token from ion identity (a/b/c/x/y/z + index)
    relative to the parent peptide sequence.
    """
    pep = re.sub(r'[^A-Za-z]', '', str(peptide_seq or '')).upper()
    if not pep:
        return ''
    s = str(ion_identity or '').strip()
    # Standard: "a5", "y8 2+", "b3-CO_1+"
    m = re.search(r'^\s*([abcxyzABCXYZ])\s*([0-9]+)', s)
    # Radical: "(z+1)11_2+", "(c-1)6_4+"
    if not m:
        m = re.search(r'^\s*\(?\s*([abcxyzABCXYZ])[+-]\d+\s*\)\s*([0-9]+)', s)
    if not m:
        return ''
    ion_family = str(m.group(1)).lower()
    try:
        n = int(m.group(2))
    except Exception:
        return ''
    if n <= 0 or n > len(pep):
        return ''
    if ion_family in {'a', 'b', 'c'}:
        return pep[:n]
    if ion_family in {'x', 'y', 'z'}:
        return pep[-n:]
    return ''


def _fragment_charge_from_ion_identity(ion_identity: object) -> int:
    """
    Parse fragment ion charge from ion identity token (e.g., "x5 3+", "y7-NH3_4+").
    Returns 0 when unavailable.
    """
    s = str(ion_identity or '').strip()
    if not s:
        return 0
    # Prefer terminal "<N>+" charge token.
    m = re.search(r'(\d+)\s*\+\s*$', s)
    if m:
        try:
            z = int(m.group(1))
            return z if z > 0 else 0
        except Exception:
            return 0
    # Fallback for compact forms "..._<N>+" or "...<N>+".
    m2 = re.search(r'[_\s]?(\d+)\+$', s)
    if m2:
        try:
            z = int(m2.group(1))
            return z if z > 0 else 0
        except Exception:
            return 0
    return 0


def _fragment_subsequence_from_fragment_fit_key(fragment_fit_key: object, peptide_seq: str) -> str:
    """
    Infer a representative fragment subsequence from a combined fragment_fit_key string.
    When multiple ions are present, choose the shortest parseable subsequence as a
    conservative per-fragment cap target for deuteration.
    """
    pep = re.sub(r'[^A-Za-z]', '', str(peptide_seq or '')).upper()
    if not pep:
        return ''
    s = str(fragment_fit_key or '').strip()
    if not s:
        return ''
    candidates: list[str] = []
    for raw_tok in re.split(r'[,;|]+', s):
        tok = str(raw_tok or '').strip()
        if not tok:
            continue
        sub = _fragment_subsequence_from_ion_identity(tok, pep)
        if sub:
            candidates.append(sub)
        # Fallback: parse embedded ion tokens including radical notation like "(z+1)11_2+".
        for m in re.finditer(r'\(?\s*([abcxyzABCXYZ])(?:[+-]\d+)?\s*\)?\s*([0-9]+)', tok):
            try:
                ion_fam = str(m.group(1)).lower()
                n = int(m.group(2))
            except Exception:
                continue
            if n <= 0 or n > len(pep):
                continue
            if ion_fam in {'a', 'b', 'c'}:
                candidates.append(pep[:n])
            elif ion_fam in {'x', 'y', 'z'}:
                candidates.append(pep[-n:])
    if not candidates:
        return ''
    candidates = [c for c in candidates if c]
    if not candidates:
        return ''
    return sorted(candidates, key=lambda v: (len(v), v))[0]


def _precursor_charge_from_run_name(run_name: object) -> int:
    """
    Parse precursor charge from run/mzML name token like ..._Z2_... .
    """
    s = str(run_name or '').strip()
    if not s:
        return 0
    base = os.path.splitext(os.path.basename(s))[0]
    m = re.search(r'(?i)(?:^|_)Z(\d+)(?=_|$)', base)
    if not m:
        return 0
    try:
        z = int(m.group(1))
        return z if z > 0 else 0
    except Exception:
        return 0


def _raw_to_mzml_basename(raw_path: str) -> str:
    """
    Keep conversion basename identical to RAW basename (extension swap only).
    """
    p = os.path.abspath(str(raw_path or '').strip()) if raw_path else ''
    if not p:
        return ''
    return os.path.splitext(os.path.basename(p))[0]


def _name_mapping_dir(working_dir: str, selected_name_dir: str = '') -> str:
    ws = _workspace_tab_dirs(working_dir) if working_dir and os.path.isdir(working_dir) else {}
    base = ws.get('terminology') or ws.get('summary') or (working_dir if ws else str(working_dir or '').strip())
    out_root = os.path.abspath(str(base or '').strip()) if str(base or '').strip() else ''
    if not out_root:
        return ''
    sel = str(selected_name_dir or '').strip()
    if not sel:
        return out_root
    mzml_root = _targeted_mzml_root_dir(working_dir)
    try:
        if mzml_root and os.path.isdir(mzml_root):
            rel = os.path.relpath(os.path.abspath(sel), os.path.abspath(mzml_root))
            if rel not in ('.', '') and not str(rel).startswith('..'):
                return os.path.abspath(os.path.join(out_root, rel))
    except Exception:
        pass
    return out_root


def _name_mapping_latest_path(working_dir: str, selected_name_dir: str = '') -> str:
    root_dir = _name_mapping_dir(working_dir, selected_name_dir)
    new_path = os.path.join(root_dir, 'name_mapping_latest.json')
    return new_path


def _list_variable_matrix_inventory_checks_depth2(working_dir: str) -> list[str]:
    root_dir = _name_mapping_dir(working_dir)
    root = str(root_dir or '').strip()
    if not root or not os.path.isdir(root):
        return []
    out: list[str] = []
    seen: set[str] = set()

    def _append_inventory_csvs(d: str) -> None:
        try:
            for ent in os.scandir(d):
                try:
                    if not ent.is_file(follow_symlinks=False):
                        continue
                    nm = str(ent.name or '').lower()
                    if nm.endswith('.csv') and (
                        '_variable_matrix_inventory_check_' in nm
                        or nm == 'file_name_variables_matrix.csv'
                        or nm.startswith('file_name_variables_matrix_type')
                    ):
                        ap = os.path.abspath(ent.path)
                        if ap not in seen:
                            seen.add(ap)
                            out.append(ap)
                except Exception:
                    continue
        except Exception:
            return

    _append_inventory_csvs(root)
    try:
        for lvl1 in os.scandir(root):
            if not lvl1.is_dir(follow_symlinks=False):
                continue
            if str(lvl1.name or '').startswith('.'):
                continue
            _append_inventory_csvs(lvl1.path)
            try:
                for lvl2 in os.scandir(lvl1.path):
                    if not lvl2.is_dir(follow_symlinks=False):
                        continue
                    if str(lvl2.name or '').startswith('.'):
                        continue
                    _append_inventory_csvs(lvl2.path)
            except Exception:
                continue
    except Exception:
        pass

    def _sort_key(p: str) -> float:
        ap = os.path.abspath(str(p or '').strip())
        try:
            stp = os.stat(ap)
            return float(getattr(stp, 'st_birthtime', stp.st_mtime))
        except Exception:
            try:
                return float(os.path.getmtime(ap))
            except Exception:
                return float('-inf')

    return sorted(out, key=_sort_key, reverse=True)


def _selected_inventory_check_csv_path(working_dir: str) -> str:
    opts = _list_variable_matrix_inventory_checks_depth2(working_dir)
    if not opts:
        return ''
    cur = str(st.session_state.get('global_selected_variable_matrix_inventory_check_csv', '') or '').strip()
    if cur and os.path.isfile(cur):
        return cur
    return opts[0]


def _split_semicolon_tokens(value: object) -> list[str]:
    txt = str(value or '').strip()
    if not txt:
        return []
    return [t.strip() for t in txt.split(';') if t and str(t).strip()]


def _load_json_file(path: str) -> dict:
    p = str(path or '').strip()
    if not p or not os.path.isfile(p):
        return {}
    try:
        with open(p, 'r', encoding='utf-8') as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            out = dict(data)
            out['_source_path'] = p
            return out
        return {}
    except Exception:
        return {}


def _derive_pipeline_base_name(
    fasta_path: str = '',
    mzml_path: str = '',
    mzml_dir: str = '',
    working_dir: str = '',
) -> str:
    """
    Build a propagated base name:
    - FASTA basename
    - RAW directory context (if resolvable from mzML location)
    - mzML file basename (single) OR mzML directory basename (batch)
    """
    fasta_base = os.path.splitext(os.path.basename(fasta_path))[0] if fasta_path else ''
    mzml_target = ''
    mzml_context_dir = ''
    if mzml_path:
        mzml_target = os.path.splitext(os.path.basename(mzml_path))[0]
        mzml_context_dir = os.path.dirname(os.path.abspath(mzml_path))
    elif mzml_dir:
        mzml_target = os.path.basename(os.path.abspath(mzml_dir.rstrip(os.sep)))
        mzml_context_dir = os.path.abspath(mzml_dir)

    raw_token = ''
    if working_dir and os.path.isdir(working_dir) and mzml_context_dir:
        ws_dirs = _workspace_tab_dirs(working_dir)
        mzml_root = ws_dirs.get('mzml', '')
        raw_root = ws_dirs.get('raw', '')
        if mzml_root and raw_root and os.path.isdir(mzml_root) and os.path.isdir(raw_root):
            try:
                rel = os.path.relpath(mzml_context_dir, os.path.abspath(mzml_root))
                if not rel.startswith('..'):
                    raw_candidate = os.path.join(os.path.abspath(raw_root), rel)
                    if os.path.isdir(raw_candidate):
                        raw_token = os.path.basename(os.path.abspath(raw_candidate))
            except Exception:
                pass

    parts: list[str] = []
    for token in [fasta_base, raw_token, mzml_target]:
        stoken = _sanitize_name_token(token)
        if stoken:
            parts.append(stoken)
    return '_'.join(parts)


def _infer_family_from_text(value: str) -> str:
    """
    Infer high-level dataset family from filename/path text.
    Returns canonical family id or '' when unknown.
    """
    text = re.sub(r'[^A-Za-z0-9]+', '_', str(value or '').strip().lower()).strip('_')
    if not text:
        return ''
    family_aliases: dict[str, tuple[str, ...]] = {
        'bradykinin': ('bradykinin', 'rppgfspfr'),
        'leuenk': ('leuenk', 'leu_enk', 'yggfl'),
        # Ube2D3 datasets frequently use WT_nep2 / Mut_nep2 run naming.
        'ube2d3': ('ube2d3', 'wt_nep2', 'mut_nep2', 'wt_0murea', 'wt_8murea', 'mut_0murea', 'nep2'),
        'p1': ('p1',),
        'dbpb': ('dbpb',),
    }
    for family, aliases in family_aliases.items():
        if any(alias in text for alias in aliases):
            return family
    return ''


def _infer_hdx_label_from_run_name(run_name: str) -> str:
    tokens = [t for t in re.split(r'[^A-Z0-9]+', str(run_name or '').upper()) if t]
    if 'D' in tokens:
        return 'D'
    if 'UN' in tokens:
        return 'UN'
    if 'H' in tokens:
        return 'H'
    return 'UN'


_HDX_EXPOSURE_TIME_TOKEN_RE = re.compile(
    r'^(?:'
    r'\d+h(?:\d+m)?(?:\d+s)?'
    r'|\d+m(?:\d+s)?'
    r'|\d+s'
    r')$',
    flags=re.IGNORECASE,
)
_HDX_VIAL_TOKEN_RE = re.compile(r'^v\d+$', flags=re.IGNORECASE)


def _is_hdx_exposure_time_token(tok: object) -> bool:
    """Compact HDX exposure tokens from filenames, e.g. 11s, 1h21m, 2m30s, 27h."""
    s = str(tok or '').strip()
    if not s:
        return False
    return bool(_HDX_EXPOSURE_TIME_TOKEN_RE.fullmatch(s))


def _is_hdx_vial_token(tok: object) -> bool:
    s = str(tok or '').strip()
    if not s:
        return False
    return bool(_HDX_VIAL_TOKEN_RE.fullmatch(s))


def _is_hdx_exposure_vial_filename_tokens(tokens: object) -> bool:
    """
    Detect compact exposure + optional vial layout used by some HDX timecourse sets,
    e.g. 11s_V14_028 or 1h21m_V6_020. Other datasets keep legacy parsing unless
    this pattern is matched.
    """
    toks = [str(t or '').strip() for t in (tokens or []) if str(t or '').strip()]
    if not toks or (not _is_hdx_exposure_time_token(toks[0])):
        return False
    if len(toks) == 1:
        return True
    if len(toks) >= 2 and _is_hdx_vial_token(toks[1]):
        return True
    return False


_HDX_RUN_LABEL_TOKENS = frozenset({'UN', 'H', 'D'})


def _is_hdx_vial_bookkeeping_filename_tokens(tokens: object) -> bool:
    """
    Filename layouts where V## / trailing ### tokens are vial bookkeeping,
    not replicate indices. Includes exposure timecourse files plus controls
    like 3pep_UN_008, TDpH_V16_030, and UN_V18_014.
    """
    toks = [str(t or '').strip() for t in (tokens or []) if str(t or '').strip()]
    if not toks:
        return False
    if _is_hdx_exposure_vial_filename_tokens(toks):
        return True
    if len(toks) >= 3 and _is_hdx_vial_suffix_token(toks[-1]):
        prev = str(toks[-2] or '').strip().upper()
        if _is_hdx_vial_token(toks[-2]):
            return True
        if prev in _HDX_RUN_LABEL_TOKENS and _is_hdx_control_filename_token(toks[0]):
            return True
    return False


def _is_hdx_vial_suffix_token(tok: object) -> bool:
    s = str(tok or '').strip()
    if not s:
        return False
    return bool(re.fullmatch(r'\d{3}', s))


def _hdx_vial_id_from_filename_tokens(tokens: object) -> str:
    for tok in (tokens or []):
        if _is_hdx_vial_token(tok):
            return str(tok).strip().upper()
    return ''


def _hdx_vial_suffix_from_filename_tokens(tokens: object) -> str:
    toks = [str(t or '').strip() for t in (tokens or []) if str(t or '').strip()]
    if not toks:
        return ''
    for i, tok in enumerate(toks):
        if _is_hdx_vial_suffix_token(tok) and i > 0 and _is_hdx_vial_token(toks[i - 1]):
            return str(tok)
    if len(toks) >= 3 and _is_hdx_vial_suffix_token(toks[-1]):
        prev_up = str(toks[-2] or '').strip().upper()
        if prev_up in _HDX_RUN_LABEL_TOKENS and _is_hdx_control_filename_token(toks[0]):
            return str(toks[-1])
    if _is_hdx_exposure_vial_filename_tokens(toks):
        for tok in reversed(toks):
            if _is_hdx_vial_suffix_token(tok):
                return str(tok)
    return ''


_HDX_FILENAME_CONTROL_SPECS: dict[str, dict[str, str]] = {
    'tdph': {'control_type': 'TDpH', 'run_type': 'D'},
    'unph': {'control_type': 'UNpH', 'run_type': 'H_UN'},
    'blank': {'control_type': 'Blank', 'run_type': ''},
    'peptidetd': {'control_type': 'PeptideTD', 'run_type': 'D'},
    '3pep': {'control_type': 'Standards', 'run_type': 'H_UN'},
}


def _is_hdx_control_filename_token(tok: object) -> bool:
    key = re.sub(r'[^a-z0-9]+', '', str(tok or '').strip().lower())
    return bool(key and key in _HDX_FILENAME_CONTROL_SPECS)


def _hdx_control_info_from_filename_tokens(tokens: object) -> dict[str, str]:
    for tok in (tokens or []):
        key = re.sub(r'[^a-z0-9]+', '', str(tok or '').strip().lower())
        if key in _HDX_FILENAME_CONTROL_SPECS:
            return dict(_HDX_FILENAME_CONTROL_SPECS[key])
    return {}


def _scan_inventory_path_for_mzml(mzml_path: str) -> str:
    mp = str(mzml_path or '').strip()
    if not mp:
        return ''
    stem = os.path.splitext(os.path.basename(mp))[0]
    sidecar = os.path.join(os.path.dirname(mp), f'{stem}_scan_inventory.csv')
    return sidecar if os.path.isfile(sidecar) else ''


_TARGETED_PROTON_MASS_DA = 1.007276466812


def _targeted_averagine_composition(neutral_mass: float) -> dict[str, float]:
    """Senko averagine elemental composition scaled to neutral mass (no sequence)."""
    scale = max(0.1, float(neutral_mass) / 111.1254)
    return {
        'C': scale * 4.9384,
        'H': scale * 7.7583,
        'N': scale * 1.3577,
        'O': scale * 1.4238,
        'S': scale * 0.0417,
    }


def _targeted_na_isotope_envelope_from_mz(mz_mono: float, charge: int, n_isos: int = 4) -> tuple[list[float], list[float]]:
    """
    Theoretical precursor isotope envelope for targeted m/z-only inputs.
    m/z positions follow the scheduled target (M, M+1, ...); relative intensities
    come from brainpy isotopic_variants on averagine — same engine as
    pyHXExpress get_na_isotope(...), but without a peptide sequence.
    """
    z = int(charge)
    if z <= 0 or not np.isfinite(mz_mono) or float(mz_mono) <= 0:
        return [], []
    neutral_mass = (float(mz_mono) * z) - (z * _TARGETED_PROTON_MASS_DA)
    if not np.isfinite(neutral_mass) or neutral_mass <= 0:
        return [], []
    c13_step = 1.0033548378 / z
    mzs = [float(mz_mono) + k * c13_step for k in range(int(n_isos))]
    ints: list[float] = [1.0] + [0.0] * (len(mzs) - 1)
    try:
        from brainpy import isotopic_variants
        cluster = isotopic_variants(
            _targeted_averagine_composition(neutral_mass),
            npeaks=int(n_isos),
            charge=1,
        )
        parsed = [float(p.intensity) for p in cluster[:n_isos] if getattr(p, 'intensity', None) is not None]
        if parsed and float(parsed[0]) > 0:
            ints = parsed
    except Exception:
        n_c = max(0.1, float(neutral_mass) / 111.1254 * 4.9384)
        lam = max(0.0, min(8.0, n_c * 0.0107))
        ints = [1.0, float(lam), float(lam * lam / 2.0), float(lam * lam * lam / 6.0)][: len(mzs)]
    return mzs, ints


def _scheduled_ms2_windows_from_mzml(
    mzml_path: str,
    mz_round: int = 3,
) -> dict[float, dict[str, float]]:
    """
    Scan an mzML once and build a map of the **scheduled MS2 collection windows**
    per precursor m/z.

    For scheduled targeted PRM/PRM-like methods, the instrument only collects
    MS2 for each scheduled precursor over a defined RT range that brackets the
    expected elution peak (with extra padding to absorb peak drift). The min/max
    RT of MS2 scans for a given precursor m/z therefore equals the scheduled
    collection window — i.e. the ground-truth RT region where that analyte is
    actually being measured.

    Returns: {rounded_precursor_mz: {rt_min, rt_max, rt_median, n_scans, mz_raw}}
    """
    mp = str(mzml_path or '').strip()
    out: dict[float, dict[str, float]] = {}
    if not mp or not os.path.isfile(mp):
        return out
    try:
        from pyopenms import MzMLFile, MSExperiment  # type: ignore
    except Exception:
        return out
    try:
        exp = MSExperiment()
        MzMLFile().load(mp, exp)
    except Exception:
        return out
    buckets: dict[float, list[tuple[float, float]]] = {}
    try:
        for spec in exp:
            try:
                if int(spec.getMSLevel()) != 2:
                    continue
            except Exception:
                continue
            try:
                precs = spec.getPrecursors()
            except Exception:
                precs = []
            if not precs:
                continue
            try:
                pmz = float(precs[0].getMZ())
            except Exception:
                continue
            if not np.isfinite(pmz) or pmz <= 0:
                continue
            try:
                rt = float(spec.getRT())
            except Exception:
                continue
            if not np.isfinite(rt) or rt < 0:
                continue
            key = round(pmz, int(mz_round))
            buckets.setdefault(key, []).append((rt, pmz))
    except Exception:
        return out
    for key, items in buckets.items():
        if not items:
            continue
        rts = np.asarray([v[0] for v in items], dtype=float)
        mzs = np.asarray([v[1] for v in items], dtype=float)
        out[key] = {
            'rt_min': float(np.nanmin(rts)),
            'rt_max': float(np.nanmax(rts)),
            'rt_median': float(np.nanmedian(rts)),
            'n_scans': int(rts.size),
            'mz_raw': float(np.nanmedian(mzs)),
        }
    return out


def _lookup_scheduled_window(
    windows: dict[float, dict[str, float]],
    target_mz: float,
    tol_da: float = 0.01,
) -> dict[str, float] | None:
    """Find the scheduled MS2 window whose precursor m/z best matches target_mz."""
    if not windows or not np.isfinite(target_mz) or target_mz <= 0:
        return None
    best_key: float | None = None
    best_diff = float('inf')
    for key in windows.keys():
        d = abs(float(key) - float(target_mz))
        if d <= float(tol_da) and d < best_diff:
            best_diff = d
            best_key = key
    if best_key is None:
        for key in windows.keys():
            d = abs(float(key) - float(target_mz))
            if d <= max(0.05, float(tol_da) * 5.0) and d < best_diff:
                best_diff = d
                best_key = key
    if best_key is None:
        return None
    return dict(windows[best_key])


def _ms1_apex_rt_sec_from_mzml(
    mzml_path: str,
    mz_mono: float,
    charge: int,
    ppm_tol: float = 20.0,
    rt_window: tuple[float, float] | None = None,
    window_pad_sec: float = 5.0,
) -> tuple[float | None, str]:
    """
    OpenMS MS1 XIC apex RT for a targeted precursor m/z, optionally constrained
    to a scheduled RT window (so we don't latch onto unrelated compounds that
    share the nominal m/z elsewhere in the gradient).

    Returns: (apex_rt_sec | None, method_label)
        method_label ∈ {
            'constrained_apex',   # MS1 apex found inside the scheduled window
            'global_apex',        # No window provided; global MS1 argmax
            'no_signal_in_window',# Window provided but no MS1 signal inside it
            'no_signal',          # No MS1 signal anywhere
            'unavailable',        # mzML / chromatogram extraction failed
        }
    """
    mp = str(mzml_path or '').strip()
    if not mp or not os.path.isfile(mp):
        return None, 'unavailable'
    iso_mzs, iso_weights = _targeted_na_isotope_envelope_from_mz(mz_mono, charge, n_isos=4)
    if not iso_mzs:
        return None, 'unavailable'
    try:
        from visualization.chromatograms import extract_aligned_isotope_chromatograms
        rts, intensity_matrix, _ = extract_aligned_isotope_chromatograms(
            mp,
            iso_mzs,
            ppm_tolerance=float(ppm_tol),
            peak_matching_ppm_threshold=5.0,
        )
    except Exception:
        return None, 'unavailable'
    if rts is None or len(rts) == 0 or intensity_matrix is None or intensity_matrix.size == 0:
        return None, 'unavailable'
    mat = np.asarray(intensity_matrix, dtype=float)
    if mat.ndim != 2 or mat.shape[0] == 0:
        return None, 'unavailable'
    w = np.asarray(iso_weights[: mat.shape[1]], dtype=float)
    if w.size == 0 or not np.any(np.isfinite(w)):
        w = np.ones(min(4, mat.shape[1]), dtype=float)
    w = np.where(np.isfinite(w) & (w > 0), w, 0.0)
    if float(w.sum()) <= 0:
        w = np.ones(mat.shape[1], dtype=float)
    w = w / float(w.sum())
    total = np.nansum(mat[:, : len(w)] * w[np.newaxis, :], axis=1)
    rts_arr = np.asarray(rts, dtype=float)
    if total.size == 0 or not np.any(np.isfinite(total) & (total > 0)):
        return None, 'no_signal'
    if rt_window is not None:
        try:
            lo = float(rt_window[0]) - float(window_pad_sec)
            hi = float(rt_window[1]) + float(window_pad_sec)
        except Exception:
            lo = hi = None  # type: ignore
        if lo is not None and hi is not None and np.isfinite(lo) and np.isfinite(hi) and hi > lo:
            mask = (rts_arr >= lo) & (rts_arr <= hi) & np.isfinite(total) & (total > 0)
            if np.any(mask):
                idxs = np.nonzero(mask)[0]
                apex_idx = int(idxs[int(np.argmax(total[idxs]))])
                apex_rt = float(rts_arr[apex_idx])
                if np.isfinite(apex_rt) and apex_rt > 0:
                    return apex_rt, 'constrained_apex'
            return None, 'no_signal_in_window'
    apex_idx = int(np.nanargmax(total))
    apex_rt = float(rts_arr[apex_idx])
    if not (np.isfinite(apex_rt) and apex_rt > 0):
        return None, 'no_signal'
    return apex_rt, 'global_apex'


def _round_target_mz(value: object) -> str:
    try:
        num = float(value)
    except Exception:
        return str(value or '').strip()
    txt = f'{num:.3f}'
    return txt.rstrip('0').rstrip('.')


def _targeted_activation_method_label(ms_level: object, source_fragmentation_scan_type: object) -> str:
    try:
        ms = int(float(ms_level))
    except Exception:
        return ''
    sft = str(source_fragmentation_scan_type or '').strip().lower()
    if ms == 2:
        if sft == 'etd_only':
            return 'ETD'
        if sft in {
            'true_ethcd',
            'likely_ethcd_hcd_tagged',
            'etd_hcd_no_supp_ambiguous',
            'etd_plus_supp_hcd',
        }:
            return 'ETDsuppHCDplus2'
    if ms == 3 and sft == 'hcd_only':
        return 'scramHCD'
    return ''


def _targeted_charge_label(value: object) -> str:
    try:
        num = int(float(value))
    except Exception:
        return ''
    return str(num) if num > 0 else ''


def _targeted_mode_setting(series: pd.Series) -> str:
    vals = [str(v).strip() for v in series.dropna().tolist() if str(v).strip()]
    if not vals:
        return ''
    try:
        return str(pd.Series(vals).mode().iloc[0])
    except Exception:
        return vals[0]


def _targeted_join_unique_values(series: pd.Series) -> str:
    vals: list[str] = []
    for raw in series.dropna().tolist():
        txt = str(raw).strip()
        if not txt:
            continue
        if txt not in vals:
            vals.append(txt)
    return ';'.join(vals)


def _strip_redundant_supplemental_hcd(setting: str) -> str:
    """
    Remove `supplemental_hcd=N` from an activation_settings_by_type expression
    when an `hcd=N` term is already present. The two CV terms (MS:1000422 and
    MS:1002678) carry the same beam-type CID energy for ETDsuppHCDplus2 / scramHCD scans.
    """
    txt = str(setting or '').strip()
    if not txt or ';' not in txt:
        return txt
    parts = [p.strip() for p in txt.split(';') if p.strip()]
    has_hcd = any(p.lower().startswith('hcd=') for p in parts)
    if not has_hcd:
        return ';'.join(parts)
    kept = [p for p in parts if not p.lower().startswith('supplemental_hcd=')]
    return ';'.join(kept)


def _targeted_activation_setting_from_parts(
    etd_setting: object = '',
    supp_hcd_plus2_setting: object = '',
    scram_hcd_setting: object = '',
) -> str:
    """Build a single activation_setting string from parsed setting columns."""
    parts: list[str] = []
    etd = str(etd_setting or '').strip()
    supp = str(supp_hcd_plus2_setting or '').strip()
    scram = str(scram_hcd_setting or '').strip()
    if etd:
        parts.append(f'etd={etd}')
    if supp:
        parts.append(f'suppHCDplus2={supp}')
    if scram:
        parts.append(f'scram_hcd={scram}')
    return ';'.join(parts)


def _parse_activation_settings_by_type(text: object) -> dict[str, str]:
    out = {'etd_setting': '', 'hcd_setting': ''}
    txt = str(text or '').strip()
    if not txt:
        return out
    for part in txt.split(';'):
        piece = str(part or '').strip()
        if not piece or '=' not in piece:
            continue
        key, val = piece.split('=', 1)
        key_norm = re.sub(r'[^a-z0-9]+', '_', str(key or '').strip().lower()).strip('_')
        val_norm = str(val or '').strip()
        if key_norm == 'etd':
            out['etd_setting'] = val_norm
        elif key_norm in {'hcd', 'supplemental_hcd', 'supp_hcd', 'supplemental_cid'}:
            if not out['hcd_setting']:
                out['hcd_setting'] = val_norm
    return out


def _targeted_join_parsed_settings(values: list[str], key: str) -> str:
    parsed_vals: list[str] = []
    for txt in values:
        parsed = _parse_activation_settings_by_type(txt)
        val = str(parsed.get(key, '') or '').strip()
        if val and val not in parsed_vals:
            parsed_vals.append(val)
    return ';'.join(parsed_vals)


_TARGETED_MZML_MATRIX_COLUMNS: list[str] = [
    'target_peptide_mz',
    'peptide_charge',
    'ms_level',
    'etd_setting',
    'suppHCDplus2_setting',
    'scram_hcd_setting',
    'condition_scan_count',
    'activation_provenance',
    'filter_string_example',
    'run_n_ms1',
    'run_n_ms2',
    'run_rt_span_sec',
]


def _ms2_fragmentation_summary_path_for_mzml(mzml_path: str) -> str:
    mp = str(mzml_path or '').strip()
    if not mp:
        return ''
    stem = os.path.splitext(os.path.basename(mp))[0]
    sidecar = os.path.join(
        os.path.dirname(mp),
        f'{stem}_ms2_per_run_fragmentation_charge_summary.csv',
    )
    return sidecar if os.path.isfile(sidecar) else ''


def _targeted_run_metadata_from_scan_inventory(inv_path: str) -> dict[str, str]:
    out = {
        'run_n_ms1': '',
        'run_n_ms2': '',
        'run_rt_span_sec': '',
    }
    if not inv_path or not os.path.isfile(inv_path):
        return out
    try:
        dfi = pd.read_csv(inv_path, usecols=lambda c: c in {'ms_level', 'rt_seconds'})
    except Exception:
        return out
    if dfi is None or dfi.empty:
        return out
    if 'ms_level' in dfi.columns:
        ms = pd.to_numeric(dfi['ms_level'], errors='coerce')
        out['run_n_ms1'] = str(int((ms == 1).sum()))
        out['run_n_ms2'] = str(int(ms.isin([2, 3]).sum()))
    if 'rt_seconds' in dfi.columns:
        rt = pd.to_numeric(dfi['rt_seconds'], errors='coerce').dropna()
        if not rt.empty:
            out['run_rt_span_sec'] = str(round(float(rt.max() - rt.min()), 3))
    return out


def _targeted_ms2_fragmentation_summary_text(mzml_path: str) -> str:
    summary_path = _ms2_fragmentation_summary_path_for_mzml(mzml_path)
    if not summary_path:
        return ''
    try:
        sdf = pd.read_csv(summary_path)
    except Exception:
        return ''
    if sdf is None or sdf.empty:
        return ''
    parts: list[str] = []
    for _, row in sdf.iterrows():
        frag = str(row.get('source_fragmentation_scan_type', '') or '').strip()
        charge = str(row.get('charge_state', '') or '').strip()
        count = str(row.get('scan_count', '') or '').strip()
        if not frag:
            continue
        parts.append(f'{frag}|z{charge}|n={count}')
    return ' || '.join(parts)


def _targeted_condition_settings_from_group(grp: pd.DataFrame) -> dict[str, str]:
    setting_col = (
        'activation_settings_by_type'
        if 'activation_settings_by_type' in grp.columns
        else 'activation_setting_observed'
    )
    settings_texts = (
        grp[setting_col].dropna().astype(str).tolist()
        if setting_col in grp.columns
        else []
    )
    parsed_etd = _targeted_join_parsed_settings(settings_texts, 'etd_setting')
    parsed_hcd = _targeted_join_parsed_settings(settings_texts, 'hcd_setting')

    def _col(name: str) -> pd.Series:
        return grp[name] if name in grp.columns else pd.Series([], dtype=str)

    out = {
        'ms_level': _targeted_mode_setting(_col('ms_level_num') if 'ms_level_num' in grp.columns else _col('ms_level')),
        'etd_setting': parsed_etd or _targeted_join_unique_values(
            _col('etd_setting_observed') if 'etd_setting_observed' in grp.columns else _col('etd_setting_numeric_from_filter')
        ),
        'hcd_setting': parsed_hcd,
        'activation_provenance': _targeted_join_unique_values(_col('activation_provenance')),
        'condition_scan_count': str(int(len(grp))),
        'filter_string_example': _targeted_mode_setting(_col('filter_string_excerpt')),
    }
    return {k: str(v or '').strip() for k, v in out.items()}


def _extract_targeted_metadata_from_scan_inventory(
    inv_path: str,
    mzml_path: str = '',
) -> dict[str, object]:
    """
    Derive targeted peptide precursor m/z list, orbitrap fragmentation
    conditions (ETD / ETDsuppHCDplus2 / scramHCD), and all observable mzML settings
    from a run scan-inventory sidecar.
    """
    out: dict[str, object] = {
        'targeted_peptides': '',
        'conditions': [],
        'run_metadata': _targeted_run_metadata_from_scan_inventory(inv_path),
        'run_ms2_fragmentation_summary': _targeted_ms2_fragmentation_summary_text(mzml_path),
    }
    if not inv_path or not os.path.isfile(inv_path):
        return out
    try:
        dfi = pd.read_csv(inv_path)
    except Exception:
        return out
    if dfi is None or dfi.empty:
        return out

    required = {
        'ms_level',
        'analyzer_class',
        'selected_ion_mz',
        'source_fragmentation_scan_type',
    }
    if not required.issubset(set(dfi.columns)):
        return out

    pep = dfi[dfi['analyzer_class'].astype(str).str.lower() == 'orbitrap'].copy()
    pep['ms_level_num'] = pd.to_numeric(pep['ms_level'], errors='coerce')
    pep['selected_ion_mz_num'] = pd.to_numeric(pep['selected_ion_mz'], errors='coerce')
    pep = pep[pep['ms_level_num'].isin([2, 3])]
    pep = pep[pep['selected_ion_mz_num'] > 300]
    if pep.empty:
        return out

    ms2 = pep[pep['ms_level_num'] == 2]
    ms2_targets = ms2[
        ms2['source_fragmentation_scan_type'].astype(str).isin(['etd_only', 'true_ethcd'])
    ]
    mz_vals = sorted(
        {
            _round_target_mz(v)
            for v in ms2_targets['selected_ion_mz_num'].dropna().tolist()
            if _round_target_mz(v)
        },
        key=lambda s: float(s),
    )
    if mz_vals:
        out['targeted_peptides'] = ';'.join(mz_vals)

    charge_col = (
        'precursor_charge_state'
        if 'precursor_charge_state' in ms2_targets.columns
        else 'charge_state'
    )

    mz_to_charge: dict[str, str] = {}
    mz_to_ms2_method: dict[str, str] = {}
    mz_to_ms2_hcd: dict[str, str] = {}
    if not ms2_targets.empty:
        ms2_targets = ms2_targets.copy()
        ms2_targets['target_mz_key'] = ms2_targets['selected_ion_mz_num'].apply(_round_target_mz)
        for mz_key, grp_mz in ms2_targets.groupby('target_mz_key'):
            mz_str = str(mz_key or '').strip()
            if not mz_str:
                continue
            if charge_col in grp_mz.columns:
                chg = _targeted_charge_label(_targeted_mode_setting(grp_mz[charge_col]))
                if chg:
                    mz_to_charge[mz_str] = chg
            sft_mode = _targeted_mode_setting(grp_mz['source_fragmentation_scan_type'])
            ms2_method = _targeted_activation_method_label(2, sft_mode)
            if ms2_method:
                mz_to_ms2_method[mz_str] = ms2_method
            if ms2_method == 'ETDsuppHCDplus2' and 'activation_settings_by_type' in grp_mz.columns:
                settings_texts_mz = grp_mz['activation_settings_by_type'].dropna().astype(str).tolist()
                ms2_hcd = _targeted_join_parsed_settings(settings_texts_mz, 'hcd_setting')
                if ms2_hcd:
                    mz_to_ms2_hcd[mz_str] = ms2_hcd

    pep['activation_method'] = pep.apply(
        lambda r: _targeted_activation_method_label(
            r.get('ms_level_num'),
            r.get('source_fragmentation_scan_type'),
        ),
        axis=1,
    )
    pep = pep[pep['activation_method'].astype(str).str.len() > 0]
    if pep.empty:
        return out

    setting_col = (
        'activation_settings_by_type'
        if 'activation_settings_by_type' in pep.columns
        else 'activation_setting_observed'
    )
    if charge_col not in pep.columns:
        charge_col = (
            'precursor_charge_state'
            if 'precursor_charge_state' in pep.columns
            else 'charge_state'
        )

    conditions: list[dict[str, str]] = []
    pep = pep.copy()
    pep['target_mz_key'] = pep['selected_ion_mz_num'].apply(_round_target_mz)

    for act in ('ETD', 'ETDsuppHCDplus2', 'scramHCD'):
        sub = pep[pep['activation_method'] == act]
        if sub.empty:
            continue
        group_cols = ['target_mz_key']
        if setting_col in sub.columns:
            group_cols.append(setting_col)
        for group_key, grp in sub.groupby(group_cols, dropna=False):
            if isinstance(group_key, tuple):
                mz_key = str(group_key[0] or '').strip()
                setting = str(group_key[1]).strip() if len(group_key) > 1 else _targeted_mode_setting(grp[setting_col])
            else:
                mz_key = str(group_key or '').strip()
                setting = _targeted_mode_setting(grp[setting_col]) if setting_col in grp.columns else ''
            if not mz_key:
                continue
            chg = mz_to_charge.get(mz_key, '')
            if not chg and charge_col in grp.columns:
                chg = _targeted_charge_label(_targeted_mode_setting(grp[charge_col]))
            method_label = act
            if act == 'scramHCD':
                ms2_method = mz_to_ms2_method.get(mz_key, '')
                if ms2_method:
                    method_label = f'scramHCD_{ms2_method}'
                else:
                    method_label = 'scramHCD_ETD' if str(chg) in {'3', '4'} else 'scramHCD'
            cond = {
                'activation_method': method_label,
                'peptide_charge': chg,
                'target_peptide_mz': mz_key,
            }
            cond.update(_targeted_condition_settings_from_group(grp))
            cond['activation_method'] = method_label
            hcd_raw = str(cond.pop('hcd_setting', '') or '').strip()
            supp_val = ''
            scram_val = ''
            if method_label == 'ETDsuppHCDplus2':
                supp_val = hcd_raw
            elif method_label.startswith('scramHCD_ETDsuppHCDplus2'):
                scram_val = hcd_raw
                supp_val = mz_to_ms2_hcd.get(mz_key, '')
            elif method_label.startswith('scramHCD'):
                scram_val = hcd_raw
            cond['suppHCDplus2_setting'] = supp_val
            cond['scram_hcd_setting'] = scram_val
            cond['activation_setting'] = _targeted_activation_setting_from_parts(
                cond.get('etd_setting'),
                supp_val,
                scram_val,
            )
            # MS3 scramHCD scans can have empty activation_provenance in inventory output.
            # Keep this explicit in the matrix instead of surfacing as ambiguous "none".
            if (not str(cond.get('activation_provenance') or '').strip()) and method_label.startswith('scramHCD'):
                cond['activation_provenance'] = 'ms3_hcd'
            conditions.append(cond)

    dedup: list[dict[str, str]] = []
    seen: set[tuple[str, str, str, str]] = set()
    for cond in conditions:
        key = (
            str(cond.get('activation_method', '') or ''),
            str(cond.get('peptide_charge', '') or ''),
            str(cond.get('activation_setting', '') or ''),
            str(cond.get('target_peptide_mz', '') or ''),
        )
        if key in seen:
            continue
        seen.add(key)
        dedup.append(cond)

    order = {
        'ETD': 0,
        'ETDsuppHCDplus2': 1,
        'scramHCD_ETD': 2,
        'scramHCD_ETDsuppHCDplus2': 3,
        'scramHCD': 4,
    }

    def _cond_sort_key(item: dict[str, str]) -> tuple[float, int, int, str]:
        mz_txt = str(item.get('target_peptide_mz', '') or '')
        try:
            mz_num = float(mz_txt) if mz_txt else 0.0
        except Exception:
            mz_num = 0.0
        chg_txt = str(item.get('peptide_charge', '') or '')
        try:
            chg_num = int(chg_txt) if chg_txt else 99
        except Exception:
            chg_num = 99
        act = str(item.get('activation_method', '') or '')
        return (mz_num, chg_num, order.get(act, 9), str(item.get('activation_setting', '') or ''))

    out['conditions'] = sorted(dedup, key=_cond_sort_key)
    return out


def _should_use_targeted_scan_inventory_enrichment(
    term_list: list[str],
    meta: dict[str, object],
) -> bool:
    if _is_hdx_exposure_vial_filename_tokens(term_list):
        return True
    if _hdx_control_info_from_filename_tokens(term_list):
        return True
    for tok in (term_list or []):
        key = re.sub(r'[^a-z0-9]+', '', str(tok or '').strip().lower())
        if key == '3pep':
            return True
    targeted = str(meta.get('targeted_peptides') or '').strip()
    n_targets = len([part for part in targeted.split(';') if str(part).strip()])
    return n_targets >= 8


def _targeted_matrix_row_payloads_from_mzml(
    mzml_path: str,
    key_payload: dict[str, str],
    run_type_norm: str,
    basename: str,
    term_list: list[str] | None = None,
) -> list[dict[str, str]]:
    inv_path = _scan_inventory_path_for_mzml(mzml_path)
    meta = _extract_targeted_metadata_from_scan_inventory(inv_path, mzml_path)
    if not _should_use_targeted_scan_inventory_enrichment(list(term_list or []), meta):
        return []
    conditions = meta.get('conditions') or []
    targeted_peptides = str(meta.get('targeted_peptides') or '').strip()
    run_meta = meta.get('run_metadata') if isinstance(meta.get('run_metadata'), dict) else {}
    run_summary = str(meta.get('run_ms2_fragmentation_summary') or '').strip()
    if not conditions and not targeted_peptides:
        return []

    def _apply_mzml_fields(row: dict[str, str], cond: dict[str, str] | None = None) -> dict[str, str]:
        out_row = dict(row)
        for key in _TARGETED_MZML_MATRIX_COLUMNS:
            if isinstance(cond, dict):
                val = str(cond.get(key, '') or '').strip()
                if val:
                    out_row[key] = val
                    continue
            if key in run_meta:
                out_row[key] = str(run_meta.get(key, '') or '').strip()
            elif key == 'run_ms2_fragmentation_summary':
                out_row[key] = run_summary
        return out_row

    if not conditions:
        return [_apply_mzml_fields(dict(key_payload), None)]

    out_rows: list[dict[str, str]] = []
    for cond in conditions:
        if not isinstance(cond, dict):
            continue
        row = _apply_mzml_fields(dict(key_payload), cond)
        row['activation_method'] = str(cond.get('activation_method') or '').strip()
        row['activation_setting'] = str(cond.get('activation_setting') or '').strip()
        chg = str(cond.get('peptide_charge') or '').strip()
        if chg:
            row['peptide_charge'] = chg
        mz = str(cond.get('target_peptide_mz') or '').strip()
        if mz:
            row['target_peptide_mz'] = mz
        out_rows.append(row)
    return out_rows


def _derive_protein_id_from_name_scope(scope_dir: str) -> str:
    """
    Derive analyte/protein ID from the selected Name-index directory basename,
    e.g. ube2d3_may19 -> ube2d3, p1_thermo -> p1.
    """
    base = os.path.basename(os.path.abspath(str(scope_dir or '').strip().rstrip(os.sep)))
    if not base:
        return ''
    lead = str(base).split('_')[0].strip().lower()
    lead = re.sub(r'[^a-z0-9]+', '', lead)
    if not lead:
        return ''
    aliases = {
        'ub2d3': 'ube2d3',
        'ube2d3': 'ube2d3',
    }
    return aliases.get(lead, lead)


def _normalize_hdx_label_value(value: object) -> str:
    tok = str(value or '').strip().upper()
    if tok in {'D', 'UN', 'H'}:
        return tok
    if tok in {'TD', 'FULLDEUT', 'FULL_DEUT', 'MAXDEUT', 'MAX_DEUT'}:
        return 'D'
    if tok in {'UNDEUT', 'UNDEUTERATED', 'H_UN', 'HU'}:
        return 'UN'
    if tok in {'U', 'UND', 'UNL', 'UNLABELED', 'UNLABELLED', 'LIGHT', 'L'}:
        return 'UN'
    if tok in {'DEUT', 'DEUTERATED', 'HEAVY', 'HDX', 'D2O'}:
        return 'D'
    return ''


def _map_hdx_label_to_pyhx_state(value: object) -> str:
    """Map app labels/run_type aliases to pyHXExpress state tokens."""
    tok = str(value or '').strip().upper()
    if tok in {'TD', 'UNDEUT'}:
        return tok.lower() if tok == 'UNDEUT' else tok
    norm = _normalize_hdx_label_value(tok)
    if norm == 'D':
        return 'TD'
    # Treat H and UN as undeuterated-side inputs for pyHXExpress.
    return 'undeut'


def _resolve_hdx_labels_from_source(
    source_mzml: pd.Series,
    existing_labels: pd.Series | None = None,
    source_mzml_path: pd.Series | None = None,
    working_dir: str = '',
) -> pd.Series:
    """
    Resolve per-row HDX labels with robust fallback:
    1) normalize existing labels if present,
    2) infer from source_mzml run names when missing/unknown,
    3) if existing labels collapsed to all-H but run names clearly contain D/UN context,
       replace with inferred labels.
    """
    src = source_mzml.astype(str)
    run_label_map = _load_name_mapping_hdx_label_by_run(working_dir) if str(working_dir or '').strip() else {}
    if run_label_map:
        src_path = source_mzml_path.astype(str) if source_mzml_path is not None else pd.Series([''] * len(src), index=src.index)
        inferred = pd.Series(
            [
                _resolve_hdx_label_from_name_map(src.iloc[i], src_path.iloc[i], run_label_map)
                for i in range(len(src))
            ],
            index=src.index,
        ).astype(str).str.upper()
    else:
        inferred = src.apply(_infer_hdx_label_from_run_name).astype(str).str.upper()
    inferred = inferred.where(inferred.isin(['D', 'UN', 'H']), 'UN')

    if existing_labels is None:
        return inferred

    existing_norm = existing_labels.apply(_normalize_hdx_label_value).astype(str).str.upper()
    out = existing_norm.copy()
    missing_mask = out == ''
    if missing_mask.any():
        out.loc[missing_mask] = inferred.loc[missing_mask]
    out = out.where(out.isin(['D', 'UN', 'H']), 'UN')

    # Recover common collapse case where imported labels are all H but run names encode D/UN.
    out_vals = set(out.dropna().astype(str).tolist())
    inferred_vals = set(inferred.dropna().astype(str).tolist())
    if out_vals == {'H'} and (('D' in inferred_vals) or ('UN' in inferred_vals)):
        out = inferred
        out = out.where(out.isin(['D', 'UN', 'H']), 'UN')
    return out


def _infer_rep_from_run_name(run_name: str) -> int:
    m = re.search(r'(?:^|[_-])rep(?:licate)?[_-]?(\d+)(?:$|[_-])', str(run_name or ''), flags=re.IGNORECASE)
    if not m:
        return 1
    try:
        v = int(m.group(1))
        return v if v > 0 else 1
    except Exception:
        return 1


def _scan_number_from_spectrum_id(spec_id: str) -> int | None:
    sid = str(spec_id or '')
    m = re.search(r'scan=(\d+)', sid, flags=re.IGNORECASE)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            pass
    # Some mzML writers use index=0-based IDs instead of explicit scan numbers.
    m2 = re.search(r'index=(\d+)', sid, flags=re.IGNORECASE)
    if m2:
        try:
            return int(m2.group(1)) + 1
        except Exception:
            pass
    return None


def _infer_fragmentation_setting_from_run_name(run_name: str) -> str:
    """
    Best-effort extraction of method/setting token for UN-vs-D fragmentation summaries.
    Examples: UVPD_1024ms, ETD50ms, CID_30ms.
    """
    s = str(run_name or '').upper()
    if not s:
        return ''

    method_match = re.search(r'(UVPD|ETD|CID|HCD|ECD|EID)', s, flags=re.IGNORECASE)
    if not method_match:
        return ''
    method = str(method_match.group(1)).upper()

    # Parse flexible numeric setting patterns:
    # - UVPD_1024
    # - ETD50
    # - ..._UVPD_Z2_0008ms
    # - ..._D_UVPD_Z3_1024ms
    tokens = [t for t in re.split(r'[^A-Z0-9]+', s) if t]
    setting_num: int | None = None

    # 1) If a method token carries an inline number (e.g., ETD50), use it.
    inline_matches: list[int] = []
    for tok in tokens:
        m_inline = re.fullmatch(r'(?:UVPD|ETD|CID|HCD|ECD|EID)(\d+)', tok, flags=re.IGNORECASE)
        if m_inline:
            try:
                inline_matches.append(int(m_inline.group(1)))
            except Exception:
                pass
    if inline_matches:
        setting_num = inline_matches[0]

    # 2) Otherwise, use a numeric token near the nearest method occurrence,
    # preferring the method token that has a following numeric setting.
    if setting_num is None:
        method_indices = [i for i, t in enumerate(tokens) if t == method or re.fullmatch(r'(?:UVPD|ETD|CID|HCD|ECD|EID)\d+', t)]
        for meth_idx in reversed(method_indices):
            window = tokens[meth_idx + 1 : meth_idx + 6]
            for tok in window:
                # skip charge tokens and obvious non-setting duration/meta tokens
                if re.fullmatch(r'Z\d+', tok):
                    continue
                if re.fullmatch(r'\d+MIN', tok):
                    continue
                m_num = re.fullmatch(r'(\d+)(?:MS)?', tok)
                if m_num:
                    try:
                        setting_num = int(m_num.group(1))
                        break
                    except Exception:
                        pass
            if setting_num is not None:
                break

    # 3) Last resort: any standalone numeric+ms token in name.
    if setting_num is None:
        m_any = re.search(r'(?:^|[_-])(\d+)(?:MS)(?:$|[_-])', s, flags=re.IGNORECASE)
        if m_any:
            try:
                setting_num = int(m_any.group(1))
            except Exception:
                setting_num = None

    if setting_num is None:
        return method
    return f'{method}_{setting_num:04d}ms'


def _infer_fragmentation_setting_from_inventory(mzml_path: str) -> str:
    """
    Prefer scan-inventory/metadata-derived activation setting over filename parsing.
    Falls back to run-name parser when inventory fields are unavailable.
    """
    run_stem = os.path.splitext(os.path.basename(str(mzml_path or '')))[0]
    mp = str(mzml_path or '').strip()
    if mp and os.path.isfile(mp):
        try:
            from workflow_scripts.mzml_activation_utils import parse_mzml_activation_metadata

            meta = parse_mzml_activation_metadata(Path(mp))
            method = str(meta.get('activation_method_from_name') or '').strip().upper()
            if method:
                setting_raw = meta.get('activation_setting_from_name')
                if setting_raw is not None:
                    try:
                        return f'{method}_{int(round(float(setting_raw))):04d}ms'
                    except Exception:
                        return method
                return method
        except Exception:
            pass
    inv = os.path.join(os.path.dirname(str(mzml_path or '')), run_stem + '_scan_inventory.csv')
    if not os.path.isfile(inv):
        return _infer_fragmentation_setting_from_run_name(run_stem)
    try:
        cols = [
            'activation_setting_observed',
            'activation_setting_numeric_from_filter',
            'activation_method_terms',
            'activation_types_observed',
        ]
        dfi = pd.read_csv(inv, usecols=lambda c: c in cols)
    except Exception:
        return _infer_fragmentation_setting_from_run_name(run_stem)
    if dfi is None or dfi.empty:
        return _infer_fragmentation_setting_from_run_name(run_stem)

    method = ''
    for c in ['activation_method_terms', 'activation_types_observed']:
        if c in dfi.columns:
            vals = dfi[c].dropna().astype(str).tolist()
            for v in vals:
                m = re.search(r'(ETD|ETHCD|UVPD|ECD|EID|HCD|CID)', str(v).upper())
                if m:
                    method = str(m.group(1)).upper()
                    if method == 'ETHCD':
                        method = 'ETD'
                    break
            if method:
                break
    if not method:
        # Conservative fallback: keep existing parser behavior for method only.
        base = _infer_fragmentation_setting_from_run_name(run_stem)
        method = str(base).split('_')[0] if base else ''

    setting_num = None
    if 'activation_setting_numeric_from_filter' in dfi.columns:
        num_series = pd.to_numeric(dfi['activation_setting_numeric_from_filter'], errors='coerce').dropna()
        if not num_series.empty:
            try:
                setting_num = int(round(float(num_series.median())))
            except Exception:
                setting_num = None
    if setting_num is None and 'activation_setting_observed' in dfi.columns:
        txt_vals = dfi['activation_setting_observed'].dropna().astype(str).tolist()
        for tv in txt_vals:
            m = re.search(r'(\d+)', tv)
            if m:
                try:
                    setting_num = int(m.group(1))
                    break
                except Exception:
                    pass

    if not method:
        return _infer_fragmentation_setting_from_run_name(run_stem)
    if setting_num is None:
        # Inventory may provide method but omit numeric setting; defer to run-name parser
        # to preserve distinctions like D_UVPD_Z2_0008ms vs D_UVPD_Z2_0016ms.
        fallback = _infer_fragmentation_setting_from_run_name(run_stem)
        return fallback or method
    return f'{method}_{int(setting_num):04d}ms'


def _load_name_mapping_run_ids(working_dir: str) -> set[str]:
    run_ids: set[str] = set()
    selected_csv = _selected_inventory_check_csv_path(working_dir)
    if not selected_csv or not os.path.isfile(selected_csv):
        return run_ids
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return run_ids
    for col in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name'):
        if col not in df.columns:
            continue
        for v in df[col].dropna().astype(str).tolist():
            for tok in _split_semicolon_tokens(v):
                stem = os.path.splitext(os.path.basename(str(tok or '').strip()))[0]
                if stem:
                    run_ids.add(stem)
    return run_ids


def _run_id_norm(value: object) -> str:
    s = str(value or '').strip()
    if not s:
        return ''
    s = os.path.splitext(os.path.basename(s))[0]
    return re.sub(r'[^a-z0-9]+', '', s.lower())


def _run_id_alias_norms(run_id_text: str) -> set[str]:
    rid = os.path.splitext(os.path.basename(str(run_id_text or '').strip()))[0]
    if not rid:
        return set()
    toks = [t for t in re.split(r'[_\s]+', rid) if t]
    if not toks:
        return set()

    def _dedupe_adjacent_tokens(tokens: list[str]) -> list[str]:
        out: list[str] = []
        prev = ''
        for t in tokens:
            if not t:
                continue
            if t.lower() == prev.lower():
                continue
            out.append(t)
            prev = t
        return out

    out: set[str] = set()
    for vv in [toks, _dedupe_adjacent_tokens(toks)]:
        for i in range(len(vv)):
            alias = '_'.join(vv[i:])
            n = _run_id_norm(alias)
            if n:
                out.add(n)
    full = _run_id_norm(rid)
    if full:
        out.add(full)
    return out


def _load_name_mapping_alias_groups(working_dir: str) -> list[set[str]]:
    """
    Load accepted Name-tab mapping as alias groups of normalized run-id variants.
    Each type-entry contributes one alias group spanning its run_ids.
    """
    groups: list[set[str]] = []
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return groups
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return groups
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return groups
    for _, row in df.iterrows():
        g: set[str] = set()
        for col in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name'):
            if col not in df.columns:
                continue
            for tok in _split_semicolon_tokens(row.get(col, '')):
                stem = os.path.splitext(os.path.basename(str(tok or '').strip()))[0]
                g.update(_run_id_alias_norms(stem))
        if g:
            groups.append(g)
    return groups


def _activation_method_from_token_text(value: object) -> str:
    txt = str(value or '').strip()
    if not txt:
        return ''
    low = txt.lower()
    if low in {'uvpd', 'etd', 'cid', 'hcd', 'ecd', 'eid', 'ethcd'}:
        return 'EThcD' if low == 'ethcd' else low.upper()
    m = re.match(r'^(uvpd|etd|cid|hcd|ecd|eid|ethcd)\d*(?:ms)?$', low, flags=re.IGNORECASE)
    if m:
        g = str(m.group(1) or '').strip().lower()
        return 'EThcD' if g == 'ethcd' else g.upper()
    return ''


def _activation_setting_ms_from_token_text(value: object) -> float | None:
    """
    Parse activation setting token text into numeric milliseconds when possible.
    Examples: 16ms, UVPD16ms, ETD16.
    """
    txt = str(value or '').strip()
    if not txt:
        return None
    low = txt.lower()
    m = re.fullmatch(r'(\d+(?:\.\d+)?)\s*ms', low, flags=re.IGNORECASE)
    if not m:
        m = re.fullmatch(r'uvpd(\d+(?:\.\d+)?)\s*ms', low, flags=re.IGNORECASE)
    if not m:
        m = re.fullmatch(r'etd(\d+(?:\.\d+)?)', low, flags=re.IGNORECASE)
    if not m:
        return None
    try:
        return float(m.group(1))
    except Exception:
        return None


def _load_name_mapping_activation_method_by_run(working_dir: str) -> dict[str, str]:
    """
    Build normalized-run-id -> activation method map from accepted Name-tab mapping.
    Uses mapped `activation_method_from_name` token index per type entry when available.
    """
    out: dict[str, str] = {}
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return out
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return out
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return out
    for _, row in df.iterrows():
        meth = _activation_method_from_token_text(row.get('activation_method', ''))
        if not meth:
            meth = _activation_method_from_token_text(row.get('activation_method_from_name', ''))
        if not meth:
            continue
        for col in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name'):
            if col not in df.columns:
                continue
            for tok in _split_semicolon_tokens(row.get(col, '')):
                n_full = _run_id_norm(tok)
                if n_full and n_full not in out:
                    out[n_full] = meth
    return out


