def _load_name_mapping_precursor_charge_by_run(working_dir: str) -> dict[str, int]:
    """
    Build normalized-run-id -> precursor/peptide charge from the selected
    terminology inventory check CSV.
    """
    out: dict[str, int] = {}
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return out
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return out
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return out
    if df is None or df.empty:
        return out

    def _z_from_value(v: object) -> int | None:
        try:
            fv = float(v)
            if np.isfinite(fv):
                iv = int(round(fv))
                if iv > 0:
                    return int(iv)
        except Exception:
            pass
        s = str(v or '').strip()
        if not s:
            return None
        m = re.search(r'(?i)(?:^|[_\-\s])z(\d+)(?:[_\-\s]|$)', s)
        if m:
            try:
                iv = int(m.group(1))
                return iv if iv > 0 else None
            except Exception:
                return None
        return None

    z_cols = [
        c for c in (
            'peptide_charge',
            'precursor_charge',
            'precursor_z',
            'charge',
            'z',
            'peptide_z',
            'charge_from_name',
            'peptide_charge_from_name',
        )
        if c in df.columns
    ]
    token_cols = [c for c in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name') if c in df.columns]
    if not token_cols:
        return out

    for _, row in df.iterrows():
        z_val: int | None = None
        for zc in z_cols:
            z_val = _z_from_value(row.get(zc, ''))
            if z_val is not None:
                break
        if z_val is None:
            for tc in token_cols:
                for tok in _split_semicolon_tokens(row.get(tc, '')):
                    z_val = _z_from_value(tok)
                    if z_val is not None:
                        break
                if z_val is not None:
                    break
        if z_val is None or int(z_val) <= 0:
            continue
        for tc in token_cols:
            for tok in _split_semicolon_tokens(row.get(tc, '')):
                n_full = _run_id_norm(tok)
                if n_full:
                    out[n_full] = int(z_val)
    return out


def _load_name_mapping_mzml_path_by_run(working_dir: str) -> dict[str, str]:
    """
    Build normalized-run-id -> mzML absolute path by resolving terminology tokens
    against files under working_directory/data/mzml.
    """
    out: dict[str, str] = {}
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return out
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return out
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return out
    if df is None or df.empty:
        return out

    token_cols = [c for c in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name') if c in df.columns]
    if not token_cols:
        return out

    mzml_roots: list[str] = []
    mzml_root = _targeted_mzml_root_dir(wd)
    if mzml_root and os.path.isdir(mzml_root):
        mzml_roots.append(os.path.abspath(mzml_root))
    mzml_files: list[str] = []
    for root_dir in mzml_roots:
        try:
            for root, _dirs, files in os.walk(root_dir):
                for fn in files:
                    if str(fn or '').lower().endswith(tuple(e.lower() for e in MZML_EXT)):
                        mzml_files.append(os.path.abspath(os.path.join(root, fn)))
        except Exception:
            continue

    by_norm: dict[str, str] = {}
    for p in mzml_files:
        stem = os.path.splitext(os.path.basename(str(p or '').strip()))[0]
        n_full = _run_id_norm(stem)
        if n_full and n_full not in by_norm:
            by_norm[n_full] = str(p)
        for alias in _run_id_alias_norms(stem):
            if alias and alias not in by_norm:
                by_norm[alias] = str(p)

    for _, row in df.iterrows():
        row_mzml_path = ''
        for pcol in ('mzml_path', 'source_mzml_path'):
            if pcol not in df.columns:
                continue
            p_raw = str(row.get(pcol, '') or '').strip()
            if p_raw and os.path.isfile(p_raw) and str(p_raw).lower().endswith(tuple(e.lower() for e in MZML_EXT)):
                row_mzml_path = os.path.abspath(p_raw)
                break
        for tc in token_cols:
            for tok in _split_semicolon_tokens(row.get(tc, '')):
                tok_s = str(tok or '').strip()
                if not tok_s:
                    continue
                n_full = _run_id_norm(tok_s)
                if not n_full:
                    continue
                # Direct path token takes precedence when valid.
                if os.path.isfile(tok_s) and str(tok_s).lower().endswith(tuple(e.lower() for e in MZML_EXT)):
                    out[n_full] = os.path.abspath(tok_s)
                    continue
                if row_mzml_path:
                    out[n_full] = str(row_mzml_path)
                    continue
                p_match = by_norm.get(n_full, '')
                if p_match:
                    out[n_full] = str(p_match)
    return out


def _load_inventory_slot_by_run(working_dir: str) -> dict[str, tuple[float, str, int, int, str]]:
    """
    Authoritative terminology mapping:
    normalized-run-id -> (activation_ms, side_group, precursor_z, replicate_index, mzml_path)
    """
    out: dict[str, tuple[float, str, int, int, str]] = {}
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return out
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return out
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return out
    if df is None or df.empty:
        return out

    token_cols = [c for c in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name') if c in df.columns]

    def _rep_idx(v: object) -> int:
        try:
            fv = float(v)
            if np.isfinite(fv):
                iv = int(round(fv))
                return iv if iv > 0 else 0
        except Exception:
            pass
        s = str(v or '').strip()
        m = re.search(r'(?i)(?:^|[_\-\s])rep(?:licate)?[_\-\s]?(\d+)(?:$|[_\-\s])', s)
        if m:
            try:
                iv = int(m.group(1))
                return iv if iv > 0 else 0
            except Exception:
                return 0
        return 0

    def _z_idx(v: object) -> int:
        try:
            fv = float(v)
            if np.isfinite(fv):
                iv = int(round(fv))
                return iv if iv > 0 else 0
        except Exception:
            pass
        s = str(v or '').strip()
        m = re.search(r'(?i)(?:^|[_\-\s])z(\d+)(?:[_\-\s]|$)', s)
        if m:
            try:
                iv = int(m.group(1))
                return iv if iv > 0 else 0
            except Exception:
                return 0
        return 0

    for _, row in df.iterrows():
        act_ms = _activation_setting_ms_from_token_text(row.get('activation_setting', ''))
        if act_ms is None:
            act_ms = _activation_setting_ms_from_token_text(row.get('activation_setting_from_name', ''))
        if act_ms is None or (not np.isfinite(float(act_ms))):
            continue
        lbl = _normalize_hdx_label_value(row.get('run_type', ''))
        if not lbl:
            lbl = _normalize_hdx_label_value(row.get('label_h_or_d', ''))
        lbl_u = str(lbl or '').strip().upper()
        if lbl_u not in {'H', 'UN', 'D'}:
            continue
        side = 'D' if lbl_u == 'D' else 'H/UN'
        z_val = (
            _z_idx(row.get('peptide_charge', ''))
            or _z_idx(row.get('precursor_charge', ''))
            or _z_idx(row.get('charge', ''))
        )
        if z_val <= 0:
            continue
        rep_val = (
            _rep_idx(row.get('replicate_index', ''))
            or _rep_idx(row.get('inventory_replicate_index', ''))
            or _rep_idx(row.get('replicate', ''))
        )
        if rep_val <= 0:
            continue
        p_mzml = ''
        for pcol in ('mzml_path', 'source_mzml_path'):
            if pcol not in df.columns:
                continue
            p_raw = str(row.get(pcol, '') or '').strip()
            if p_raw and os.path.isfile(p_raw):
                p_mzml = os.path.abspath(p_raw)
                break
        if not p_mzml:
            # best-effort from data/mzml inventory by token name
            for tc in token_cols:
                found = False
                for tok in _split_semicolon_tokens(row.get(tc, '')):
                    tok_n = _run_id_norm(tok)
                    if not tok_n:
                        continue
                    # defer path fill; token aliases still map slot.
                    found = True
                    break
                if found:
                    break
        slot = (float(act_ms), str(side), int(z_val), int(rep_val), str(p_mzml))
        alias_tokens: list[str] = []
        for tc in token_cols:
            alias_tokens.extend(_split_semicolon_tokens(row.get(tc, '')))
        if p_mzml:
            alias_tokens.append(os.path.splitext(os.path.basename(str(p_mzml)))[0])
        for tok in alias_tokens:
            n = _run_id_norm(tok)
            if n:
                out[n] = slot
    return out


def _load_name_mapping_rep_index_by_run(working_dir: str) -> dict[str, int]:
    """
    Build normalized-run-id -> replicate index from accepted Name-tab mapping.
    If an explicit replicate column is unavailable, assign deterministic replicate
    order within (side-group, activation-setting) from row/token order.
    """
    out: dict[str, int] = {}
    wd = str(working_dir or '').strip()
    if not wd or not os.path.isdir(wd):
        return out
    selected_csv = _selected_inventory_check_csv_path(wd)
    if not selected_csv or not os.path.isfile(selected_csv):
        return out
    try:
        df = pd.read_csv(selected_csv)
    except Exception:
        return out
    if df is None or df.empty:
        return out

    def _rep_idx_from_value(v: object) -> int | None:
        try:
            fv = float(v)
            if np.isfinite(fv):
                iv = int(round(fv))
                if iv > 0:
                    return int(iv)
        except Exception:
            pass
        s = str(v or '').strip()
        if not s:
            return None
        m = re.search(r'(?i)(?:^|[_\-\s])rep(?:licate)?[_\-\s]?(\d+)(?:$|[_\-\s])', s)
        if m:
            try:
                rv = int(m.group(1))
                return rv if rv > 0 else None
            except Exception:
                return None
        m2 = re.fullmatch(r'(\d+)', s)
        if m2:
            try:
                rv = int(m2.group(1))
                return rv if rv > 0 else None
            except Exception:
                return None
        return None

    def _precursor_z_from_token(token_text: object) -> int | None:
        s = str(token_text or '').strip()
        if not s:
            return None
        m = re.search(r'(?i)(?:^|[_\-\s])z(\d+)(?:[_\-\s]|$)', s)
        if m:
            try:
                zv = int(m.group(1))
                return zv if zv > 0 else None
            except Exception:
                return None
        m2 = re.search(r'(?i)precursor[_\-\s]*z(\d+)', s)
        if m2:
            try:
                zv = int(m2.group(1))
                return zv if zv > 0 else None
            except Exception:
                return None
        return None

    rep_cols = [
        c for c in [
            'replicate',
            'replicate_from_name',
            'replicate_index',
            'rep_index',
            'rep',
            'rep_number',
            'replicate_number',
        ]
        if c in df.columns
    ]
    token_cols = [c for c in ('run_id', 'inventory_matched_run_ids', 'h_un_filename', 'd_filename', 'unlabeled_file_name') if c in df.columns]
    if not token_cols:
        return out

    # If replicate index is explicitly provided in terminology mapping, use it
    # directly (authoritative) and avoid inferred/grouped reassignment.
    if rep_cols:
        token_cols_ordered = [
            c for c in (
                'h_un_filename',
                'd_filename',
                'unlabeled_file_name',
                'inventory_matched_run_ids',
                'run_id',
            )
            if c in df.columns
        ]
        for _, row in df.iterrows():
            rep_explicit: int | None = None
            for rc in rep_cols:
                rep_explicit = _rep_idx_from_value(row.get(rc, ''))
                if rep_explicit is not None:
                    break
            if rep_explicit is None or int(rep_explicit) <= 0:
                continue
            rep_idx_final = int(rep_explicit)
            for tc in token_cols_ordered:
                for tok in _split_semicolon_tokens(row.get(tc, '')):
                    n_full = _run_id_norm(tok)
                    if not n_full:
                        continue
                    # Overwrite is intentional: later rows/columns in the
                    # user-selected terminology CSV are treated as authoritative.
                    out[n_full] = int(rep_idx_final)
        return out

    pending: list[tuple[str, str, float | None, int | None, int | None]] = []
    for _, row in df.iterrows():
        lbl = _normalize_hdx_label_value(row.get('run_type', ''))
        side_group = 'D' if str(lbl).strip().upper() == 'D' else 'H/UN'
        act_ms: float | None = None
        act_ms = _activation_setting_ms_from_token_text(row.get('activation_setting_from_name', ''))
        if act_ms is None:
            act_ms = _activation_setting_ms_from_token_text(row.get('activation_setting', ''))
        rep_explicit: int | None = None
        for rc in rep_cols:
            rep_explicit = _rep_idx_from_value(row.get(rc, ''))
            if rep_explicit is not None:
                break

        for tc in token_cols:
            tc_side = side_group
            if tc == 'd_filename':
                tc_side = 'D'
            elif tc in ('h_un_filename', 'unlabeled_file_name'):
                tc_side = 'H/UN'
            for tok in _split_semicolon_tokens(row.get(tc, '')):
                n_full = _run_id_norm(tok)
                if not n_full:
                    continue
                z_tok = _precursor_z_from_token(tok)
                pending.append((n_full, tc_side, act_ms, rep_explicit, z_tok))

    counter_by_group: dict[tuple[str, float | None, int | None], int] = {}
    for n_full, side_group, act_ms, rep_explicit, z_tok in pending:
        rep_idx = int(rep_explicit) if rep_explicit is not None else 0
        if rep_idx <= 0:
            gk = (
                str(side_group),
                float(act_ms) if act_ms is not None else None,
                int(z_tok) if z_tok is not None else None,
            )
            counter_by_group[gk] = int(counter_by_group.get(gk, 0)) + 1
            rep_idx = int(counter_by_group[gk])
        out[n_full] = max(1, int(rep_idx))
    return out


def _resolve_rep_index_from_name_map(
    source_name: object,
    source_path: object,
    run_rep_map: dict[str, int] | None = None,
) -> int:
    """Resolve replicate index from Name-tab mapping using strict run-id matches."""
    rm = run_rep_map or {}
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        n_full = _run_id_norm(stem)
        v = rm.get(n_full)
        if v is not None:
            try:
                iv = int(v)
                if iv > 0:
                    return int(iv)
            except Exception:
                pass
    return 0


def _resolve_hdx_label_from_name_map(
    source_name: object,
    source_path: object,
    run_label_map: dict[str, str] | None = None,
) -> str:
    """
    Resolve HDX label from Name-tab mapping using source name/path aliases.
    Falls back to run-name parser when no mapping match is found.
    """
    rm = run_label_map or {}
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        n_full = _run_id_norm(stem)
        v = str(rm.get(n_full, '') or '').strip().upper()
        if v in {'H', 'D', 'UN'}:
            return v
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        if not stem:
            continue
        n_stem = _run_id_norm(stem)
        for k_norm, lbl in rm.items():
            if len(str(k_norm or '')) < 10:
                continue
            if str(n_stem).endswith(str(k_norm)) or str(k_norm).endswith(str(n_stem)):
                v = str(lbl or '').strip().upper()
                if v in {'H', 'D', 'UN'}:
                    return v
    return _infer_hdx_label_from_run_name(str(source_name or ''))


def _resolve_activation_method_from_name_map(
    source_name: object,
    source_path: object,
    run_method_map: dict[str, str] | None = None,
) -> str:
    """
    Resolve activation method from Name-tab mapping using source name/path aliases.
    Falls back to run-name parser when no mapping match is found.
    """
    rm = run_method_map or {}
    # Prefer exact normalized run-id mapping to avoid accidental collisions
    # from short/generic alias fragments (e.g., replicate numbers).
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        n_full = _run_id_norm(stem)
        v = str(rm.get(n_full, '') or '').strip().upper()
        if v:
            return v

    # Conservative fallback: token-tail match against mapped keys.
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        if not stem:
            continue
        toks = [t for t in re.split(r'[^a-z0-9]+', stem.lower()) if t]
        if not toks:
            continue
        for k_norm, method in rm.items():
            # only allow sufficiently long key overlap to avoid generic matches
            if len(str(k_norm or '')) < 10:
                continue
            if str(_run_id_norm(stem)).endswith(str(k_norm)) or str(k_norm).endswith(str(_run_id_norm(stem))):
                v = str(method or '').strip().upper()
                if v:
                    return v
    stem_fallback = os.path.splitext(os.path.basename(str(source_name or '').strip()))[0]
    setting = str(_infer_fragmentation_setting_from_run_name(stem_fallback) or '').strip().upper()
    return setting.split('_')[0] if setting else ''


def _resolve_activation_setting_ms_from_name_map(
    source_name: object,
    source_path: object,
    run_setting_map: dict[str, float] | None = None,
) -> float | None:
    """
    Resolve activation setting (ms) from Name-tab mapping using source aliases.
    Falls back to conservative run-name parsing when no mapping match is found.
    """
    rm = run_setting_map or {}
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        n_full = _run_id_norm(stem)
        v = rm.get(n_full, None)
        if v is not None:
            try:
                return float(v)
            except Exception:
                pass
    for cand in [source_name, source_path]:
        stem = os.path.splitext(os.path.basename(str(cand or '').strip()))[0]
        if not stem:
            continue
        n_stem = _run_id_norm(stem)
        for k_norm, v in rm.items():
            if len(str(k_norm or '')) < 10:
                continue
            if str(n_stem).endswith(str(k_norm)) or str(k_norm).endswith(str(n_stem)):
                try:
                    return float(v)
                except Exception:
                    pass
    # Fallback parser from filename token.
    stem_fallback = os.path.splitext(os.path.basename(str(source_name or '').strip()))[0]
    m = re.search(r'([0-9]+(?:\.[0-9]+)?)\s*ms\b', stem_fallback, flags=re.IGNORECASE)
    if m:
        try:
            return float(m.group(1))
        except Exception:
            return None
    return None


def _extract_ms2_scan_arrays_from_mzml(mzml_path: str, wanted_scans: set[int]) -> tuple[dict[int, pd.DataFrame], str]:
    out: dict[int, pd.DataFrame] = {}
    if not mzml_path or not os.path.isfile(mzml_path) or not wanted_scans:
        return out, 'missing_file_or_scans'
    try:
        from pyteomics import mzml as pyteomics_mzml
    except Exception as e:
        return out, f'pyteomics_import_error:{e}'
    remaining = set(int(x) for x in wanted_scans if int(x) > 0)
    if not remaining:
        return out, 'empty_scan_set'
    try:
        ms2_ord = 0
        with pyteomics_mzml.MzML(mzml_path) as reader:
            for spec in reader:
                if not remaining:
                    break
                sid = str(spec.get('id', ''))
                ms_level = spec.get('ms level', spec.get('ms_level', None))
                try:
                    ms_level_i = int(ms_level)
                except Exception:
                    ms_level_i = None
                if ms_level_i != 2:
                    continue
                ms2_ord += 1
                scan_no = _scan_number_from_spectrum_id(sid)
                if scan_no is None:
                    # Fallback for mzMLs without explicit scan numbering in ID.
                    scan_no = ms2_ord
                if scan_no not in remaining:
                    continue
                mz_arr = np.asarray(spec.get('m/z array', np.array([])), dtype=float)
                int_arr = np.asarray(spec.get('intensity array', np.array([])), dtype=float)
                if mz_arr.size == 0 or int_arr.size == 0:
                    continue
                n = int(min(mz_arr.size, int_arr.size))
                if n <= 0:
                    continue
                df = pd.DataFrame({'mz': mz_arr[:n], 'Intensity': int_arr[:n]})
                df = df.replace([np.inf, -np.inf], np.nan).dropna(subset=['mz', 'Intensity'])
                if df.empty:
                    continue
                df = df[df['Intensity'] >= 0].sort_values('mz').reset_index(drop=True)
                if df.empty:
                    continue
                out[scan_no] = df
                remaining.discard(scan_no)
    except Exception as e:
        return out, f'mzml_read_error:{e}'
    return out, 'ok'


def _run_pyhxexpress_fits_from_prep(
    spectra_input_csv: str,
    out_dir: str,
    output_base: str,
    pyhx_config_overrides: dict[str, object] | None = None,
    progress_cb=None,
) -> tuple[bool, str, dict[str, str]]:
    """
    Build pyHXExpress user_deutdata from prepared scan lists and execute run_hdx_fits().
    """
    def _emit(pct: int, msg: str) -> None:
        if progress_cb is None:
            return
        try:
            progress_cb(max(0, min(100, int(pct))), str(msg))
        except Exception:
            pass

    run_t0 = time.time()
    phase_t0 = run_t0
    cfg_over = dict(pyhx_config_overrides or {})
    use_theoretical_h_companions = bool(cfg_over.get('use_theoretical_h_companions', False))

    def _emit_phase(pct: int, title: str, detail: str = '') -> None:
        nonlocal phase_t0
        now = time.time()
        elapsed = max(0.0, now - phase_t0)
        phase_t0 = now
        txt = f'[phase] {title} (dt={elapsed:.1f}s)'
        if detail:
            txt += f' :: {detail}'
        _emit(pct, txt)

    def _resolve_working_dir_guess(path_hint: str) -> str:
        start = os.path.abspath(str(path_hint or '').strip()) if str(path_hint or '').strip() else ''
        if not start:
            return ''
        cur = start if os.path.isdir(start) else os.path.dirname(start)
        seen: set[str] = set()
        for _ in range(8):
            if (not cur) or (cur in seen):
                break
            seen.add(cur)
            try:
                sel = _selected_inventory_check_csv_path(cur)
                if sel and os.path.isfile(sel):
                    return cur
            except Exception:
                pass
            parent = os.path.dirname(cur)
            if (not parent) or (parent == cur):
                break
            cur = parent
        return os.path.abspath(os.path.dirname(path_hint)) if str(path_hint or '').strip() else ''

    _emit(0, '========== pyHXExpress fit debug run started ==========')
    _emit(1, f'Start time: {_timestamp_human()}')
    _emit(1, f'Prepared spectra CSV: {spectra_input_csv}')
    _emit(1, f'Fit output root: {out_dir}')
    _emit(1, 'Validating pyHXExpress runtime and prepared input CSV...')
    if pyhx_hxex is None:
        return False, 'pyHXExpress import is not available in this environment.', {}
    if not spectra_input_csv or not os.path.isfile(spectra_input_csv):
        return False, 'Prepared spectra input CSV is missing.', {}
    if not out_dir:
        return False, 'Output directory not set.', {}

    try:
        sdf = pd.read_csv(spectra_input_csv)
    except Exception as e:
        return False, f'Could not read prepared spectra CSV: {e}', {}
    _emit(7, f'Input CSV columns ({len(sdf.columns)}): {", ".join([str(c) for c in sdf.columns[:25]])}')
    req = ['peptide_sequence', 'charge', 'scan', 'source_mzml', 'source_mzml_path', 'label_h_or_d']
    miss = [c for c in req if c not in sdf.columns]
    if miss:
        return False, f'Prepared spectra CSV missing required columns: {", ".join(miss)}', {}
    if sdf.empty:
        return False, 'Prepared spectra CSV is empty.', {}

    _emit(8, f'Loaded prepared spectra rows: {len(sdf)}')
    sdf = sdf.copy()
    sdf['peptide_sequence'] = sdf['peptide_sequence'].astype(str).str.strip().str.upper()
    sdf['source_mzml'] = sdf['source_mzml'].astype(str)
    sdf['source_mzml_path'] = sdf['source_mzml_path'].astype(str)
    sdf['label_h_or_d'] = sdf['label_h_or_d'].astype(str).str.upper()
    if 'pyhx_state' in sdf.columns:
        sdf['pyhx_state'] = sdf['pyhx_state'].astype(str).str.strip()
    else:
        sdf['pyhx_state'] = sdf['label_h_or_d'].apply(_map_hdx_label_to_pyhx_state)
    sdf['pyhx_state'] = sdf['pyhx_state'].apply(_map_hdx_label_to_pyhx_state)
    sdf['charge'] = pd.to_numeric(sdf['charge'], errors='coerce').round().astype('Int64')
    sdf['scan'] = pd.to_numeric(sdf['scan'], errors='coerce').round().astype('Int64')
    sdf = sdf[
        (sdf['peptide_sequence'] != '')
        & (sdf['charge'].notna())
        & (sdf['scan'].notna())
        & (sdf['source_mzml_path'].astype(str) != '')
    ].copy()
    if sdf.empty:
        return False, 'No valid rows left in prepared spectra CSV after cleanup.', {}

    _emit(12, f'Rows after cleanup: {len(sdf)}')
    _emit_phase(12, 'Input cleanup complete', f'rows={len(sdf)}')
    try:
        lbl_counts = sdf['label_h_or_d'].astype(str).str.upper().value_counts(dropna=False).to_dict()
        _emit(13, f'Label distribution after cleanup: {lbl_counts}')
    except Exception:
        pass
    try:
        mzml_n = int(sdf['source_mzml_path'].astype(str).replace('', np.nan).dropna().nunique())
        _emit(14, f'Unique source mzML paths referenced: {mzml_n}')
    except Exception:
        pass
    # Keep peptide-mode prefilter bridge filenames aligned with app-wide
    # AM/PM no-seconds timestamp policy.
    ts = _timestamp_token()
    base = _sanitize_name_token(output_base or 'pyhx') or 'pyhx'
    run_dir = os.path.join(out_dir, _dedup_same_day_dates_in_name(f'{base}_pyhx_fits__{ts}'))
    os.makedirs(run_dir, exist_ok=True)
    _emit(14, f'Run directory: {run_dir}')
    _emit_phase(14, 'Run directory prepared', os.path.basename(run_dir))

    scans_by_file: dict[str, set[int]] = {}
    n_missing_paths = 0
    missing_paths_preview: list[str] = []
    _emit(15, 'Building per-file scan index from prepared rows...')
    for mzml_path, grp in sdf.groupby('source_mzml_path', dropna=False):
        scan_set = set(int(x) for x in pd.to_numeric(grp['scan'], errors='coerce').dropna().astype(int).tolist() if int(x) > 0)
        if not os.path.isfile(str(mzml_path)):
            n_missing_paths += 1
            if len(missing_paths_preview) < 8:
                missing_paths_preview.append(str(mzml_path))
            continue
        if scan_set:
            scans_by_file[str(mzml_path)] = scan_set
    _emit(
        16,
        f'Scan index summary: mzML files with requested scans={len(scans_by_file)}, '
        f'missing_mzml_paths={n_missing_paths}',
    )
    if scans_by_file:
        top_scan_files = sorted(
            ((os.path.basename(k), len(v)) for k, v in scans_by_file.items()),
            key=lambda x: x[1],
            reverse=True,
        )[:8]
        _emit(
            16,
            'Requested scans per file (top): '
            + '; '.join(f'{nm}={cnt}' for nm, cnt in top_scan_files),
        )
    if missing_paths_preview:
        _emit(16, 'Missing mzML path examples: ' + '; '.join(missing_paths_preview))

    raw_lookup: dict[str, dict[int, pd.DataFrame]] = {}
    n_requested_scans = 0
    n_found_scans = 0
    extract_status_counts: dict[str, int] = {}
    total_files = max(1, len(scans_by_file))
    for i, (p, scan_set) in enumerate(scans_by_file.items(), start=1):
        n_requested_scans += len(scan_set)
        raw_map, status = _extract_ms2_scan_arrays_from_mzml(p, scan_set)
        raw_lookup[p] = raw_map
        extract_status_counts[status] = int(extract_status_counts.get(status, 0)) + 1
        n_found_scans += len(raw_lookup[p])
        _emit(15 + int(35 * (i / total_files)), f'Reading mzML scans {i}/{total_files}: {os.path.basename(p)}')
    match_pct = (100.0 * float(n_found_scans) / float(n_requested_scans)) if n_requested_scans > 0 else 0.0
    _emit(
        51,
        f'mzML extraction summary: requested_scans={n_requested_scans}, matched_scans={n_found_scans} '
        f'({match_pct:.1f}%), file_status={extract_status_counts}',
    )
    _emit_phase(
        51,
        'mzML scan extraction complete',
        f'requested={n_requested_scans}, matched={n_found_scans}, files={len(scans_by_file)}',
    )

    full_deut_time = float(getattr(pyhx_hxex.config, 'FullDeut_Time', 1e6) or 1e6)
    if (not np.isfinite(full_deut_time)) or (float(full_deut_time) <= 0.0):
        full_deut_time = 1e6
        _emit(82, 'Adjusted invalid FullDeut_Time to 1e6 to preserve binary UN/D time context.')
    sample_name = _sanitize_name_token(base) or 'sample'
    working_dir_guess = _resolve_working_dir_guess(out_dir)
    name_map_run_ids = _load_name_mapping_run_ids(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else set()
    run_method_map = _load_name_mapping_activation_method_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    run_setting_map = _load_name_mapping_activation_setting_ms_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    source_side_by_run_norm: dict[str, str] = {}
    source_rep_by_run_norm: dict[str, int] = {}
    source_setting_by_run_norm: dict[str, str] = {}
    source_side_by_path_abs: dict[str, str] = {}
    source_rep_by_path_abs: dict[str, int] = {}
    source_setting_by_path_abs: dict[str, str] = {}
    try:
        inv_slot_map = _load_inventory_slot_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
        for _rk, slot_v in (inv_slot_map or {}).items():
            try:
                act_v, side_v, _z, rep_v, p_v = slot_v
            except Exception:
                continue
            side_norm = 'D' if str(side_v).strip().upper() == 'D' else 'UN'
            p_txt = str(p_v or '').strip()
            p_base = os.path.basename(p_txt) if p_txt else ''
            stem = os.path.splitext(p_base)[0] if p_base else ''
            run_norm_stem = _run_id_norm(stem)
            method_tok = str(run_method_map.get(run_norm_stem, '') or '').strip().upper() if run_norm_stem else ''
            ms_tok = ''
            try:
                ms_v = run_setting_map.get(run_norm_stem, act_v) if run_norm_stem else act_v
                ms_f = float(ms_v)
                if np.isfinite(ms_f):
                    ms_tok = f"{int(round(ms_f))}ms" if abs(ms_f - round(ms_f)) < 1e-9 else f"{ms_f:g}ms"
            except Exception:
                ms_tok = ''
            setting_norm = _sanitize_name_token(f'{method_tok}_{ms_tok}' if method_tok and ms_tok else (method_tok or ms_tok)).upper()
            for key_txt in (p_txt, p_base, stem):
                rn = _run_id_norm(key_txt)
                if rn:
                    source_side_by_run_norm[rn] = side_norm
                    source_rep_by_run_norm[rn] = int(rep_v) if int(rep_v) > 0 else 1
                    source_setting_by_run_norm[rn] = str(setting_norm or 'UNKNOWN')
            if p_txt:
                p_abs = os.path.abspath(p_txt)
                source_side_by_path_abs[p_abs] = side_norm
                source_rep_by_path_abs[p_abs] = int(rep_v) if int(rep_v) > 0 else 1
                source_setting_by_path_abs[p_abs] = str(setting_norm or 'UNKNOWN')
    except Exception:
        source_side_by_run_norm = {}
        source_rep_by_run_norm = {}
        source_setting_by_run_norm = {}
        source_side_by_path_abs = {}
        source_rep_by_path_abs = {}
        source_setting_by_path_abs = {}
    data_id_map: dict[tuple[str, int, str, str], int] = {}
    metadf_rows: list[dict[str, object]] = []
    deut_frames: list[pd.DataFrame] = []
    frag_setting_cache: dict[str, str] = {}
    bin_diag_rows: list[dict[str, object]] = []

    if 'fragment_fit_key' not in sdf.columns:
        sdf['fragment_fit_key'] = ''
    sdf['fragment_fit_key'] = sdf['fragment_fit_key'].astype(str).str.strip()
    group_cols = ['peptide_sequence', 'charge', 'source_mzml', 'source_mzml_path', 'pyhx_state', 'fragment_fit_key']
    grouped = sdf.groupby(group_cols, dropna=False)
    grouped_list = list(grouped)
    total_groups = max(1, len(grouped_list))
    _emit(48, f'Peak-picking grouped inputs: {total_groups} groups')
    try:
        grp_sizes = [int(len(g)) for _, g in grouped_list]
        if grp_sizes:
            _emit(
                48,
                'Peak-picking group size stats (rows/group): '
                f"min={int(min(grp_sizes))}, median={int(np.median(grp_sizes))}, max={int(max(grp_sizes))}",
            )
    except Exception:
        pass
    group_skip_counts: Counter = Counter()
    peakpick_success_groups = 0
    for gi, ((pep, z_raw, src_name, src_path, pyhx_state, frag_key), grp) in enumerate(grouped_list, start=1):
        if pd.isna(z_raw):
            group_skip_counts['invalid_charge_nan'] += 1
            continue
        z = int(z_raw)
        if z <= 0:
            group_skip_counts['invalid_charge_nonpositive'] += 1
            continue
        pep = str(pep or '').strip().upper()
        if not pep:
            group_skip_counts['missing_peptide'] += 1
            continue
        frag_key_s = str(frag_key or '').strip()
        frag_subseq = _fragment_subsequence_from_fragment_fit_key(frag_key_s, pep)
        pep_fit = str(frag_subseq or pep).strip().upper()
        if not pep_fit:
            group_skip_counts['missing_fragment_sequence'] += 1
            continue
        wanted_scans = [int(x) for x in pd.to_numeric(grp['scan'], errors='coerce').dropna().astype(int).tolist() if int(x) > 0]
        if not wanted_scans:
            group_skip_counts['no_valid_scans'] += 1
            continue
        spec_map = raw_lookup.get(str(src_path), {})
        raw_dfs = [spec_map.get(sn) for sn in wanted_scans if sn in spec_map]
        raw_dfs = [x for x in raw_dfs if x is not None and not x.empty]
        if not raw_dfs:
            group_skip_counts['no_matching_scan_arrays'] += 1
            continue

        binned: dict[float, float] = {}
        for rdf in raw_dfs:
            for mz_val, int_val in zip(rdf['mz'].astype(float).values, rdf['Intensity'].astype(float).values):
                if not np.isfinite(mz_val) or not np.isfinite(int_val):
                    continue
                k = round(float(mz_val), 4)
                binned[k] = binned.get(k, 0.0) + max(0.0, float(int_val))
        if not binned:
            group_skip_counts['empty_binned_signal'] += 1
            continue
        src_path_str = str(src_path)
        src_path_abs = os.path.abspath(src_path_str) if str(src_path_str).strip() else ''
        run_stem = os.path.splitext(os.path.basename(str(src_name)))[0]
        run_norm = _run_id_norm(run_stem)
        side_from_inventory = str(
            source_side_by_path_abs.get(src_path_abs, source_side_by_run_norm.get(run_norm, '')) or ''
        ).strip().upper()
        rep_from_inventory = int(
            source_rep_by_path_abs.get(src_path_abs, source_rep_by_run_norm.get(run_norm, 0)) or 0
        )
        frag_setting = str(
            source_setting_by_path_abs.get(src_path_abs, source_setting_by_run_norm.get(run_norm, '')) or ''
        ).strip().upper()
        if side_from_inventory not in {'D', 'UN'}:
            group_skip_counts['missing_inventory_side_mapping'] += 1
            continue
        if rep_from_inventory <= 0:
            group_skip_counts['missing_inventory_replicate_mapping'] += 1
            continue
        if not frag_setting:
            group_skip_counts['missing_inventory_activation_mapping'] += 1
            continue
        if use_theoretical_h_companions and side_from_inventory != 'D':
            # Optional augmentation: inject missing isotope companions (M+1/2/3)
            # scaled from observed M0 for H/UN runs.
            mz_keys_sorted = sorted(float(k) for k in binned.keys())
            if mz_keys_sorted:
                proton_mass_da = 1.007276466812
                iso_step_da = 1.0033548378
                z_frag = _fragment_charge_from_ion_identity(str(frag_key_s or '').strip())
                if int(z_frag) <= 0:
                    z_frag = int(max(1, int(z)))
                m0_vals: list[float] = []
                if 'fragment_mono_mz' in grp.columns:
                    m0_vals = [
                        float(v)
                        for v in pd.to_numeric(grp['fragment_mono_mz'], errors='coerce').dropna().tolist()
                        if np.isfinite(float(v)) and float(v) > 0
                    ]
                m0_vals = sorted(set(m0_vals))

                def _nearest_mz_key(target_mz: float, tol_da: float) -> float | None:
                    if not mz_keys_sorted:
                        return None
                    i = bisect.bisect_right(mz_keys_sorted, float(target_mz))
                    cands: list[float] = []
                    if i - 1 >= 0:
                        cands.append(float(mz_keys_sorted[i - 1]))
                    if i < len(mz_keys_sorted):
                        cands.append(float(mz_keys_sorted[i]))
                    if not cands:
                        return None
                    best = min(cands, key=lambda x: abs(float(x) - float(target_mz)))
                    return float(best) if abs(float(best) - float(target_mz)) <= float(tol_da) else None

                injected_companions = 0
                for m0_mz in m0_vals:
                    tol0 = max(0.0025, float(m0_mz) * 12e-6)
                    mk0 = _nearest_mz_key(float(m0_mz), float(tol0))
                    if mk0 is None:
                        continue
                    y0 = float(binned.get(round(float(mk0), 4), 0.0))
                    if (not np.isfinite(y0)) or (y0 <= 0):
                        continue
                    # Preferred: exact composition-based NA envelope from pyHXExpress.
                    ratios: dict[int, float] = {}
                    try:
                        na = np.asarray(
                            pyhx_hxex.get_na_isotope(str(pep_fit).strip().upper(), int(z_frag), npeaks=None),
                            dtype=float,
                        )
                        if na.size >= 2 and float(na[0]) > 0 and np.isfinite(float(na[0])):
                            na0 = float(na[0])
                            for iso_n in (1, 2, 3):
                                if iso_n < na.size and np.isfinite(float(na[iso_n])) and float(na[iso_n]) > 0:
                                    ratios[iso_n] = float(na[iso_n]) / na0
                    except Exception:
                        ratios = {}
                    # Fallback: averagine/Poisson approximation if NA lookup fails.
                    if not ratios:
                        neutral_mass = (float(m0_mz) * float(z_frag)) - (float(z_frag) * proton_mass_da)
                        if (not np.isfinite(neutral_mass)) or (neutral_mass <= 0):
                            continue
                        n_c = max(0.1, (float(neutral_mass) / 111.1254) * 4.9384)
                        lam = max(0.0, min(8.0, n_c * 0.0107))
                        ratios = {
                            1: float(lam),
                            2: float((lam * lam) / 2.0),
                            3: float((lam * lam * lam) / 6.0),
                        }
                    for iso_n in (1, 2, 3):
                        target = float(m0_mz) + (float(iso_step_da) * float(iso_n) / float(z_frag))
                        tol_n = max(0.0025, float(target) * 12e-6)
                        mk_n = _nearest_mz_key(float(target), float(tol_n))
                        if mk_n is not None:
                            continue
                        y_pred = float(y0) * float(ratios.get(int(iso_n), 0.0))
                        if (not np.isfinite(y_pred)) or (y_pred <= 0):
                            continue
                        kb = round(float(target), 4)
                        binned[kb] = float(binned.get(kb, 0.0)) + float(y_pred)
                        injected_companions += 1
                if injected_companions > 0:
                    _emit(
                        50 + int(28 * (gi / total_groups)),
                        f'Injected theoretical H/UN companions before peak-picking: +{int(injected_companions)}',
                    )
        xs = sorted(binned.keys())
        # Use summed signal across matched scans for HX-Express fit input.
        ys = [binned[k] for k in xs]
        raw_avg = pd.DataFrame({'mz': xs, 'Intensity': ys})
        raw_avg = raw_avg[(raw_avg['Intensity'] > 0) & raw_avg['mz'].notna()].copy()
        if raw_avg.empty:
            group_skip_counts['empty_average_spectrum'] += 1
            continue

        # Resolve fragment-specific charge and monoisotopic m/z for peak_picker.
        # Fragment ions (z, x, a, b, c, y) have different masses than protonated
        # peptides of the same subsequence.  Without the correct undeut_mz,
        # peak_picker targets a completely wrong m/z region (off by 8-25 Da).
        z_pp = int(z)
        pp_mod: dict[str, object] = {}
        if frag_key_s:
            z_frag_pp = _fragment_charge_from_ion_identity(frag_key_s)
            if z_frag_pp > 0:
                z_pp = z_frag_pp
            frag_mz_vals = []
            if 'fragment_mono_mz' in grp.columns:
                frag_mz_vals = [
                    float(v)
                    for v in pd.to_numeric(grp['fragment_mono_mz'], errors='coerce').dropna().tolist()
                    if np.isfinite(float(v)) and float(v) > 0
                ]
            if frag_mz_vals:
                pp_mod['undeut_mz'] = float(np.median(frag_mz_vals))
        try:
            peaks = pyhx_hxex.peak_picker(
                raw_avg,
                pep_fit,
                float(z_pp),
                resolution=float(getattr(pyhx_hxex.config, 'Peak_Resolution', 50.0) or 50.0),
                count_sc=0,
                mod_dict=pp_mod,
            )
        except Exception:
            group_skip_counts['peak_picker_exception'] += 1
            continue
        if peaks is None or peaks.empty:
            group_skip_counts['empty_peak_picker_output'] += 1
            continue

        ds_key = (pep_fit, int(z), frag_setting, frag_key_s)
        if ds_key not in data_id_map:
            did = len(data_id_map)
            data_id_map[ds_key] = did
            start_seq = 1
            end_seq = int(max(1, len(pep_fit)))
            if pep and pep_fit:
                if pep.startswith(pep_fit):
                    start_seq = 1
                    end_seq = int(len(pep_fit))
                elif pep.endswith(pep_fit):
                    start_seq = int(max(1, len(pep) - len(pep_fit) + 1))
                    end_seq = int(len(pep))
                else:
                    idx = pep.find(pep_fit)
                    if idx >= 0:
                        start_seq = int(idx + 1)
                        end_seq = int(idx + len(pep_fit))
            metadf_rows.append(
                {
                    'data_id': did,
                    'file': str(src_name),
                    'sample': sample_name,
                    'start_seq': start_seq,
                    'end_seq': end_seq,
                    'peptide_range': f'{start_seq:04d}-{end_seq:04d}',
                    'charge': float(z),
                    'peptide': pep_fit,
                    'fragmentation_setting': frag_setting,
                    'fragment_fit_key': frag_key_s,
                    'run_type_pyhx': str(pyhx_state),
                }
            )
        did = data_id_map[ds_key]

        pyhx_state_u = str(pyhx_state or '').strip()
        lbl_out = 'D' if side_from_inventory == 'D' else 'UN'
        tval = float(full_deut_time) if str(lbl_out).upper() == 'D' else 0.0
        pyhx_state_u = 'TD' if str(lbl_out).upper() == 'D' else 'undeut'
        rep_guess = int(rep_from_inventory)

        peaks = peaks.copy()
        peaks['data_id'] = int(did)
        peaks['sample'] = sample_name
        peaks['peptide'] = pep_fit
        peaks['charge'] = float(z)
        p_start = 1
        p_end = int(max(1, len(pep_fit)))
        if pep and pep_fit:
            if pep.startswith(pep_fit):
                p_start, p_end = 1, int(len(pep_fit))
            elif pep.endswith(pep_fit):
                p_start, p_end = int(max(1, len(pep) - len(pep_fit) + 1)), int(len(pep))
            else:
                idx = pep.find(pep_fit)
                if idx >= 0:
                    p_start, p_end = int(idx + 1), int(idx + len(pep_fit))
        peaks['start_seq'] = int(p_start)
        peaks['end_seq'] = int(p_end)
        peaks['peptide_range'] = f'{int(p_start):04d}-{int(p_end):04d}'
        peaks['file'] = str(src_name)
        peaks['time'] = float(tval)
        peaks['rep'] = int(rep_guess)
        peaks['source_mzml'] = str(src_name)
        peaks['source_mzml_path'] = str(src_path)
        peaks['label_h_or_d'] = str(lbl_out).upper()
        peaks['pyhx_state'] = str(pyhx_state_u)
        peaks['run_type_pyhx'] = str(pyhx_state_u)
        peaks['fragmentation_setting'] = frag_setting
        peaks['fragment_fit_key'] = frag_key_s
        deut_frames.append(peaks)
        peakpick_success_groups += 1
        # Emit every group so long runs provide continuous terminal progress.
        _emit(50 + int(28 * (gi / total_groups)), f'Peak-picking group {gi}/{total_groups}: {pep} z{z}')
    _emit(
        79,
        f'Peak-picking summary: successful_groups={peakpick_success_groups}/{total_groups}, '
        f'deut_frames={len(deut_frames)}, skip_reasons={dict(group_skip_counts)}',
    )
    _emit_phase(
        79,
        'Peak-picking complete',
        f'success={peakpick_success_groups}, skipped={int(total_groups - peakpick_success_groups)}',
    )

    if not deut_frames or not metadf_rows:
        hint = ''
        if any('lxml' in str(k).lower() for k in extract_status_counts.keys()):
            hint = (
                " Install missing dependency in the app environment: "
                "`conda install -n hdx_app -c conda-forge lxml` "
                "(or `pip install lxml` in the same environment), then restart Streamlit."
            )
        return (
            False,
            '[scan-match-v2] Could not derive any peak-picked fit input from selected scans/mzML files. '
            f'(rows={len(sdf)}, mzml_files={len(scans_by_file)}, missing_mzml_paths={n_missing_paths}, '
            f'requested_scans={n_requested_scans}, matched_scans={n_found_scans}, '
            f'extract_status={extract_status_counts}).{hint}',
            {},
        )

    user_deut = pd.concat(deut_frames, ignore_index=True)
    if user_deut.empty:
        return False, 'Derived pyHXExpress deutdata is empty.', {}

    # Guard against NaN/inf values reaching curve fitting internals.
    pre_rows = len(user_deut)
    for c in ['mz', 'Intensity', 'n_deut', 'data_id', 'charge', 'time', 'rep']:
        if c in user_deut.columns:
            user_deut[c] = pd.to_numeric(user_deut[c], errors='coerce')
    user_deut = user_deut.replace([np.inf, -np.inf], np.nan)
    required_num_cols = [c for c in ['mz', 'Intensity', 'n_deut', 'data_id', 'charge', 'time', 'rep'] if c in user_deut.columns]
    if required_num_cols:
        user_deut = user_deut.dropna(subset=required_num_cols)
    if 'Intensity' in user_deut.columns:
        user_deut = user_deut[user_deut['Intensity'] > 0].copy()
    if 'mz' in user_deut.columns:
        user_deut = user_deut[user_deut['mz'] > 0].copy()
    if {'data_id', 'time', 'rep', 'n_deut', 'mz', 'Intensity'}.issubset(user_deut.columns):
        # Deduplicate same isotope bins if they appear multiple times after aggregation.
        user_deut = (
            user_deut.sort_values(['data_id', 'time', 'rep', 'n_deut', 'Intensity'], ascending=[True, True, True, True, False])
            .drop_duplicates(subset=['data_id', 'time', 'rep', 'n_deut'], keep='first')
            .sort_values(['data_id', 'time', 'rep', 'mz'])
            .reset_index(drop=True)
        )
        # Normalize isotope-bin vector length per data_id across time/rep groups.
        # pyHXExpress fit internals can fail with broadcasting errors when one group has
        # a different number of isotope bins than another within the same dataset.
        aligned_parts: list[pd.DataFrame] = []
        dropped_data_ids: list[int] = []
        n_truncated_groups = 0
        for did, dgrp in user_deut.groupby('data_id', dropna=False):
            # Align isotope bins per data_id across time contexts (UN-like time 0 vs D-like >0),
            # not per replicate. Per-replicate alignment can over-drop valid datasets when one
            # side has fewer replicate files.
            time_keys = sorted(
                set(float(x) for x in pd.to_numeric(dgrp.get('time', pd.Series(dtype=float)), errors='coerce').dropna().tolist())
            )
            if not time_keys:
                continue
            lbls_here = sorted(
                set(
                    str(x).upper().strip()
                    for x in dgrp.get('label_h_or_d', pd.Series(dtype=str)).astype(str).tolist()
                    if str(x).strip()
                )
            )
            has_un_label = any(x in {'UN', 'H'} for x in lbls_here)
            has_d_label = any(x == 'D' for x in lbls_here)
            min_bins_required = 1 if (has_un_label and has_d_label) else 3
            nsets: list[set[int]] = []
            sizes: list[int] = []
            all_group_sizes: list[int] = []
            for t_key in time_keys:
                sub = dgrp[dgrp['time'] == float(t_key)]
                nvals = set(pd.to_numeric(sub['n_deut'], errors='coerce').dropna().astype(int).tolist())
                if not nvals:
                    continue
                nsets.append(nvals)
                sizes.append(len(nvals))
                all_group_sizes.append(len(nvals))
            did_int = int(did)
            diag_row: dict[str, object] = {
                'data_id': did_int,
                'group_count': int(len(time_keys)),
                'min_bins_per_group': int(min(all_group_sizes)) if all_group_sizes else 0,
                'max_bins_per_group': int(max(all_group_sizes)) if all_group_sizes else 0,
                'median_bins_per_group': float(np.median(all_group_sizes)) if all_group_sizes else 0.0,
                'shared_bins_count': 0,
                'decision': 'kept',
                'decision_detail': '',
            }
            if not nsets:
                dropped_data_ids.append(did_int)
                diag_row['decision'] = 'dropped'
                diag_row['decision_detail'] = 'no valid n_deut bins found in any group'
                bin_diag_rows.append(diag_row)
                continue
            common = set.intersection(*nsets) if len(nsets) > 1 else set(nsets[0])
            diag_row['shared_bins_count'] = int(len(common))
            keep_sub = dgrp.copy()
            if len(common) >= int(min_bins_required):
                keep_sub = keep_sub[keep_sub['n_deut'].astype(int).isin(sorted(common))].copy()
                n_truncated_groups += 1
                diag_row['decision'] = 'trimmed_to_shared_bins'
                diag_row['decision_detail'] = f'kept shared bins across groups: {len(common)}'
            else:
                min_len = min(sizes) if sizes else 0
                if min_len < int(min_bins_required):
                    dropped_data_ids.append(did_int)
                    diag_row['decision'] = 'dropped'
                    diag_row['decision_detail'] = (
                        f'insufficient common/truncatable bins (min_len={min_len}, min_required={int(min_bins_required)})'
                    )
                    bin_diag_rows.append(diag_row)
                    continue
                trunc_parts: list[pd.DataFrame] = []
                for t_key in time_keys:
                    sub = keep_sub[keep_sub['time'] == float(t_key)].copy()
                    if sub.empty:
                        continue
                    # Keep one representative row per isotope bin within each time context.
                    sub = (
                        sub.sort_values(['n_deut', 'Intensity'], ascending=[True, False])
                        .drop_duplicates(subset=['n_deut'], keep='first')
                        .head(min_len)
                        .copy()
                    )
                    trunc_parts.append(sub)
                if not trunc_parts:
                    dropped_data_ids.append(did_int)
                    diag_row['decision'] = 'dropped'
                    diag_row['decision_detail'] = 'no groups remained after truncation pass'
                    bin_diag_rows.append(diag_row)
                    continue
                keep_sub = pd.concat(trunc_parts, ignore_index=True)
                n_truncated_groups += 1
                diag_row['decision'] = 'truncated_to_min_group_len'
                diag_row['decision_detail'] = f'truncated each group to min_len={min_len}'
            if keep_sub.empty:
                dropped_data_ids.append(did_int)
                diag_row['decision'] = 'dropped'
                diag_row['decision_detail'] = 'dataset empty after alignment filtering'
                bin_diag_rows.append(diag_row)
                continue
            aligned_parts.append(keep_sub)
            bin_diag_rows.append(diag_row)
        if aligned_parts:
            user_deut = pd.concat(aligned_parts, ignore_index=True)
            user_deut = (
                user_deut.sort_values(['data_id', 'time', 'rep', 'mz'])
                .reset_index(drop=True)
            )
        else:
            user_deut = pd.DataFrame(columns=user_deut.columns)
        if dropped_data_ids:
            _emit(
                84,
                f'Isotope-bin alignment dropped datasets with insufficient shared bins: {sorted(set(dropped_data_ids))}',
            )
        else:
            _emit(84, f'Isotope-bin alignment applied (groups adjusted={n_truncated_groups}).')
    if user_deut.empty:
        return (
            False,
            f'Derived pyHXExpress deutdata became empty after non-finite cleanup (input_rows={pre_rows}).',
            {},
        )
    removed_rows = pre_rows - len(user_deut)

    metadf = pd.DataFrame(metadf_rows).drop_duplicates(subset=['data_id']).sort_values('data_id').set_index('data_id')
    if metadf.empty:
        return False, 'Derived pyHXExpress metadf is empty.', {}

    _emit(82, f'Prepared fit inputs: datasets={metadf.shape[0]}, deut_rows={len(user_deut)}')
    try:
        did_rows = (
            user_deut.groupby('data_id', dropna=False)
            .size()
            .astype(int)
            .tolist()
        )
        if did_rows:
            _emit(
                82,
                'Per-dataset deut rows stats: '
                f"min={int(min(did_rows))}, median={int(np.median(did_rows))}, max={int(max(did_rows))}",
            )
    except Exception:
        pass
    _emit_phase(82, 'Fit inputs assembled', f'datasets={metadf.shape[0]}, deut_rows={len(user_deut)}')
    try:
        lbl_fit_counts = user_deut['label_h_or_d'].astype(str).str.upper().value_counts(dropna=False).to_dict()
        _emit(83, f'Fit-input labels: {lbl_fit_counts}')
    except Exception:
        pass
    if 'time' not in user_deut.columns:
        user_deut['time'] = 0.0
    if 'rep' not in user_deut.columns:
        user_deut['rep'] = 1
    user_deut['time'] = pd.to_numeric(user_deut['time'], errors='coerce').fillna(0.0).astype(float)
    user_deut['rep'] = pd.to_numeric(user_deut['rep'], errors='coerce').fillna(1).astype(int)
    user_deut['charge'] = pd.to_numeric(user_deut['charge'], errors='coerce').fillna(0).astype(float)
    user_deut['data_id'] = pd.to_numeric(user_deut['data_id'], errors='coerce').fillna(-1).astype(int)
    user_deut = user_deut[user_deut['data_id'] >= 0].copy()
    if user_deut.empty:
        return False, 'Derived pyHXExpress deutdata has no valid data_id rows.', {}

    user_deut['time_idx'] = 0
    for did, grp in user_deut.groupby('data_id', dropna=False):
        tvals = sorted(set(float(x) for x in pd.to_numeric(grp['time'], errors='coerce').dropna().tolist()))
        tmap = {tv: i for i, tv in enumerate(tvals)}
        user_deut.loc[grp.index, 'time_idx'] = [int(tmap.get(float(tv), 0)) for tv in grp['time'].tolist()]

    # Guard against shape/indexing failures in pyHXExpress internals:
    # require binary-label context per data_id with at least two distinct time values.
    # In this app's UN-vs-D mode this means one undeuterated-like time (0) and one D-like time (>0).
    def _binary_time_context_partition(df: pd.DataFrame) -> tuple[list[int], list[int], pd.DataFrame]:
        keep_ids: list[int] = []
        drop_ids: list[int] = []
        diag_rows: list[dict[str, object]] = []
        for did, grp in df.groupby('data_id', dropna=False):
            tvals = sorted(set(float(x) for x in pd.to_numeric(grp['time'], errors='coerce').dropna().tolist()))
            has_un_like = any(abs(float(tv)) < 1e-12 for tv in tvals)
            has_d_like = any(float(tv) > 0 for tv in tvals)
            label_vals = sorted(
                set(
                    str(x).upper()
                    for x in grp.get('label_h_or_d', pd.Series(dtype=str)).astype(str).tolist()
                    if str(x).strip() != ''
                )
            )
            decision = 'keep' if (len(tvals) >= 2 and has_un_like and has_d_like) else 'drop'
            if decision == 'keep':
                keep_ids.append(int(did))
            else:
                drop_ids.append(int(did))
            diag_rows.append(
                {
                    'data_id': int(did),
                    'n_rows': int(len(grp)),
                    'n_time_values': int(len(tvals)),
                    'has_un_like_time': bool(has_un_like),
                    'has_d_like_time': bool(has_d_like),
                    'labels_seen': '|'.join(label_vals),
                    'fragment_fit_key_nonempty_rows': int(
                        (grp.get('fragment_fit_key', pd.Series('', index=grp.index)).astype(str).str.strip() != '').sum()
                    ),
                    'decision': decision,
                }
            )
        diag_df = pd.DataFrame(diag_rows)
        return keep_ids, drop_ids, diag_df

    keep_dids, drop_dids_time, context_diag_df = _binary_time_context_partition(user_deut)
    _emit(
        87,
        f'Binary UN/D context check: keep={len(keep_dids)}, drop={len(drop_dids_time)}, total={len(keep_dids) + len(drop_dids_time)}',
    )
    if drop_dids_time:
        _emit(
            88,
            'Dropping datasets lacking full binary UN/D time context: '
            + ', '.join(str(x) for x in sorted(set(drop_dids_time))),
        )
    if not keep_dids and not user_deut.empty:
        # Fallback: if fragment-level keys over-split H/UN and D into separate data_ids,
        # coalesce by peptide+charge+fragmentation_setting and re-check binary context.
        has_fragment_keys = (
            'fragment_fit_key' in user_deut.columns
            and (user_deut['fragment_fit_key'].astype(str).str.strip() != '').any()
        )
        if has_fragment_keys and {'peptide', 'charge', 'fragmentation_setting'}.issubset(user_deut.columns):
            _emit(88, 'No paired datasets after strict keying; retrying with coalesced keys (peptide+charge+fragmentation_setting)...')
            co_key = (
                user_deut['peptide'].astype(str).str.upper().str.strip()
                + '||'
                + pd.to_numeric(user_deut['charge'], errors='coerce').fillna(0).astype(int).astype(str)
                + '||'
                + user_deut['fragmentation_setting'].astype(str).str.strip().replace('', 'UNKNOWN')
            )
            co_codes, _ = pd.factorize(co_key, sort=True)
            user_deut_co = user_deut.copy()
            user_deut_co['data_id'] = pd.Series(co_codes, index=user_deut_co.index).astype(int)
            keep_co, drop_co, context_diag_co_df = _binary_time_context_partition(user_deut_co)
            _emit(
                89,
                f'Coalesced-key context check: keep={len(keep_co)}, drop={len(drop_co)}, total={len(keep_co) + len(drop_co)}',
            )
            if keep_co:
                user_deut = user_deut_co[user_deut_co['data_id'].isin(keep_co)].copy()
                meta_rows_co: list[dict[str, object]] = []
                for did, grp in user_deut.groupby('data_id', dropna=False):
                    pep0 = str(grp['peptide'].iloc[0]) if 'peptide' in grp.columns else ''
                    charge0 = float(pd.to_numeric(pd.Series([grp['charge'].iloc[0]]), errors='coerce').fillna(0).iloc[0])
                    frag0 = str(grp['fragmentation_setting'].iloc[0]) if 'fragmentation_setting' in grp.columns else 'UNKNOWN'
                    file_vals = sorted(set(str(v) for v in grp.get('file', pd.Series('', index=grp.index)).astype(str).tolist() if str(v).strip()))
                    file0 = file_vals[0] if file_vals else ''
                    meta_rows_co.append(
                        {
                            'data_id': int(did),
                            'file': file0,
                            'sample': sample_name,
                            'start_seq': 1,
                            'end_seq': int(max(1, len(pep0))),
                            'peptide_range': f'{1:04d}-{int(max(1, len(pep0))):04d}',
                            'charge': float(charge0),
                            'peptide': pep0,
                            'fragmentation_setting': frag0 or 'UNKNOWN',
                            'fragment_fit_key': '',
                        }
                    )
                metadf = (
                    pd.DataFrame(meta_rows_co)
                    .drop_duplicates(subset=['data_id'])
                    .sort_values('data_id')
                    .set_index('data_id')
                )
                context_diag_df = context_diag_co_df
                keep_dids = keep_co
                drop_dids_time = drop_co
                _emit(89, f'Recovered paired datasets via coalesced fallback: datasets={len(keep_dids)}')
            else:
                context_diag_df = context_diag_co_df
    if keep_dids:
        user_deut = user_deut[user_deut['data_id'].isin(keep_dids)].copy()
        metadf = metadf[metadf.index.isin(keep_dids)].copy()
    else:
        user_deut = pd.DataFrame(columns=user_deut.columns)
        metadf = pd.DataFrame(columns=metadf.columns)

    if user_deut.empty or metadf.empty:
        if not context_diag_df.empty:
            try:
                _emit(
                    89,
                    'Context-failure sample: '
                    + '; '.join(
                        [
                            f"data_id={int(r['data_id'])} rows={int(r['n_rows'])} times={int(r['n_time_values'])} labels={str(r['labels_seen'] or '-')}"
                            for _, r in context_diag_df.head(8).iterrows()
                        ]
                    ),
                )
            except Exception:
                pass
        return (
            False,
            'Derived pyHXExpress fit input has no datasets with complete binary UN/D time context after cleanup.',
            {},
        )

    metadf_input_csv = os.path.join(run_dir, _dedup_same_day_dates_in_name(f'{base}_pyhx_metadf_run_input__{ts}.csv'))
    deut_input_csv = os.path.join(run_dir, _dedup_same_day_dates_in_name(f'{base}_pyhx_deutdata_run_input__{ts}.csv'))
    _metadf_out = metadf.reset_index().copy()
    if 'data_id' in _metadf_out.columns:
        _metadf_out.insert(0, 'Index', pd.to_numeric(_metadf_out['data_id'], errors='coerce').fillna(-1).astype(int))
    _metadf_out.to_csv(metadf_input_csv, index=False)
    user_deut.to_csv(deut_input_csv, index=False)
    pyhx_user_config_py = ''
    ok_cfg, msg_cfg, cfg_path = _write_pyhxexpress_user_config(
        output_dir=run_dir,
        base_name=base,
        data_dir=run_dir,
        data_type=1,
        config_overrides=(pyhx_config_overrides or {}),
        metadf_file=os.path.basename(str(metadf_input_csv)),
    )
    if ok_cfg and cfg_path:
        pyhx_user_config_py = str(cfg_path)
        _emit(86, f'Generated pyHXExpress user config: {os.path.basename(pyhx_user_config_py)}')
    else:
        _emit(86, f'pyHXExpress user config was not generated: {msg_cfg}')
    _emit(86, 'Saved pyHXExpress run-input CSVs (metadf + deutdata).')
    _emit_phase(86, 'Run-input CSVs saved', f'metadf={os.path.basename(metadf_input_csv)}, deutdata={os.path.basename(deut_input_csv)}')
    try:
        did_stats = (
            user_deut.groupby('data_id', dropna=False)
            .agg(
                n_rows=('mz', 'size'),
                n_time=('time', 'nunique'),
                n_rep=('rep', 'nunique'),
            )
            .reset_index()
        )
        if not did_stats.empty:
            n_rows_vals = pd.to_numeric(did_stats['n_rows'], errors='coerce').dropna()
            msg = (
                f"Fit-engine debug: data_ids={len(did_stats)}, "
                f"rows_per_data_id[min/median/max]={int(n_rows_vals.min())}/{int(np.median(n_rows_vals))}/{int(n_rows_vals.max())}"
            )
            _emit(88, msg)
            preview_rows = did_stats.sort_values(['data_id']).head(8).to_dict(orient='records')
            for r in preview_rows:
                _emit(
                    89,
                    f"data_id={int(r.get('data_id', -1))} rows={int(r.get('n_rows', 0))} "
                    f"timepoints={int(r.get('n_time', 0))} reps={int(r.get('n_rep', 0))}",
                )
    except Exception:
        pass

    # Final strict numeric safety guard before entering pyHXExpress internals.
    # pyHXExpress may cast integer-like columns with astype(int); if any NA/inf
    # survives to this point, it can raise IntCastingNaNError inside the engine.
    pre_engine_rows = int(len(user_deut))
    int_like_cols = [c for c in ['data_id', 'rep', 'time_idx', 'n_deut'] if c in user_deut.columns]
    for c in int_like_cols:
        user_deut[c] = pd.to_numeric(user_deut[c], errors='coerce')
    float_like_cols = [c for c in ['mz', 'Intensity', 'time', 'charge', 'max_namides', 'env_width', 'env_symm'] if c in user_deut.columns]
    for c in float_like_cols:
        user_deut[c] = pd.to_numeric(user_deut[c], errors='coerce')
    user_deut = user_deut.replace([np.inf, -np.inf], np.nan)
    required_pre_engine = [c for c in ['data_id', 'rep', 'time_idx', 'n_deut', 'mz', 'Intensity', 'time'] if c in user_deut.columns]
    if required_pre_engine:
        user_deut = user_deut.dropna(subset=required_pre_engine).copy()
    for c in int_like_cols:
        if c in user_deut.columns:
            user_deut[c] = pd.to_numeric(user_deut[c], errors='coerce').fillna(-1).astype(int)
    if 'data_id' in user_deut.columns:
        user_deut = user_deut[user_deut['data_id'] >= 0].copy()
    if 'rep' in user_deut.columns:
        user_deut = user_deut[user_deut['rep'] > 0].copy()
    if 'n_deut' in user_deut.columns:
        user_deut = user_deut[user_deut['n_deut'] >= 0].copy()
    if user_deut.empty:
        return (
            False,
            'Derived pyHXExpress fit input became empty during final numeric safety guard (non-finite integer-like values).',
            {'run_dir': run_dir, 'metadf_input_csv': metadf_input_csv, 'deutdata_input_csv': deut_input_csv},
        )
    dropped_pre_engine = int(max(0, pre_engine_rows - len(user_deut)))
    _emit(
        89,
        'Final numeric safety guard: '
        f'rows_before={pre_engine_rows}, rows_after={len(user_deut)}, dropped={dropped_pre_engine}',
    )
    # Pre-fit viability guard:
    # pyHXExpress can crash or emit empty data_fits when any time/rep condition
    # has only one isotope curve (N=1). Require >=2 unique n_deut per (time,rep)
    # within each data_id before entering run_hdx_fits.
    try:
        fitable_ids: list[int] = []
        unfit_rows: list[dict[str, object]] = []
        grouped_did = list(user_deut.groupby('data_id', dropna=False))
        for did, grp_did in grouped_did:
            min_curves = 10**9
            cond_summary: list[str] = []
            for (t_v, r_v), grp_tr in grp_did.groupby(['time', 'rep'], dropna=False):
                n_curves = int(pd.to_numeric(grp_tr.get('n_deut'), errors='coerce').dropna().astype(int).nunique())
                min_curves = min(min_curves, n_curves)
                cond_summary.append(f't={float(t_v):g}/r={int(r_v)}:N={n_curves}')
            if min_curves >= 2:
                fitable_ids.append(int(did))
            else:
                unfit_rows.append(
                    {
                        'data_id': int(did),
                        'min_curves_per_time_rep': int(min_curves if min_curves != 10**9 else 0),
                        'conditions': '; '.join(cond_summary[:12]),
                    }
                )
        if unfit_rows:
            _emit(
                89,
                f'Pre-fit viability dropped datasets with N<2 curves in at least one time/rep condition: {len(unfit_rows)}',
            )
            try:
                preview = ', '.join(str(int(r['data_id'])) for r in unfit_rows[:12])
                _emit(89, f'Unfit data_id sample: {preview}')
            except Exception:
                pass
        if fitable_ids:
            user_deut = user_deut[user_deut['data_id'].isin(fitable_ids)].copy()
            metadf = metadf[metadf.index.isin(fitable_ids)].copy()
        else:
            user_deut = pd.DataFrame(columns=user_deut.columns)
            metadf = pd.DataFrame(columns=metadf.columns)
        if unfit_rows:
            try:
                unfit_csv = os.path.join(run_dir, _dedup_same_day_dates_in_name(f'{base}_prefit_viability_dropped__{ts}.csv'))
                pd.DataFrame(unfit_rows).to_csv(unfit_csv, index=False)
                _emit(89, f'Wrote pre-fit viability diagnostics: {os.path.basename(unfit_csv)}')
            except Exception:
                pass
    except Exception:
        pass
    if user_deut.empty or metadf.empty:
        return (
            False,
            'No fitable datasets remain after pre-fit viability check (requires >=2 isotope curves per time/rep condition).',
            {'run_dir': run_dir, 'metadf_input_csv': metadf_input_csv, 'deutdata_input_csv': deut_input_csv},
        )

    cfg = pyhx_hxex.config
    cfg_backup = {
        'Output_DIR': getattr(cfg, 'Output_DIR', ''),
        'Data_DIR': getattr(cfg, 'Data_DIR', ''),
        'Data_Type': getattr(cfg, 'Data_Type', 1),
        'Generate_Plots': getattr(cfg, 'Generate_Plots', True),
        'WRITE_PARAMS': getattr(cfg, 'WRITE_PARAMS', True),
        'Allow_Overwrite': getattr(cfg, 'Allow_Overwrite', True),
        'Keep_Raw': getattr(cfg, 'Keep_Raw', True),
        'Nex_Max_Scale': getattr(cfg, 'Nex_Max_Scale', 1.2),
        'floor_correction_mode': getattr(cfg, 'floor_correction_mode', 'none'),
    }
    fallback_recovered = False
    fallback_failed_count = 0
    per_data_id_fail_csv = ''
    try:
        cfg.Output_DIR = os.path.join(run_dir, '')
        cfg.Data_DIR = out_dir
        cfg.Data_Type = int((pyhx_config_overrides or {}).get('Data_Type', 1))
        cfg.Generate_Plots = bool((pyhx_config_overrides or {}).get('Generate_Plots', True))
        cfg.Hide_Figure_Output = bool((pyhx_config_overrides or {}).get('Hide_Figure_Output', True))
        cfg.WRITE_PARAMS = bool((pyhx_config_overrides or {}).get('WRITE_PARAMS', True))
        cfg.Allow_Overwrite = bool((pyhx_config_overrides or {}).get('Allow_Overwrite', True))
        cfg.Keep_Raw = bool((pyhx_config_overrides or {}).get('Keep_Raw', False))
        # Enforce physical cap by default; still user-overridable.
        cfg.Nex_Max_Scale = float((pyhx_config_overrides or {}).get('Nex_Max_Scale', 1.0))
        for _k, _v in dict((pyhx_config_overrides or {})).items():
            try:
                if hasattr(cfg, str(_k)):
                    setattr(cfg, str(_k), _v)
            except Exception:
                continue
        _emit(
            89,
            f'pyHXExpress config snapshot: FullDeut_Time={full_deut_time}, '
            f'Peak_Resolution={float(getattr(pyhx_hxex.config, "Peak_Resolution", 50.0) or 50.0)}, '
            f'Generate_Plots={bool(cfg.Generate_Plots)}, Nex_Max_Scale={float(getattr(cfg, "Nex_Max_Scale", 1.0) or 1.0):.3f}, '
            f'floor_correction_mode={str(getattr(cfg, "floor_correction_mode", "none") or "none")}',
        )
        _emit(
            89,
            'Engine preflight summary: '
            f"datasets={int(metadf.shape[0])}, unique_times={int(user_deut['time'].nunique()) if 'time' in user_deut.columns else 0}, "
            f"unique_reps={int(user_deut['rep'].nunique()) if 'rep' in user_deut.columns else 0}",
        )
        _emit(90, 'Running pyHXExpress fit engine (run_hdx_fits)...')
        _emit_phase(90, 'Entering fit engine', f'datasets={int(metadf.shape[0])}')
        pyhx_hxex.run_hdx_fits(metadf, user_deutdata=user_deut, update_deutdata=False)
        _emit_phase(96, 'Fit engine returned', 'collecting output artifacts')
    except Exception as e:
        err_txt = str(e)
        _emit(91, f'run_hdx_fits exception: {err_txt}')
        try:
            tb_tail = traceback.format_exc().splitlines()[-12:]
            for ln in tb_tail:
                if str(ln).strip():
                    _emit(91, f'TRACEBACK: {ln}')
        except Exception:
            pass
        # Fallback: if batch fit collapses due to known pyHXExpress internals,
        # retry dataset-by-dataset to salvage successful fits and isolate failures.
        err_low = str(err_txt or '').lower()
        retry_per_data_id = bool(
            ('too many indices for array' in err_low and '1-dimensional' in err_low)
            or (
                'best_fit' in err_low
                and (
                    'unboundlocalerror' in err_low
                    or 'cannot access local variable' in err_low
                )
            )
        )
        if retry_per_data_id:
            if 'best_fit' in err_low:
                _emit(91, 'Batch fit hit pyHXExpress best_fit internal error; retrying one data_id at a time...')
            else:
                _emit(91, 'Batch fit hit 1D/2D indexing mismatch; retrying one data_id at a time...')
            ok_ids: list[int] = []
            fail_rows: list[dict[str, object]] = []
            all_ids = [int(x) for x in metadf.index.tolist()]
            total_ids = max(1, len(all_ids))
            for i, did in enumerate(all_ids, start=1):
                md_i = metadf.loc[[did]].copy() if did in metadf.index else pd.DataFrame()
                ud_i = user_deut[user_deut['data_id'] == int(did)].copy()
                if md_i.empty or ud_i.empty:
                    fail_rows.append({'data_id': int(did), 'error': 'empty_subset_after_filter'})
                    continue
                sub_dir = os.path.join(run_dir, f'data_id_{int(did)}')
                os.makedirs(sub_dir, exist_ok=True)
                try:
                    cfg.Output_DIR = os.path.join(sub_dir, '')
                    pyhx_hxex.run_hdx_fits(md_i, user_deutdata=ud_i, update_deutdata=False)
                    ok_ids.append(int(did))
                except Exception as sub_e:
                    fail_rows.append({'data_id': int(did), 'error': str(sub_e)})
                _emit(91 + int(8 * (i / total_ids)), f'Per-data_id retry {i}/{total_ids}: data_id={did}')

            if ok_ids:
                _emit(
                    99,
                    f'Per-data_id fallback completed: succeeded={len(ok_ids)}, failed={len(fail_rows)}',
                )
                fallback_recovered = True
                fallback_failed_count = int(len(fail_rows))
                if fail_rows:
                    try:
                        per_data_id_fail_csv = os.path.join(run_dir, _dedup_same_day_dates_in_name(f'{base}_per_data_id_failures__{ts}.csv'))
                        pd.DataFrame(fail_rows).to_csv(per_data_id_fail_csv, index=False)
                    except Exception:
                        pass
                # Continue to artifact discovery below and return success with warning text.
                err_family = 'shape_or_internal_error'
                if 'best_fit' in err_low:
                    err_family = 'best_fit_internal_error'
                err_txt = (
                    f'batch_fit_failed_with_{err_family}; per_data_id_fallback_recovered={len(ok_ids)}; '
                    f'per_data_id_failed={len(fail_rows)}'
                )
            else:
                friendly = (
                    " Human-readable explanation: at least one dataset collapsed to a 1D shape during fitting "
                    "but pyHXExpress attempted 2D indexing. This usually means that after filtering/alignment, "
                    "a dataset did not retain a full UN-vs-D pair with stable bin structure. The app attempted "
                    "per-data_id fallback, but none of the datasets fit successfully."
                )
                return (
                    False,
                    f'pyHXExpress fit run failed: {err_txt}.{friendly}',
                    {'run_dir': run_dir, 'metadf_input_csv': metadf_input_csv, 'deutdata_input_csv': deut_input_csv},
                )
        friendly = ''
        if 'operands could not be broadcast together with shapes' in err_txt:
            friendly = (
                " Human-readable explanation: pyHXExpress tried to compare two isotope-envelope vectors that "
                "had different lengths (for example 7 bins vs 4 bins) within what it expected to be the same "
                "dataset/condition shape. This usually means one run/time/rep group has extra or missing isotope "
                "bins after peak-picking. The app now performs isotope-bin alignment before fitting, but this error "
                "can still occur if remaining groups are highly inconsistent."
            )
        elif 'too many indices for array' in err_txt and '1-dimensional' in err_txt:
            friendly = (
                " Human-readable explanation: at least one dataset collapsed to a 1D shape during fitting "
                "but pyHXExpress attempted 2D indexing. This usually means that after filtering/alignment, "
                "a dataset did not retain a full UN-vs-D pair with stable bin structure. The app now drops "
                "datasets without complete binary UN/D time context before fitting."
            )
        elif 'UnboundLocalError' in err_txt and 'best_fit' in err_txt:
            friendly = (
                " Human-readable explanation: pyHXExpress raised an internal `best_fit` assignment error in batch mode. "
                "The app retries per data_id to salvage successful fits and isolate any failing datasets."
            )
        if not fallback_recovered:
            return (
                False,
                f'pyHXExpress fit run failed: {err_txt}.{friendly}',
                {'run_dir': run_dir, 'metadf_input_csv': metadf_input_csv, 'deutdata_input_csv': deut_input_csv},
            )
    finally:
        for k, v in cfg_backup.items():
            try:
                setattr(cfg, k, v)
            except Exception:
                pass

    csvs = _sort_existing_paths_by_mtime_desc(_find_files(run_dir, ('.csv',)))
    data_fits_csv = next((p for p in csvs if 'data_fits_asrun_' in os.path.basename(p)), '')
    fitparams_csv = next((p for p in csvs if 'fitparamsAll_asrun_' in os.path.basename(p)), '')
    metadf_asrun_csv = next((p for p in csvs if 'metadf_asrun_' in os.path.basename(p)), '')
    out_paths = {
        'run_dir': run_dir,
        'metadf_input_csv': metadf_input_csv,
        'deutdata_input_csv': deut_input_csv,
        'pyhx_user_config_py': pyhx_user_config_py,
        'metadf_asrun_csv': metadf_asrun_csv,
        'data_fits_asrun_csv': data_fits_csv,
        'fitparams_asrun_csv': fitparams_csv,
    }
    if per_data_id_fail_csv and os.path.isfile(per_data_id_fail_csv):
        out_paths['per_data_id_failures_csv'] = per_data_id_fail_csv
    if bin_diag_rows:
        try:
            bin_diag_csv = os.path.join(run_dir, _dedup_same_day_dates_in_name(f'{base}_bin_alignment_diagnostics__{ts}.csv'))
            pd.DataFrame(bin_diag_rows).sort_values(['data_id']).to_csv(bin_diag_csv, index=False)
            out_paths['bin_alignment_diagnostics_csv'] = bin_diag_csv
        except Exception:
            pass
    msg = (
        f"[scan-match-v2] pyHXExpress fit run completed: datasets={metadf.shape[0]}, "
        f"deut_rows={len(user_deut)}, cleaned_rows_removed={removed_rows}, output_dir={run_dir}"
    )
    if fallback_recovered:
        msg += f" (batch shape-error recovered by per-data_id fallback; failed_data_ids={fallback_failed_count})"
    elapsed = max(0.0, float(time.time() - run_t0))
    _emit(
        100,
        'Artifact discovery summary: '
        f"data_fits_asrun={'yes' if bool(data_fits_csv) else 'no'}, "
        f"fitparams_asrun={'yes' if bool(fitparams_csv) else 'no'}, "
        f"metadf_asrun={'yes' if bool(metadf_asrun_csv) else 'no'}",
    )
    _emit(100, f'Fit run completed and output artifacts were discovered (elapsed={elapsed:.1f}s).')
    return True, msg, out_paths


def _prepare_pyhxexpress_inputs(
    mode: str,
    out_dir: str,
    output_base: str,
    openms_csv: str = '',
    mzml_paths: list[str] | None = None,
    peptide_sequence: str = '',
    peptide_charges: list[int] | None = None,
    fragment_annotation_csv: str = '',
    selected_precursor_charges: list[int] | None = None,
    selected_activation_settings: list[str] | None = None,
    allow_fragment_propagation: bool = True,
    pyhx_config_overrides: dict[str, object] | None = None,
    nterm_subtract_for_uptake: int = 1,
    progress_cb=None,
) -> tuple[bool, str, dict[str, str]]:
    """
    Build pyHXExpress-ready input tables from either OpenMS CSV or peptide-mode scan inventories.
    """
    def _emit(pct: int, msg: str) -> None:
        if progress_cb is None:
            return
        try:
            progress_cb(max(0, min(100, int(pct))), str(msg))
        except Exception:
            pass

    def _resolve_working_dir_guess(path_hint: str) -> str:
        start = os.path.abspath(str(path_hint or '').strip()) if str(path_hint or '').strip() else ''
        if not start:
            return ''
        cur = start if os.path.isdir(start) else os.path.dirname(start)
        seen: set[str] = set()
        for _ in range(8):
            if (not cur) or (cur in seen):
                break
            seen.add(cur)
            try:
                sel = _selected_inventory_check_csv_path(cur)
                if sel and os.path.isfile(sel):
                    return cur
            except Exception:
                pass
            parent = os.path.dirname(cur)
            if (not parent) or (parent == cur):
                break
            cur = parent
        return os.path.abspath(os.path.dirname(path_hint)) if str(path_hint or '').strip() else ''

    _emit(1, 'Preparing pyHXExpress input tables...')
    if not out_dir:
        return False, 'Output directory not set.', {}
    os.makedirs(out_dir, exist_ok=True)
    base = _sanitize_name_token(output_base or 'pyhx_input') or 'pyhx_input'
    ts = _timestamp_token()
    prep_csv = os.path.join(out_dir, _dedup_same_day_dates_in_name(f'{base}_pyhx_spectra_input__{ts}.csv'))
    meta_csv = os.path.join(out_dir, _dedup_same_day_dates_in_name(f'{base}_pyhx_metadf_input__{ts}.csv'))

    cols = ['peptide_sequence', 'charge', 'scan', 'scan_id', 'source_mzml', 'source_mzml_path', 'label_h_or_d', 'fragment_fit_key', 'fragment_mono_mz', 'fragment_charge']
    df = pd.DataFrame(columns=cols)
    frag_csv = str(fragment_annotation_csv or '').strip()
    if not frag_csv or (not os.path.isfile(frag_csv)):
        return (
            False,
            'Fragment annotation CSV is required for HDX prep/fits to enforce filtered-fragment-only quantification.',
            {},
        )
    fragment_filter_requested = False
    fragment_filter_applied = False
    fragment_filter_total_rows = 0
    fragment_filter_kept_rows = 0
    mode_norm = str(mode or '').strip().lower()
    working_dir_guess = _resolve_working_dir_guess(out_dir)
    run_slot_map_global = _load_inventory_slot_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    source_slot_by_run_norm: dict[str, tuple[float, str, int, int, str]] = {}
    source_slot_by_path_abs: dict[str, tuple[float, str, int, int, str]] = {}
    for _rk, slot_v in (run_slot_map_global or {}).items():
        try:
            act_v, side_v, z_v, rep_v, p_v = slot_v
        except Exception:
            continue
        p_txt = str(p_v or '').strip()
        p_base = os.path.basename(p_txt) if p_txt else ''
        stem = os.path.splitext(p_base)[0] if p_base else ''
        slot_t = (float(act_v), str(side_v), int(z_v), int(rep_v), str(p_txt))
        for cand in (p_txt, p_base, stem):
            rn = _run_id_norm(cand)
            if rn:
                source_slot_by_run_norm[rn] = slot_t
        if p_txt:
            source_slot_by_path_abs[os.path.abspath(p_txt)] = slot_t

    def _slot_for_source(source_name: object, source_path: object) -> tuple[float, str, int, int, str] | None:
        p_txt = str(source_path or '').strip()
        if p_txt:
            p_abs = os.path.abspath(p_txt)
            if p_abs in source_slot_by_path_abs:
                return source_slot_by_path_abs[p_abs]
        for cand in (
            source_name,
            source_path,
            os.path.basename(str(source_name or '').strip()),
            os.path.basename(str(source_path or '').strip()),
            os.path.splitext(os.path.basename(str(source_name or '').strip()))[0],
            os.path.splitext(os.path.basename(str(source_path or '').strip()))[0],
        ):
            rn = _run_id_norm(cand)
            if rn and rn in source_slot_by_run_norm:
                return source_slot_by_run_norm[rn]
        return None
    if mode_norm.startswith('openms'):
        _emit(5, 'Loading OpenMS/Comet table for prep...')
        if not openms_csv or not os.path.isfile(openms_csv):
            return False, 'OpenMS CSV not found for OpenMS mode.', {}
        try:
            dfo = pd.read_csv(openms_csv)
        except Exception as e:
            return False, f'Could not read OpenMS CSV: {e}', {}
        required = ['peptide_sequence', 'charge', 'scan', 'scan_id', 'source_mzml', 'source_mzml_path']
        miss = [c for c in required if c not in dfo.columns]
        if miss:
            return False, f'OpenMS CSV missing required columns: {", ".join(miss)}', {}
        df = dfo[required].copy()
        if 'label_h_or_d' in dfo.columns:
            df['label_h_or_d'] = _resolve_hdx_labels_from_source(
                df['source_mzml'].astype(str),
                dfo['label_h_or_d'].astype(str),
            )
        else:
            df['label_h_or_d'] = _resolve_hdx_labels_from_source(
                df['source_mzml'].astype(str),
                None,
            )
        if 'ion_identity' in dfo.columns:
            df['fragment_fit_key'] = dfo['ion_identity'].astype(str).str.strip()
        elif 'fragment_matched_frags' in dfo.columns:
            df['fragment_fit_key'] = (
                dfo['fragment_matched_frags']
                .astype(str)
                .str.split(r'[,;|\s]+', regex=True)
                .str[0]
                .fillna('')
                .astype(str)
                .str.strip()
            )
        else:
            df['fragment_fit_key'] = ''
    else:
        _emit(5, 'Building peptide-mode scan table from mzML inventories...')
        seq = str(peptide_sequence or '').strip().upper()
        if not seq:
            return False, 'Peptide mode requires a peptide sequence.', {}
        z_keep = sorted(set(int(z) for z in (peptide_charges or []) if int(z) > 0))
        mzml_paths_effective: list[str] = []
        # Augment selected mzML scope with opposite-label sibling runs from
        # the same inventory slot (activation + precursor + replicate), matching
        # the plot-side condition pairing behavior.
        try:
            run_slot_map = dict(run_slot_map_global or {})
            slot_to_paths: dict[tuple[float, str, int, int], set[str]] = {}
            path_to_slots: dict[str, list[tuple[float, str, int, int]]] = {}
            for _rn, slot_v in (run_slot_map or {}).items():
                try:
                    act_v, side_v, z_v, rep_v, p_v = slot_v
                except Exception:
                    continue
                p_abs = os.path.abspath(str(p_v or '').strip()) if str(p_v or '').strip() else ''
                if not p_abs or (not os.path.isfile(p_abs)):
                    continue
                k_slot = (float(act_v), str(side_v), int(z_v), int(rep_v))
                slot_to_paths.setdefault(k_slot, set()).add(p_abs)
                path_to_slots.setdefault(p_abs, []).append(k_slot)
            requested_paths = [
                os.path.abspath(str(p).strip())
                for p in (mzml_paths or [])
                if str(p).strip() and os.path.isfile(str(p).strip())
            ]
            mzml_aug: set[str] = set(requested_paths)
            added_pair_paths: set[str] = set()
            for p_abs in requested_paths:
                for slot in path_to_slots.get(p_abs, []):
                    act_v, side_v, z_v, rep_v = slot
                    opposite_side = 'D' if str(side_v) != 'D' else 'H/UN'
                    cand_same_rep = slot_to_paths.get((float(act_v), str(opposite_side), int(z_v), int(rep_v)), set()) or set()
                    cands = set(cand_same_rep)
                    # Fallback: same activation + precursor on opposite side when replicate
                    # index does not exist for one side.
                    if not cands:
                        for (a2, s2, z2, _r2), pset in slot_to_paths.items():
                            if (float(a2) == float(act_v)) and (str(s2) == str(opposite_side)) and (int(z2) == int(z_v)):
                                cands.update(set(pset or set()))
                    for cp in cands:
                        if cp not in mzml_aug:
                            added_pair_paths.add(cp)
                        mzml_aug.add(cp)
            mzml_paths_effective = sorted(list(mzml_aug))
            if added_pair_paths:
                _emit(
                    6,
                    f'Augmented peptide-mode mzML scope with paired-condition siblings: +{len(added_pair_paths)} file(s)',
                )
        except Exception:
            mzml_paths_effective = []
        if not mzml_paths_effective:
            mzml_paths_effective = [
                str(p).strip()
                for p in (mzml_paths or [])
                if str(p).strip() and os.path.isfile(str(p).strip())
            ]
        rows: list[dict[str, object]] = []
        for mzml in mzml_paths_effective:
            p = str(mzml or '').strip()
            if not p or not os.path.isfile(p):
                continue
            run_id = os.path.splitext(os.path.basename(p))[0]
            inv = os.path.join(os.path.dirname(p), run_id + '_scan_inventory.csv')
            if not os.path.isfile(inv):
                continue
            try:
                dfi = pd.read_csv(inv, usecols=['scan_number', 'ms_level', 'charge_state', 'precursor_charge_state'])
            except Exception:
                continue
            dfi['ms_level'] = pd.to_numeric(dfi.get('ms_level'), errors='coerce')
            dfi = dfi[dfi['ms_level'] == 2].copy()
            if dfi.empty:
                continue
            slot_v = _slot_for_source(os.path.basename(p), p)
            if slot_v is None:
                continue
            _act_v, side_v, z_v, _rep_v, _p_slot = slot_v
            dfi['charge'] = int(z_v)
            if z_keep:
                dfi = dfi[dfi['charge'].isin(z_keep)].copy()
            if dfi.empty:
                continue
            lbl = 'D' if str(side_v).strip().upper() == 'D' else 'UN'
            for _, rr in dfi.iterrows():
                scan_no = pd.to_numeric(pd.Series([rr.get('scan_number')]), errors='coerce').iloc[0]
                if pd.isna(scan_no):
                    continue
                charge_i = pd.to_numeric(pd.Series([rr.get('charge')]), errors='coerce').iloc[0]
                if pd.isna(charge_i):
                    continue
                scan_int = int(round(float(scan_no)))
                ch_int = int(round(float(charge_i)))
                rows.append(
                    {
                        'peptide_sequence': seq,
                        'charge': ch_int,
                        'scan': scan_int,
                        'scan_id': f'{run_id}:{scan_int}',
                        'source_mzml': os.path.basename(p),
                        'source_mzml_path': p,
                        'label_h_or_d': lbl,
                        'fragment_fit_key': '',
                    }
                )
        if not rows:
            return False, 'No peptide-mode MS2 rows were prepared from selected mzML scan inventories.', {}
        df = pd.DataFrame(rows, columns=cols)

        # Fragment mapping enforcement is applied below for all modes.

    if df.empty:
        return False, 'Prepared pyHXExpress input is empty.', {}

    df['peptide_sequence'] = df['peptide_sequence'].astype(str).str.strip().str.upper()
    df['charge'] = pd.to_numeric(df['charge'], errors='coerce').fillna(0).astype(int)
    df['scan'] = pd.to_numeric(df['scan'], errors='coerce').fillna(0).astype(int)
    df['scan_id'] = df['scan_id'].astype(str)
    df['source_mzml'] = df['source_mzml'].astype(str)
    df['source_mzml_path'] = df['source_mzml_path'].astype(str)
    df['label_h_or_d'] = df['label_h_or_d'].astype(str).str.upper()
    inv_act_norm: list[str] = []
    inv_side_lbl: list[str] = []
    inv_pz: list[int] = []
    inv_rep: list[int] = []
    inv_mapped: list[bool] = []
    for src_nm, src_p in zip(df['source_mzml'].astype(str).tolist(), df['source_mzml_path'].astype(str).tolist()):
        slot_v = _slot_for_source(src_nm, src_p)
        if slot_v is None:
            inv_mapped.append(False)
            inv_act_norm.append('')
            inv_side_lbl.append('')
            inv_pz.append(0)
            inv_rep.append(0)
            continue
        act_v, side_v, z_v, rep_v, _p_slot = slot_v
        side_lbl = 'D' if str(side_v).strip().upper() == 'D' else 'UN'
        ms_txt = f"{int(round(float(act_v)))}ms" if abs(float(act_v) - round(float(act_v))) < 1e-9 else f"{float(act_v):g}ms"
        inv_mapped.append(True)
        inv_act_norm.append(_sanitize_name_token(str(ms_txt)).upper())
        inv_side_lbl.append(side_lbl)
        inv_pz.append(int(z_v) if int(z_v) > 0 else 0)
        inv_rep.append(int(rep_v) if int(rep_v) > 0 else 1)
    df['_inv_mapped'] = pd.Series(inv_mapped, index=df.index).astype(bool)
    unmapped_inv_rows = int((~df['_inv_mapped']).sum())
    if unmapped_inv_rows > 0:
        _emit(14, f'Dropping rows without terminology slot mapping: {unmapped_inv_rows}')
    df = df[df['_inv_mapped']].copy()
    if df.empty:
        return False, 'No rows map to terminology inventory slots; cannot proceed without terminology ground truth.', {}
    df['_inv_activation_setting_norm'] = pd.Series(inv_act_norm, index=pd.RangeIndex(len(inv_act_norm))).reindex(df.index).fillna('').astype(str)
    df['_inv_side_label'] = pd.Series(inv_side_lbl, index=pd.RangeIndex(len(inv_side_lbl))).reindex(df.index).fillna('').astype(str)
    df['_inv_precursor_charge'] = pd.Series(inv_pz, index=pd.RangeIndex(len(inv_pz))).reindex(df.index).fillna(0).astype(int)
    df['_inv_replicate_index'] = pd.Series(inv_rep, index=pd.RangeIndex(len(inv_rep))).reindex(df.index).fillna(1).astype(int)
    df['label_h_or_d'] = df['_inv_side_label'].astype(str).str.upper()
    df['charge'] = pd.to_numeric(df['_inv_precursor_charge'], errors='coerce').fillna(0).astype(int)
    # pyHXExpress state mapping: treat app H/UN as undeut side, D as TD.
    df['run_type_pyhx'] = df['label_h_or_d'].apply(_map_hdx_label_to_pyhx_state).astype(str)
    df['pyhx_state'] = df['run_type_pyhx'].astype(str)
    if 'fragment_fit_key' not in df.columns:
        df['fragment_fit_key'] = ''
    df['fragment_fit_key'] = df['fragment_fit_key'].astype(str).str.strip()
    df = df[(df['peptide_sequence'] != '') & (df['charge'] > 0) & (df['scan'] > 0)].copy()
    if df.empty:
        return False, 'Prepared pyHXExpress input has no valid rows after cleanup.', {}
    _emit(16, f'Base prep rows ready: {len(df)}')

    nterm_subtract_i = int(max(0, int(nterm_subtract_for_uptake or 0)))

    def _fit_subseq_and_uptake(row: pd.Series) -> tuple[str, int, int]:
        pep_full = re.sub(r'[^A-Za-z]', '', str(row.get('peptide_sequence', '') or '')).strip().upper()
        if not pep_full:
            return '', 0, 0
        fk = str(row.get('fragment_fit_key', '') or '').strip()
        frag_sub = _fragment_subsequence_from_fragment_fit_key(fk, pep_full) if fk else ''
        fit_seq = str(frag_sub or pep_full).strip().upper()
        fit_len = int(len(re.sub(r'[^A-Z]', '', fit_seq)))
        n_pro = fit_seq[nterm_subtract_i:].count('P') if fit_len > nterm_subtract_i else 0
        max_uptake = int(max(0, fit_len - nterm_subtract_i - n_pro))
        return fit_seq, fit_len, max_uptake

    fit_triplets = df.apply(_fit_subseq_and_uptake, axis=1)
    df['fragment_subsequence_for_fit'] = [str(t[0]) for t in fit_triplets.tolist()]
    df['subsequence_length_for_fit'] = [int(t[1]) for t in fit_triplets.tolist()]
    df['max_uptake_d_for_fit'] = [int(t[2]) for t in fit_triplets.tolist()]
    def _activation_setting_norm_canonical(v: object) -> str:
        """
        Canonical activation token used in fragment contract matching.
        Normalizes variants like UVPD_0004MS, 0004ms, and 4ms -> 4MS.
        """
        tok = _sanitize_name_token(str(v or '')).upper()
        if not tok:
            return ''
        m_ms = re.search(r'(?<!\d)(\d+)MS(?!\d)', tok)
        if m_ms:
            try:
                return f"{int(m_ms.group(1))}MS"
            except Exception:
                return f"{str(m_ms.group(1)).lstrip('0') or '0'}MS"
        m_num = re.search(r'(?<!\d)(\d+)(?!\d)', tok)
        if m_num:
            try:
                return f"{int(m_num.group(1))}MS"
            except Exception:
                pass
        return tok
    sel_pz = sorted(set(int(z) for z in (selected_precursor_charges or []) if int(z) > 0))
    sel_act_norm = sorted(
        set(
            _activation_setting_norm_canonical(v)
            for v in (selected_activation_settings or [])
            if str(v).strip()
        )
    )
    # Normalize fit charge to precursor/peptide charge, not fragment/product-ion charge.
    df['_prep_precursor_charge'] = pd.to_numeric(df['_inv_precursor_charge'], errors='coerce').fillna(0).astype(int)
    df['charge'] = pd.to_numeric(df['_prep_precursor_charge'], errors='coerce').fillna(0).astype(int)
    df['_prep_activation_setting_norm'] = df['_inv_activation_setting_norm'].apply(_activation_setting_norm_canonical).astype(str)
    if sel_pz or sel_act_norm:
        before_filter_rows = int(len(df))
        avail_pz = sorted(
            set(
                int(v) for v in pd.to_numeric(df['_prep_precursor_charge'], errors='coerce').dropna().astype(int).tolist()
                if int(v) > 0
            )
        )
        avail_act_norm = sorted(
            set(
                str(v).strip().upper()
                for v in df['_prep_activation_setting_norm'].astype(str).tolist()
                if str(v).strip()
            )
        )
        if sel_pz:
            df = df[df['_prep_precursor_charge'].isin(sel_pz)].copy()
        if sel_act_norm:
            df = df[df['_prep_activation_setting_norm'].isin(sel_act_norm)].copy()
        _emit(17, f'Applied UI filters (activation/precursor): kept {len(df)}/{before_filter_rows} rows')
        if df.empty:
            sel_z_txt = ','.join([f'Z{int(v)}' for v in sel_pz]) if sel_pz else 'none'
            sel_act_txt = ','.join([str(v) for v in sel_act_norm]) if sel_act_norm else 'none'
            avail_z_txt = ','.join([f'Z{int(v)}' for v in avail_pz]) if avail_pz else 'none'
            avail_act_txt = ','.join([str(v) for v in avail_act_norm]) if avail_act_norm else 'none'
            return (
                False,
                'No rows remain after applying selected precursor charge / activation setting filters. '
                f'Selected charges: {sel_z_txt}; selected activation settings: {sel_act_txt}. '
                f'Available charges in prep rows: {avail_z_txt}; available activation settings: {avail_act_txt}. '
                'Try selecting all charge/activation checkboxes in HDX Fits.',
                {},
            )
    if '_prep_precursor_charge' in df.columns:
        df = df.drop(columns=['_prep_precursor_charge'])
    if '_prep_activation_setting_norm' in df.columns:
        df = df.drop(columns=['_prep_activation_setting_norm'])
    if '_inv_mapped' in df.columns:
        df = df.drop(columns=['_inv_mapped'])

    # Strict filtered-fragment-only enforcement for all HDX prep modes.
    fragment_filter_requested = True
    try:
        fdf = pd.read_csv(frag_csv)
    except Exception:
        fdf = pd.DataFrame()
    _emit(20, f'Loaded filtered fragment list CSV: {os.path.basename(frag_csv)}')
    if fdf is None or fdf.empty:
        return False, 'Selected fragment annotation CSV is empty; cannot enforce filtered-fragment-only fitting.', {}
    run_method_map = _load_name_mapping_activation_method_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    run_setting_map = _load_name_mapping_activation_setting_ms_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    scan_col = next((c for c in ['scan', 'scan_number', 'scan_num', 'spectrum_scan'] if c in fdf.columns), None)
    src_col = next((c for c in ['source_mzml', 'mzml', 'file', 'run', 'run_name'] if c in fdf.columns), None)
    frag_col = next((c for c in ['ion_identity', 'fragment_fit_key', 'fragment_id', 'fragment', 'fragment_matched_frags'] if c in fdf.columns), None)
    pep_col = next((c for c in ['peptide_sequence', 'plain_peptide', 'peptide', 'sequence'] if c in fdf.columns), None)
    precursor_ch_col = next(
        (c for c in ['precursor_charge', 'charge', 'charge_state', 'precursor_charge_state', 'z'] if c in fdf.columns),
        None,
    )
    fragment_ch_col = next(
        (c for c in ['fragment_charge', 'product_charge', 'ion_charge', 'fragment_z'] if c in fdf.columns),
        None,
    )
    frag_subseq_col = next(
        (c for c in ['fragment_subsequence', 'frag_subsequence', 'subsequence', 'fragment_sequence', 'ion_subsequence'] if c in fdf.columns),
        None,
    )
    act_col = next(
        (c for c in ['activation_setting', 'activation_setting_from_name', 'activation', 'activation_setting_ms'] if c in fdf.columns),
        None,
    )
    frag_mono_mz_col = next(
        (c for c in ['fragment_mono_mz', 'fragment_matched_frags_predicted_mz', 'predicted_mz', 'mz'] if c in fdf.columns),
        None,
    )
    if not (scan_col and src_col and frag_col):
        return (
            False,
            'Selected fragment annotation CSV does not contain required mapping columns '
            '(scan + source_mzml + fragment identity); cannot enforce filtered-fragment-only fitting.',
            {},
        )
    map_cols = [scan_col, src_col, frag_col]
    if pep_col:
        map_cols.append(pep_col)
    if precursor_ch_col:
        map_cols.append(precursor_ch_col)
    if fragment_ch_col:
        map_cols.append(fragment_ch_col)
    if act_col:
        map_cols.append(act_col)
    if frag_subseq_col:
        map_cols.append(frag_subseq_col)
    if frag_mono_mz_col:
        map_cols.append(frag_mono_mz_col)
    map_df = fdf[map_cols].copy()
    map_df['scan'] = pd.to_numeric(map_df[scan_col], errors='coerce').astype('Int64')
    map_df['source_mzml'] = map_df[src_col].astype(str).apply(lambda x: os.path.basename(str(x).strip()))
    map_df['fragment_fit_key'] = map_df[frag_col].astype(str).str.strip()
    # Explode comma-separated fragment lists so each row = one scan × one fragment.
    _has_multi = map_df['fragment_fit_key'].str.contains(',', na=False)
    if _has_multi.any():
        _fk_split = map_df['fragment_fit_key'].str.split(r'\s*,\s*', regex=True)
        if frag_mono_mz_col and frag_mono_mz_col in map_df.columns:
            _mz_split = map_df[frag_mono_mz_col].astype(str).str.split(r'\s*,\s*', regex=True)
        else:
            _mz_split = None
        exploded_rows: list[pd.DataFrame] = []
        for idx in map_df.index:
            fk_list = _fk_split.at[idx]
            if not isinstance(fk_list, list) or len(fk_list) <= 1:
                exploded_rows.append(map_df.loc[[idx]])
                continue
            n_frags = len(fk_list)
            expanded = pd.DataFrame([map_df.loc[idx]] * n_frags).reset_index(drop=True)
            expanded['fragment_fit_key'] = [str(f).strip() for f in fk_list]
            if _mz_split is not None:
                mz_list = _mz_split.at[idx]
                if isinstance(mz_list, list) and len(mz_list) == n_frags:
                    expanded[frag_mono_mz_col] = [str(v).strip() for v in mz_list]
                else:
                    expanded[frag_mono_mz_col] = str(np.nan)
            exploded_rows.append(expanded)
        map_df = pd.concat(exploded_rows, ignore_index=True)
        _emit(30, f'Exploded multi-fragment annotation rows: {_has_multi.sum()} rows → {len(map_df)} (one per fragment)')
    if act_col:
        map_df['activation_setting'] = map_df[act_col].astype(str).str.strip()
    else:
        map_df['activation_setting'] = ''
    if pep_col:
        map_df['peptide_sequence'] = map_df[pep_col].astype(str).str.strip().str.upper()
    else:
        map_df['peptide_sequence'] = ''
    if precursor_ch_col:
        map_df['precursor_charge'] = pd.to_numeric(map_df[precursor_ch_col], errors='coerce').round().astype('Int64')
    else:
        map_df['precursor_charge'] = pd.Series(pd.array([pd.NA] * len(map_df), dtype='Int64'), index=map_df.index)
    parsed_pz_map = map_df['source_mzml'].apply(lambda x: _precursor_charge_from_run_name(x)).astype(int)
    has_parsed_pz_map = parsed_pz_map > 0
    if has_parsed_pz_map.any():
        map_df.loc[has_parsed_pz_map, 'precursor_charge'] = parsed_pz_map[has_parsed_pz_map].astype('Int64')
    if fragment_ch_col:
        map_df['fragment_charge'] = pd.to_numeric(map_df[fragment_ch_col], errors='coerce').round().astype('Int64')
    else:
        map_df['fragment_charge'] = pd.Series(pd.array([pd.NA] * len(map_df), dtype='Int64'), index=map_df.index)
    if frag_subseq_col:
        map_df['fragment_subsequence'] = (
            map_df[frag_subseq_col].astype(str).str.strip().str.upper()
        )
    else:
        map_df['fragment_subsequence'] = ''
    missing_subseq = map_df['fragment_subsequence'].astype(str).str.strip() == ''
    if missing_subseq.any():
        map_df.loc[missing_subseq, 'fragment_subsequence'] = map_df.loc[missing_subseq].apply(
            lambda r: _fragment_subsequence_from_ion_identity(
                r.get('fragment_fit_key', ''),
                r.get('peptide_sequence', ''),
            ),
            axis=1,
        )
    map_df['fragment_subsequence'] = map_df['fragment_subsequence'].astype(str).str.strip().str.upper()
    if frag_mono_mz_col:
        map_df['fragment_mono_mz'] = pd.to_numeric(map_df[frag_mono_mz_col], errors='coerce')
    else:
        map_df['fragment_mono_mz'] = np.nan
    missing_frag_z = map_df['fragment_charge'].isna()
    if missing_frag_z.any():
        map_df.loc[missing_frag_z, 'fragment_charge'] = map_df.loc[missing_frag_z, 'fragment_fit_key'].apply(
            lambda x: _fragment_charge_from_ion_identity(x)
        )
    map_df['fragment_charge'] = pd.to_numeric(map_df['fragment_charge'], errors='coerce').fillna(0).astype(int)
    _act_txt = map_df['activation_setting'].astype(str).str.strip()
    missing_act = _act_txt.eq('') | _act_txt.str.lower().isin({'nan', 'none', 'null'})
    if missing_act.any():
        def _resolve_activation_setting_from_name_vars(src_name: object) -> str:
            method = str(_resolve_activation_method_from_name_map(src_name, src_name, run_method_map) or '').strip().upper()
            ms = _resolve_activation_setting_ms_from_name_map(src_name, src_name, run_setting_map)
            ms_txt = ''
            if ms is not None:
                try:
                    ms_f = float(ms)
                    ms_txt = f"{int(round(ms_f))}ms" if abs(ms_f - round(ms_f)) < 1e-9 else f"{ms_f:g}ms"
                except Exception:
                    ms_txt = ''
            if method and ms_txt:
                return f'{method}_{ms_txt}'
            if method:
                return method
            if ms_txt:
                return ms_txt
            return str(_infer_fragmentation_setting_from_run_name(os.path.splitext(os.path.basename(str(src_name)))[0]) or '').strip()

        map_df.loc[missing_act, 'activation_setting'] = map_df.loc[missing_act, 'source_mzml'].apply(
            _resolve_activation_setting_from_name_vars
        )
    map_df['activation_setting_norm'] = (
        map_df['activation_setting']
        .astype(str)
        .str.strip()
        .apply(_activation_setting_norm_canonical)
    )
    map_df = map_df.dropna(subset=['scan']).copy()
    map_df['scan'] = map_df['scan'].astype(int)
    map_df = map_df[(map_df['fragment_fit_key'] != '')].copy()
    if map_df.empty:
        return False, 'Selected fragment annotation CSV has no non-empty fragment assignments; cannot enforce filtered-fragment-only fitting.', {}
    _emit(
        28,
        f'Filtered fragment entries available: {len(map_df)} | '
        f'unique frag keys: {map_df["fragment_fit_key"].nunique()} | '
        f'act_norms: {sorted(map_df["activation_setting_norm"].dropna().unique())[:5]} | '
        f'pz: {sorted(map_df["precursor_charge"].dropna().unique())} | '
        f'peps: {sorted(map_df["peptide_sequence"].dropna().unique())[:3]}',
    )
    _map_exact_cols = ['source_mzml', 'scan', 'fragment_fit_key', 'fragment_mono_mz', 'fragment_charge']
    _map_exact_cols = [c for c in _map_exact_cols if c in map_df.columns]
    map_df_exact = map_df[_map_exact_cols].drop_duplicates(
        subset=[c for c in ['source_mzml', 'scan', 'fragment_fit_key'] if c in _map_exact_cols],
    )
    map_df['fragment_fit_key'] = map_df['fragment_fit_key'].astype(str).str.strip()
    map_df_sc = map_df.dropna(subset=['precursor_charge']).copy()
    map_df_sc = map_df_sc[(map_df_sc['fragment_subsequence'].astype(str).str.strip() != '')].copy()
    subseq_precursor_fragment_charge_to_fragments: dict[tuple[str, int, str, str, int], list[str]] = {}
    activation_precursor_peptide_to_fragments: dict[tuple[str, int, str], list[str]] = {}
    allowed_keys_by_activation_precursor_peptide: dict[tuple[str, int, str], set[str]] = {}
    for (act_i, pz_i, pep_i), grp in map_df.groupby(['activation_setting_norm', 'precursor_charge', 'peptide_sequence'], dropna=False):
        act_s = str(act_i).strip().upper()
        pep_s = str(pep_i).strip().upper()
        try:
            pz_int = int(pz_i)
        except Exception:
            continue
        if (not act_s) or (not pep_s) or (pz_int <= 0):
            continue
        frag_list = sorted(set(str(x).strip() for x in grp['fragment_fit_key'].astype(str).tolist() if str(x).strip()))
        if frag_list:
            activation_precursor_peptide_to_fragments[(act_s, pz_int, pep_s)] = frag_list
            allowed_keys_by_activation_precursor_peptide[(act_s, pz_int, pep_s)] = set(frag_list)
    _emit(
        34,
        'Built activation+precursor filtered fragment catalog: '
        f'{len(activation_precursor_peptide_to_fragments)} groups | '
        f'keys: {list(activation_precursor_peptide_to_fragments.keys())[:3]} | '
        f'sample frags: {list(list(activation_precursor_peptide_to_fragments.values())[0])[:5] if activation_precursor_peptide_to_fragments else []}',
    )
    if not map_df_sc.empty:
        for (act_i, pz_i, pep_i, sub_i, fz_i), grp in map_df_sc.groupby(
            ['activation_setting_norm', 'precursor_charge', 'peptide_sequence', 'fragment_subsequence', 'fragment_charge'],
            dropna=False,
        ):
            act_s = str(act_i).strip().upper()
            pep_s = str(pep_i).strip().upper()
            try:
                pz_int = int(pz_i)
            except Exception:
                continue
            try:
                fz_int = int(fz_i)
            except Exception:
                fz_int = 0
            sub_s = str(sub_i).strip().upper()
            if (not act_s) or (not pep_s) or (not sub_s) or (pz_int <= 0):
                continue
            frag_list = sorted(
                set(
                    str(x).strip()
                    for x in grp['fragment_fit_key'].astype(str).tolist()
                    if str(x).strip()
                )
            )
            if frag_list:
                subseq_precursor_fragment_charge_to_fragments[(act_s, pz_int, pep_s, sub_s, max(0, fz_int))] = frag_list
    # Build per-fragment m/z + charge lookup for propagation to non-exact rows.
    _frag_mz_lookup: dict[str, float] = {}
    _frag_charge_lookup: dict[str, int] = {}
    if 'fragment_mono_mz' in map_df.columns:
        for fk_val, grp_mz in map_df.groupby('fragment_fit_key', dropna=False):
            fk_s = str(fk_val).strip()
            if not fk_s:
                continue
            mz_vals = pd.to_numeric(grp_mz['fragment_mono_mz'], errors='coerce').dropna()
            if not mz_vals.empty:
                _frag_mz_lookup[fk_s] = float(mz_vals.median())
            fz_vals = pd.to_numeric(grp_mz.get('fragment_charge', pd.Series(dtype=float)), errors='coerce').dropna()
            fz_vals = fz_vals[fz_vals > 0]
            if not fz_vals.empty:
                _frag_charge_lookup[fk_s] = int(fz_vals.mode().iloc[0])
    fragment_filter_total_rows = int(len(df))
    df = df.merge(map_df_exact, on=['source_mzml', 'scan'], how='left', suffixes=('', '_map'))
    if 'fragment_fit_key_map' in df.columns:
        df['fragment_fit_key'] = df['fragment_fit_key_map'].fillna(df.get('fragment_fit_key', ''))
        df = df.drop(columns=['fragment_fit_key_map'])
    df['fragment_fit_key'] = df.get('fragment_fit_key', '').astype(str).str.strip()
    if 'fragment_mono_mz_map' in df.columns:
        df['fragment_mono_mz'] = pd.to_numeric(df['fragment_mono_mz_map'], errors='coerce').fillna(
            pd.to_numeric(df.get('fragment_mono_mz', np.nan), errors='coerce')
        )
        df = df.drop(columns=['fragment_mono_mz_map'])
    if 'fragment_charge_map' in df.columns:
        df['fragment_charge'] = pd.to_numeric(df['fragment_charge_map'], errors='coerce').fillna(
            pd.to_numeric(df.get('fragment_charge', np.nan), errors='coerce')
        )
        df = df.drop(columns=['fragment_charge_map'])
    df['_activation_setting_norm'] = (
        df.get('_inv_activation_setting_norm', pd.Series('', index=df.index))
        .apply(_activation_setting_norm_canonical)
        .astype(str)
    )
    df['_peptide_norm'] = df['peptide_sequence'].astype(str).str.strip().str.upper()
    df['_frag_subseq'] = df.apply(
        lambda r: _fragment_subsequence_from_ion_identity(
            r.get('fragment_fit_key', ''),
            r.get('peptide_sequence', ''),
        ),
        axis=1,
    ).astype(str).str.strip().str.upper()
    df['_precursor_charge_i'] = pd.to_numeric(df.get('_inv_precursor_charge', df.get('charge', 0)), errors='coerce').fillna(0).astype(int)
    df['_fragment_charge_i'] = df['fragment_fit_key'].apply(lambda x: _fragment_charge_from_ion_identity(x)).astype(int)
    df['_exact_mapped'] = df['fragment_fit_key'].astype(str).str.strip() != ''
    exact_keep_rows = int(df['_exact_mapped'].sum())
    non_exact = df[~df['_exact_mapped']].copy()
    exact_rows = df[df['_exact_mapped']].copy()
    _emit(
        38,
        f'Post-merge: total={len(df)}, exact_mapped={exact_keep_rows}, non_exact={len(non_exact)} | '
        f'exact act_norms: {sorted(exact_rows["_activation_setting_norm"].dropna().unique())[:5] if not exact_rows.empty else []} | '
        f'exact pz: {sorted(exact_rows["_precursor_charge_i"].dropna().unique())[:5] if not exact_rows.empty else []} | '
        f'exact pep: {sorted(exact_rows["_peptide_norm"].dropna().unique())[:3] if not exact_rows.empty else []} | '
        f'exact fk sample: {exact_rows["fragment_fit_key"].dropna().unique()[:5].tolist() if not exact_rows.empty else []}',
    )
    # For exact source+scan matches, keep only fragment keys allowed for this
    # activation setting + precursor charge + peptide sequence contract.
    exact_rows_keep_mask = []
    for _, r in exact_rows.iterrows():
        k = (
            str(r.get('_activation_setting_norm', '')).strip().upper(),
            int(pd.to_numeric(pd.Series([r.get('_precursor_charge_i', 0)]), errors='coerce').fillna(0).iloc[0]),
            str(r.get('_peptide_norm', '')).strip().upper(),
        )
        fk = str(r.get('fragment_fit_key', '')).strip()
        allowed_set = allowed_keys_by_activation_precursor_peptide.get(k, set())
        exact_rows_keep_mask.append(bool(fk and allowed_set and fk in allowed_set))
    if len(exact_rows_keep_mask) == len(exact_rows):
        exact_rows = exact_rows[pd.Series(exact_rows_keep_mask, index=exact_rows.index)].copy()
    _emit(42, f'Exact scan/run filtered rows retained: {len(exact_rows)}')
    source_rows_retained_for_expansion = int(len(exact_rows))
    expanded_rows: list[pd.DataFrame] = []
    propagated_rows = 0
    propagated_rows_subseq = 0
    propagated_rows_peptide = 0
    # Use all condition rows, but only quantify fragment identities present in
    # filtered CSV contracts (activation + precursor + peptide).
    if not non_exact.empty:
        non_exact_fk = non_exact[non_exact['fragment_fit_key'].astype(str).str.strip() != ''].copy()
        if not non_exact_fk.empty:
            keep_idx: list[int] = []
            for ridx, r in non_exact_fk.iterrows():
                k = (
                    str(r.get('_activation_setting_norm', '')).strip().upper(),
                    int(pd.to_numeric(pd.Series([r.get('_precursor_charge_i', 0)]), errors='coerce').fillna(0).iloc[0]),
                    str(r.get('_peptide_norm', '')).strip().upper(),
                )
                fk = str(r.get('fragment_fit_key', '')).strip()
                allowed_set = allowed_keys_by_activation_precursor_peptide.get(k, set())
                if fk and allowed_set and fk in allowed_set:
                    keep_idx.append(ridx)
            if keep_idx:
                kept_fk = non_exact_fk.loc[keep_idx].copy()
                source_rows_retained_for_expansion += int(len(kept_fk))
                propagated_rows += int(len(kept_fk))
                expanded_rows.append(kept_fk)

        non_exact_empty = non_exact[non_exact['fragment_fit_key'].astype(str).str.strip() == ''].copy()
        if (not non_exact_empty.empty) and bool(allow_fragment_propagation):
            grouped_non_exact = list(
                non_exact_empty.groupby(
                    ['_activation_setting_norm', '_precursor_charge_i', '_peptide_norm', '_frag_subseq', '_fragment_charge_i'],
                    dropna=False,
                )
            )
            total_non_exact_groups = max(1, len(grouped_non_exact))
            for gi, ((act_i, pz_i, pep_i, sub_i, fz_i), grp) in enumerate(grouped_non_exact, start=1):
                act_s = str(act_i).strip().upper()
                sub_s = str(sub_i).strip().upper()
                pep_s = str(pep_i).strip().upper()
                pz_int = int(pz_i) if pd.notna(pz_i) else 0
                fz_int = int(fz_i) if pd.notna(fz_i) else 0
                if (not act_s) or (not pep_s) or (pz_int <= 0):
                    continue
                keys_here: list[str] = []
                if sub_s:
                    keys_here = list(
                        subseq_precursor_fragment_charge_to_fragments.get((act_s, pz_int, pep_s, sub_s, max(0, fz_int)), [])
                        or subseq_precursor_fragment_charge_to_fragments.get((act_s, pz_int, pep_s, sub_s, 0), [])
                        or []
                    )
                if not keys_here:
                    keys_here = list(activation_precursor_peptide_to_fragments.get((act_s, pz_int, pep_s), []) or [])
                if not keys_here:
                    continue
                source_rows_retained_for_expansion += int(len(grp))
                _emit(
                    42 + int(46 * (gi / total_non_exact_groups)),
                    f'Propagating filtered fragment keys for {pep_s or "PEPTIDE"} at {act_s or "UNKNOWN"}, Z{pz_int}: {len(keys_here)} key(s)',
                )
                for fk in keys_here:
                    g2 = grp.copy()
                    g2['fragment_fit_key'] = str(fk)
                    if fk in _frag_mz_lookup:
                        g2['fragment_mono_mz'] = _frag_mz_lookup[fk]
                    if fk in _frag_charge_lookup:
                        g2['fragment_charge'] = _frag_charge_lookup[fk]
                    propagated_rows += int(len(g2))
                    if sub_s:
                        propagated_rows_subseq += int(len(g2))
                    else:
                        propagated_rows_peptide += int(len(g2))
                    expanded_rows.append(g2)
        elif (not non_exact_empty.empty) and (not bool(allow_fragment_propagation)):
            _emit(
                70,
                f'Propagation disabled: dropped {len(non_exact_empty)} row(s) without exact/explicit fragment keys.',
            )

    if expanded_rows:
        df = pd.concat([exact_rows] + expanded_rows, ignore_index=True)
    else:
        df = exact_rows.copy()
    df['fragment_fit_key'] = df.get('fragment_fit_key', '').astype(str).str.strip()
    df = df[df['fragment_fit_key'] != ''].copy()
    if '_frag_subseq' in df.columns:
        df = df.drop(columns=['_frag_subseq'])
    if '_peptide_norm' in df.columns:
        df = df.drop(columns=['_peptide_norm'])
    if '_activation_setting_norm' in df.columns:
        df = df.drop(columns=['_activation_setting_norm'])
    if '_precursor_charge_i' in df.columns:
        df = df.drop(columns=['_precursor_charge_i'])
    if '_fragment_charge_i' in df.columns:
        df = df.drop(columns=['_fragment_charge_i'])
    if '_exact_mapped' in df.columns:
        df = df.drop(columns=['_exact_mapped'])
    fragment_filter_kept_rows = int(len(df))
    fragment_filter_applied = True
    source_rows_dropped_before_expansion = max(0, int(fragment_filter_total_rows) - int(source_rows_retained_for_expansion))
    if df.empty:
        return (
            False,
            'Fragment-only fit enforcement kept 0 rows after filtered-fragment mapping/propagation; '
            'the selected merged annotation CSV does not overlap current prep input scope.',
            {},
        )
    _emit(92, f'Filtered prep rows after fragment gating: {len(df)}')

    # Recompute fragment subsequence and max_uptake now that fragment_fit_key
    # has been populated by propagation (in peptide mode the initial keys were empty).
    fit_triplets = df.apply(_fit_subseq_and_uptake, axis=1)
    df['fragment_subsequence_for_fit'] = [str(t[0]) for t in fit_triplets.tolist()]
    df['subsequence_length_for_fit'] = [int(t[1]) for t in fit_triplets.tolist()]
    df['max_uptake_d_for_fit'] = [int(t[2]) for t in fit_triplets.tolist()]

    meta_group_cols = ['source_mzml', 'source_mzml_path', 'label_h_or_d', 'run_type_pyhx', 'peptide_sequence', 'charge']
    if '_inv_replicate_index' in df.columns:
        meta_group_cols.append('_inv_replicate_index')
    if (df['fragment_fit_key'].astype(str).str.strip() != '').any():
        meta_group_cols.append('fragment_fit_key')
    meta = (
        df.groupby(meta_group_cols, dropna=False)
        .agg(
            n_scans=('scan', 'count'),
            scan_min=('scan', 'min'),
            scan_max=('scan', 'max'),
            max_uptake_d_for_fit=('max_uptake_d_for_fit', 'max'),
            subsequence_length_for_fit=('subsequence_length_for_fit', 'max'),
        )
        .reset_index()
        .sort_values(['source_mzml', 'run_type_pyhx', 'charge'])
    )
    # Build pyHXExpress required metadf scaffold:
    # SAMPLE_START-END-PEPTIDE-zCHARGE-usertext.csv/.xlsx
    # We emit fields explicitly so downstream fit scripts can consume directly.
    if not meta.empty:
        meta = meta.copy()
        meta['sample'] = (
            meta['source_mzml']
            .astype(str)
            .apply(lambda s: _sanitize_name_token(os.path.splitext(os.path.basename(str(s)))[0]) or 'sample')
        )
        meta['start_seq'] = 1
        meta['end_seq'] = meta['peptide_sequence'].astype(str).str.len().clip(lower=1).astype(int)
        meta['peptide_range'] = meta.apply(lambda r: f"{int(r['start_seq']):04d}-{int(r['end_seq']):04d}", axis=1)
        meta['peptide'] = meta['peptide_sequence'].astype(str)
        meta['usertext_pyhx'] = meta['run_type_pyhx'].astype(str)
        if '_inv_replicate_index' in meta.columns:
            meta['rep'] = pd.to_numeric(meta['_inv_replicate_index'], errors='coerce').fillna(1).astype(int)
        else:
            meta['rep'] = 1
        meta['file'] = meta.apply(
            lambda r: (
                f"{str(r.get('sample', 'sample'))}_{int(r.get('start_seq', 1)):04d}"
                f"-{int(r.get('end_seq', 1)):04d}"
                f"-{str(r.get('peptide', '')).strip().upper()}"
                f"-z{int(pd.to_numeric(pd.Series([r.get('charge', 0)]), errors='coerce').fillna(0).iloc[0])}"
                f"-{str(r.get('usertext_pyhx', 'undeut'))}.csv"
            ),
            axis=1,
        )
        meta = meta.reset_index(drop=True)
        # pyHXExpress metadf minimum contract requires `Index` (int row ID).
        # Keep `data_id` as a mirrored convenience field for local debugging.
        _idx_vals = np.arange(len(meta), dtype=int)
        meta.insert(0, 'Index', _idx_vals)
        meta.insert(1, 'data_id', _idx_vals)
        desired_order = [
            'Index',
            'data_id',
            'file',
            'sample',
            'start_seq',
            'end_seq',
            'peptide_range',
            'charge',
            'peptide',
            'run_type_pyhx',
            'usertext_pyhx',
            'label_h_or_d',
            'source_mzml',
            'source_mzml_path',
            'rep',
            'fragment_fit_key',
            'n_scans',
            'scan_min',
            'scan_max',
        ]
        meta = meta[[c for c in desired_order if c in meta.columns] + [c for c in meta.columns if c not in desired_order]]
    df.to_csv(prep_csv, index=False)
    meta.to_csv(meta_csv, index=False)
    user_cfg_csv = ''
    ok_cfg, msg_cfg, cfg_path = _write_pyhxexpress_user_config(
        output_dir=out_dir,
        base_name=base,
        data_dir=out_dir,
        data_type=1,
        config_overrides=(pyhx_config_overrides or {}),
        metadf_file=os.path.basename(str(meta_csv)),
    )
    if ok_cfg and cfg_path:
        user_cfg_csv = str(cfg_path)
        _emit(99, f'Generated pyHXExpress user config: {os.path.basename(user_cfg_csv)}')
    else:
        _emit(99, f'pyHXExpress user config was not generated: {msg_cfg}')
    _emit(98, f'Saved prep tables: {os.path.basename(prep_csv)} and {os.path.basename(meta_csv)}')
    msg = f'Prepared pyHXExpress inputs: rows={len(df)}, groups={len(meta)}'
    if fragment_filter_requested and fragment_filter_applied:
        msg += (
            ' | filtered-fragment-only enforced: '
            f'source_rows_retained={source_rows_retained_for_expansion}/{fragment_filter_total_rows}, '
            f'source_rows_dropped={source_rows_dropped_before_expansion}, '
            f'rows_after_fragment_expansion={fragment_filter_kept_rows}'
        )
        msg += (
            f' | fragment propagation: exact_scan_matches={exact_keep_rows}, '
            f'propagated_rows={propagated_rows}, '
            f'subsequence_propagated_rows={propagated_rows_subseq}, '
            f'peptide_level_propagated_rows={propagated_rows_peptide}, '
            f'subsequence_precursor_fragmentcharge_sets={len(subseq_precursor_fragment_charge_to_fragments)}, '
            f'activation_precursor_peptide_sets={len(activation_precursor_peptide_to_fragments)}, '
            f'propagation_enabled={bool(allow_fragment_propagation)}'
        )
    elif fragment_filter_requested and (not fragment_filter_applied):
        msg += ' | fragment annotation CSV selected, but strict enforcement was not applied'
    try:
        max_uptake_preview = int(pd.to_numeric(df.get('max_uptake_d_for_fit'), errors='coerce').fillna(0).max())
        msg += f' | max_uptake_d_for_fit(max)={max_uptake_preview}'
    except Exception:
        pass
    _emit(100, msg)
    return True, msg, {
        'spectra_input_csv': prep_csv,
        'metadf_input_csv': meta_csv,
        'pyhx_user_config_py': user_cfg_csv,
    }


def _find_latest_pyhxexpress_prep_file(
    directory: str, base_name: str, suffix: str, ext: str = '.csv'
) -> str:
    """
    Return most recently modified prep file matching:
      <base_name><suffix><timestamp><ext>
    Searches recursively under `directory`.
    """
    root = str(directory or '').strip()
    if not root or (not os.path.isdir(root)):
        return ''
    base_tok = _sanitize_name_token(base_name or '') or ''
    if not base_tok:
        return ''
    pat = re.compile(
        r'^' + re.escape(base_tok) + re.escape(str(suffix or '')) + r'.*' + re.escape(str(ext or '.csv')) + r'$',
        flags=re.IGNORECASE,
    )
    hits: list[tuple[float, str]] = []
    for cur, _, files in os.walk(root):
        for fn in files:
            if not pat.match(str(fn)):
                continue
            fp = os.path.join(cur, fn)
            try:
                hits.append((float(os.path.getmtime(fp)), fp))
            except Exception:
                continue
    if not hits:
        return ''
    hits.sort(key=lambda x: x[0], reverse=True)
    return str(hits[0][1])


def _build_peptide_prefilter_input_from_fragment_search(
    fragment_matches_csv: str,
    out_dir: str,
    peptide_sequence: str = '',
    allowed_ion_types: list[str] | None = None,
    mz_tol_mode: str = 'ppm',
    mz_tol_ppm: float = 5.0,
    mz_tol_da: float = 0.4,
    include_neutral_losses: bool = True,
    include_radical_variants: bool = True,
    min_matched_intensity: float = 0.0,
) -> tuple[bool, str, str]:
    """
    Build a prefilter-style CSV from Fragment Search merged matches.
    This enables Step 6 Extraction in peptide mode without Comet/OpenMS.
    """
    if not fragment_matches_csv or not os.path.isfile(fragment_matches_csv):
        return False, 'Fragment Search merged matches CSV not found.', ''
    if not out_dir:
        return False, 'Output directory not set.', ''
    try:
        dff = pd.read_csv(fragment_matches_csv)
    except Exception as e:
        return False, f'Could not read Fragment Search CSV: {e}', ''
    if dff is None or dff.empty:
        return False, 'Fragment Search CSV is empty.', ''
    required = ['source_mzml', 'source_mzml_path', 'scan', 'ion_identity', 'observed_mz']
    miss = [c for c in required if c not in dff.columns]
    if miss:
        return False, f'Fragment Search CSV missing required columns: {", ".join(miss)}', ''

    dff = dff.copy()
    dff['scan'] = pd.to_numeric(dff.get('scan'), errors='coerce').astype('Int64')
    dff['observed_mz'] = pd.to_numeric(dff.get('observed_mz'), errors='coerce')
    dff['predicted_mz'] = pd.to_numeric(dff.get('predicted_mz'), errors='coerce')
    dff['intensity'] = pd.to_numeric(dff.get('intensity'), errors='coerce')
    dff['mz_error_ppm'] = pd.to_numeric(dff.get('mz_error_ppm'), errors='coerce')
    dff = dff.dropna(subset=['scan', 'observed_mz']).copy()
    if dff.empty:
        return False, 'No valid rows in Fragment Search CSV after cleanup.', ''
    dff['scan'] = dff['scan'].astype(int)
    dff['source_mzml'] = dff['source_mzml'].astype(str)
    dff['source_mzml_path'] = dff['source_mzml_path'].astype(str)
    dff['ion_identity'] = dff['ion_identity'].astype(str).str.strip()
    dff['ion_type'] = dff.get('ion_type', pd.Series([''] * len(dff), index=dff.index)).astype(str).str.strip().str.lower()
    dff['ion_family'] = dff.get('ion_family', pd.Series([''] * len(dff), index=dff.index)).astype(str).str.strip().str.lower()
    dff.loc[dff['ion_family'] == '', 'ion_family'] = (
        dff.loc[dff['ion_family'] == '', 'ion_type']
        .astype(str)
        .str.extract(r'^([abcxyz])', expand=False)
        .fillna('')
        .str.lower()
    )
    dff.loc[dff['ion_family'] == '', 'ion_family'] = (
        dff.loc[dff['ion_family'] == '', 'ion_identity']
        .astype(str)
        .str.extract(r'^\(?\s*([abcxyz])', expand=False)
        .fillna('')
        .str.lower()
    )

    # Peptide-mode matching filters (relevant to fragment-search data model).
    sel_ions = [str(x).strip().lower() for x in (allowed_ion_types or []) if str(x).strip()]
    if sel_ions and 'ion_family' in dff.columns:
        # Keep detailed variants (e.g., z+1, c-1) by filtering on base family.
        dff = dff[dff['ion_family'].isin(set(sel_ions))].copy()
    mode = str(mz_tol_mode or 'ppm').strip().lower()
    if mode not in {'ppm', 'da'}:
        mode = 'ppm'
    if mode == 'ppm' and 'mz_error_ppm' in dff.columns:
        dff = dff[pd.to_numeric(dff['mz_error_ppm'], errors='coerce').abs() <= float(mz_tol_ppm)].copy()
    elif mode == 'da' and 'mz_error_da' in dff.columns:
        dff = dff[pd.to_numeric(dff['mz_error_da'], errors='coerce').abs() <= float(mz_tol_da)].copy()
    try:
        min_i = float(min_matched_intensity or 0.0)
    except Exception:
        min_i = 0.0
    min_i = max(0.0, float(min_i))
    if min_i > 0.0 and 'intensity' in dff.columns:
        dff = dff[pd.to_numeric(dff['intensity'], errors='coerce').fillna(0.0) >= float(min_i)].copy()
    if not include_neutral_losses and 'ion_identity' in dff.columns:
        dff = dff[
            ~dff['ion_identity'].astype(str).str.contains(
                r'-(H2O|NH3|CO)(?:$|_|[^A-Za-z0-9])',
                regex=True,
                na=False,
                case=False,
            )
        ].copy()
    if not include_radical_variants and 'ion_type' in dff.columns:
        dff = dff[
            ~(
                dff['ion_type'].astype(str).str.lower().isin({'c-1', 'c+1', 'c+2', 'z-1', 'z+1', 'z+2', 'z+3'})
                | dff['ion_identity'].astype(str).str.contains(
                    r'^\(?\s*(?:c|z)[+-]\d+\s*\)?',
                    regex=True,
                    na=False,
                    case=False,
                )
            )
        ].copy()
    if dff.empty:
        return False, 'All fragment-search rows were filtered out by peptide-mode matching filters.', ''

    # Peptide identity source priority for peptide-mode bridge generation:
    # 1) sequence prefix encoded in fragment-search merged CSV name (e.g. HHHHHHIIKIIK_fragment_search_matches...)
    # 2) caller-provided resolved peptide_sequence
    # 3) fallback placeholder
    pep_from_filename = ''
    try:
        base_name = os.path.basename(str(fragment_matches_csv or ''))
        m_pep = re.match(r'^([A-Za-z]+)_fragment_search_matches', base_name, flags=re.IGNORECASE)
        if m_pep:
            pep_from_filename = re.sub(r'[^A-Za-z]', '', str(m_pep.group(1) or '')).strip().upper()
    except Exception:
        pep_from_filename = ''
    pep_from_arg = re.sub(r'[^A-Za-z]', '', str(peptide_sequence or '')).strip().upper()
    pep = pep_from_filename or pep_from_arg or 'PEPTIDE'

    rt_cache: dict[str, dict[int, float]] = {}

    def _get_rt_min(mzml_path: str, scan_no: int) -> float | None:
        path = str(mzml_path or '')
        if path not in rt_cache:
            rt_map: dict[int, float] = {}
            try:
                stem = os.path.splitext(os.path.basename(path))[0]
                inv = os.path.join(os.path.dirname(path), f'{stem}_scan_inventory.csv')
                if os.path.isfile(inv):
                    inv_df = pd.read_csv(inv)
                    scan_col = next((c for c in ['scan_number', 'scan', 'scan_num'] if c in inv_df.columns), None)
                    rt_col = next((c for c in ['retention_time_min', 'retention_time_minutes', 'scan_start_time_min', 'rt_min'] if c in inv_df.columns), None)
                    if not rt_col:
                        rt_sec_col = next((c for c in ['retention_time_sec', 'scan_start_time_sec', 'rt_sec'] if c in inv_df.columns), None)
                        if rt_sec_col:
                            inv_df['_rt_min'] = pd.to_numeric(inv_df[rt_sec_col], errors='coerce') / 60.0
                            rt_col = '_rt_min'
                    if scan_col and rt_col:
                        svals = pd.to_numeric(inv_df[scan_col], errors='coerce')
                        rvals = pd.to_numeric(inv_df[rt_col], errors='coerce')
                        ok = svals.notna() & rvals.notna()
                        for s, r in zip(svals[ok].astype(int).tolist(), rvals[ok].astype(float).tolist()):
                            rt_map[int(s)] = float(r)
            except Exception:
                rt_map = {}
            rt_cache[path] = rt_map
        return rt_cache.get(path, {}).get(int(scan_no))

    out_rows: list[dict[str, object]] = []
    for (src_name, src_path, scan_no), grp in dff.groupby(['source_mzml', 'source_mzml_path', 'scan'], dropna=False):
        src_name_s = str(src_name)
        src_path_s = str(src_path)
        scan_i = int(scan_no)
        m = re.search(r'_Z(\d+)(?=_|\.|$)', src_name_s, flags=re.IGNORECASE)
        precursor_z = int(m.group(1)) if m else 1
        ions: list[str] = []
        mzs: list[float] = []
        pred_mzs: list[float] = []
        intens: list[float] = []
        ppms: list[float] = []
        for _, grow in grp.iterrows():
            ion_s = str(grow.get('ion_identity') or '').strip()
            try:
                obs_v = float(grow.get('observed_mz'))
            except Exception:
                obs_v = np.nan
            if (not ion_s) or (not np.isfinite(obs_v)):
                continue
            ions.append(ion_s)
            mzs.append(float(obs_v))
            try:
                pred_v = float(grow.get('predicted_mz'))
                if np.isfinite(pred_v):
                    pred_mzs.append(float(pred_v))
                else:
                    pred_mzs.append(float(obs_v))
            except Exception:
                pred_mzs.append(float(obs_v))
            try:
                int_v = float(grow.get('intensity'))
                if np.isfinite(int_v):
                    intens.append(float(int_v))
            except Exception:
                pass
            try:
                ppm_v = float(grow.get('mz_error_ppm'))
                if np.isfinite(ppm_v):
                    ppms.append(float(ppm_v))
            except Exception:
                pass
        if not ions or not mzs:
            continue
        theo_vals = pd.Series(pred_mzs, dtype=float)
        theo_mz = float(theo_vals.median()) if not theo_vals.empty else float(np.median(mzs))
        obs_mz = float(np.median(mzs))
        ms1_ppm = float(np.median(ppms)) if ppms else 0.0
        rt_min = _get_rt_min(src_path_s, scan_i)
        out_rows.append(
            {
                'protein_position': f'1-{max(1, len(pep))}',
                'peptide_sequence': pep,
                'plain_peptide': pep,
                'charge': int(max(1, precursor_z)),
                'scan': int(scan_i),
                'source_mzml': src_name_s,
                'source_mzml_path': src_path_s,
                'observed_mz': float(obs_mz),
                'theoretical_mz': float(theo_mz),
                # Fragment Search is MS2-based; keep legacy MS1 alias for compatibility.
                'MS2_mz_error_ppm': float(ms1_ppm),
                'MS1_mz_error_ppm': float(ms1_ppm),
                'MS1_RT_minutes': (float(rt_min) if rt_min is not None else np.nan),
                'qvalue': 0.0,
                'pep': 0.0,
                'sp': (float(np.nanmax(intens)) if intens else np.nan),
                'fragment_matched_frags': ','.join(ions),
                'fragment_matched_frags_mz': ','.join(f'{v:.6f}' for v in mzs),
                'fragment_matched_frags_predicted_mz': ','.join(f'{v:.6f}' for v in pred_mzs),
                'fragment_matched_frags_intensities': ','.join(f'{v:.2f}' for v in intens) if intens else '',
                'fragment_matched_frags_quality_scores': ','.join('1.0' for _ in ions),
            }
        )
    if not out_rows:
        return False, 'No prefilter-style rows could be built from Fragment Search CSV.', ''
    out_df = pd.DataFrame(out_rows)
    ts = _timestamp_token()
    base_raw = _sanitize_name_token(os.path.splitext(os.path.basename(fragment_matches_csv))[0]) or 'fragment_search'
    # Keep bridge filenames compact/readable:
    # - drop trailing source timestamp token from fragment-search merged inputs
    # - avoid embedding duplicate mode/timestamp segments in output names
    base_compact = re.sub(r'__\d{8}_(?:\d{6}|\d{4}_(?:AM|PM))$', '', str(base_raw), flags=re.IGNORECASE)
    base_compact = re.sub(
        r'_peptide_mode_prefilter__\d{8}(?:_(?:\d{6}|\d{4}_(?:AM|PM)))?$',
        '',
        str(base_compact),
        flags=re.IGNORECASE,
    )
    base_final = str(base_compact).strip('_') or str(base_raw)
    # Canonical: <input_stem>__<tab>_<timestamp>.csv
    out_csv = os.path.join(out_dir, _dedup_same_day_dates_in_name(f'{base_final}__prefilter_{ts}.csv'))
    out_df.to_csv(out_csv, index=False)
    return True, f'Built peptide-mode prefilter input: rows={len(out_df)}', out_csv


def _export_hxexpress_like_tabular_from_prep(
    spectra_input_csv: str,
    out_dir: str,
    output_base: str,
    split_by_fragmentation_setting: bool = True,
    group_by_source_mzml: bool = False,
    mirror_tree_mode: bool = False,
    mirror_tree_root: str = '',
    progress_cb=None,
) -> tuple[bool, str, dict[str, str]]:
    """
    Export strict HX-Express-style tabular spectra input from prepared scan references.

    Generates one strict direct-input file set per dataset (peptide + charge + fragmentation_setting),
    with adjacent [m/z, Intensity] column pairs and HX-Express-style headers produced by
    pyHXExpress `export_to_hxexpress(...)`.
    """
    if pyhx_hxex is None or not hasattr(pyhx_hxex, 'export_to_hxexpress'):
        return False, 'pyHXExpress export_to_hxexpress is not available in this environment.', {}

    def _emit(pct: int, msg: str) -> None:
        if progress_cb is None:
            return
        try:
            progress_cb(max(0, min(100, int(pct))), str(msg))
        except Exception:
            pass

    def _safe_export_to_hxexpress(rawdata: pd.DataFrame, remove_untd_reps: bool = False) -> pd.DataFrame:
        """
        Compatible fallback for pyHXExpress export_to_hxexpress().
        Handles library edge-case where list.remove('unused') is called even when absent.
        """
        if rawdata is None or rawdata.empty:
            return pd.DataFrame()
        full_deut_time_local = float(getattr(pyhx_hxex.config, 'FullDeut_Time', 1e6) or 1e6)
        if (not np.isfinite(full_deut_time_local)) or (float(full_deut_time_local) <= 0.0):
            full_deut_time_local = 1e6

        def _time_col(row: pd.Series) -> str:
            t = float(pd.to_numeric(row.get('time'), errors='coerce') if row.get('time') is not None else 0.0)
            rep_v = int(pd.to_numeric(row.get('rep'), errors='coerce') if row.get('rep') is not None else 1)
            if t == 0.0:
                if remove_untd_reps:
                    if rep_v == 1:
                        return '0.0_undeut'
                    return 'unused'
                x = f'undeut{int(rep_v)}'
                order = '0.0'
            elif t == full_deut_time_local:
                if remove_untd_reps:
                    if rep_v == 1:
                        return '1.0_TD'
                    return 'unused'
                x = f'TD{int(rep_v)}'
                order = '1.0'
            else:
                t_idx = int(pd.to_numeric(row.get('time_idx'), errors='coerce') if row.get('time_idx') is not None else 0)
                x = f'{float(t) + (float(rep_v) - 1.0) / 100.0:0.2f} sec'
                order = t_idx + 1
            return f"{order}.{int(rep_v)}_{x}"

        tmp = rawdata.copy()
        tmp['time_col'] = tmp.apply(_time_col, axis=1)
        tmp = tmp[tmp['time_col'] != 'unused'].copy()
        if tmp.empty:
            return pd.DataFrame()

        def _tc_sort_key(tc: str) -> tuple:
            s = str(tc or '')
            left = s.split('_', 1)[0]
            parts = [p for p in left.split('.') if p != '']
            nums: list[float] = []
            for p in parts:
                try:
                    nums.append(float(p))
                except Exception:
                    nums.append(0.0)
            if not nums:
                nums = [9999.0]
            return tuple(nums)

        unique_tcs = [str(x) for x in tmp['time_col'].dropna().astype(str).unique().tolist()]
        unique_tcs = sorted(unique_tcs, key=_tc_sort_key)
        if not unique_tcs:
            return pd.DataFrame()

        hxcols = pd.DataFrame()
        for i, key in enumerate(unique_tcs):
            v = str(key).split('_', 1)[1] if '_' in str(key) else str(key)
            sel = tmp[tmp['time_col'] == str(key)]
            hxcol = pd.DataFrame()
            hxcol[v] = pd.to_numeric(sel.get('mz'), errors='coerce').values
            hxcol[' ' * i] = pd.to_numeric(sel.get('Intensity'), errors='coerce').values
            hxcols = pd.concat([hxcols, hxcol], axis=1, ignore_index=False)
        return hxcols
    if not spectra_input_csv or not os.path.isfile(spectra_input_csv):
        return False, 'Prepared spectra input CSV is missing.', {}
    if not out_dir:
        return False, 'Output directory not set.', {}
    os.makedirs(out_dir, exist_ok=True)
    _emit(2, f'Loading prepared spectra CSV: {spectra_input_csv}')

    try:
        sdf = pd.read_csv(spectra_input_csv)
    except Exception as e:
        return False, f'Could not read prepared spectra CSV: {e}', {}
    _emit(8, f'Loaded rows: {len(sdf)}')

    req = ['peptide_sequence', 'charge', 'scan', 'source_mzml', 'source_mzml_path', 'label_h_or_d']
    miss = [c for c in req if c not in sdf.columns]
    if miss:
        return False, f'Prepared spectra CSV missing required columns: {", ".join(miss)}', {}
    _emit(12, f'Required columns present: {", ".join(req)}')
    if sdf.empty:
        return False, 'Prepared spectra CSV is empty.', {}

    sdf = sdf.copy()
    sdf['charge'] = pd.to_numeric(sdf['charge'], errors='coerce').round().astype('Int64')
    sdf['scan'] = pd.to_numeric(sdf['scan'], errors='coerce').round().astype('Int64')
    sdf['source_mzml'] = sdf['source_mzml'].astype(str)
    sdf['source_mzml_path'] = sdf['source_mzml_path'].astype(str)
    sdf['label_h_or_d'] = sdf['label_h_or_d'].astype(str).str.upper()
    sdf = sdf[
        (sdf['charge'].notna())
        & (sdf['scan'].notna())
        & (sdf['scan'] > 0)
        & (sdf['source_mzml_path'] != '')
    ].copy()
    _emit(18, f'Rows after base cleanup: {len(sdf)}')
    if sdf.empty:
        return False, 'No valid rows left in prepared spectra CSV after cleanup.', {}
    label_counts = sdf['label_h_or_d'].value_counts(dropna=False).to_dict()
    _emit(21, f'Label distribution: {label_counts}')

    scans_by_file: dict[str, set[int]] = {}
    missing_file_rows = 0
    for mzml_path, grp in sdf.groupby('source_mzml_path', dropna=False):
        p = str(mzml_path or '').strip()
        if not p or not os.path.isfile(p):
            missing_file_rows += int(len(grp))
            continue
        scan_set = set(int(x) for x in pd.to_numeric(grp['scan'], errors='coerce').dropna().astype(int).tolist() if int(x) > 0)
        if scan_set:
            scans_by_file[p] = scan_set
    _emit(26, f'mzML path check: files={len(scans_by_file)}, rows_with_missing_paths={missing_file_rows}')
    if not scans_by_file:
        return False, 'No valid mzML files/scans found while exporting HX-Express-like table.', {}

    raw_lookup: dict[str, dict[int, pd.DataFrame]] = {}
    total_files = max(1, len(scans_by_file))
    for i, (p, scan_set) in enumerate(scans_by_file.items(), start=1):
        raw_map, _ = _extract_ms2_scan_arrays_from_mzml(p, scan_set)
        raw_lookup[p] = raw_map
        _emit(26 + int(18 * (i / total_files)), f'Extracting MS2 arrays {i}/{total_files}: {os.path.basename(p)} (matched_scans={len(raw_map)})')

    working_dir_guess = os.path.abspath(os.path.dirname(out_dir)) if out_dir else ''
    name_map_run_ids = _load_name_mapping_run_ids(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else set()
    full_deut_time = float(getattr(pyhx_hxex.config, 'FullDeut_Time', 1e6) or 1e6)
    if (not np.isfinite(full_deut_time)) or (float(full_deut_time) <= 0.0):
        full_deut_time = 1e6
    sample_name = _sanitize_name_token(_sanitize_name_token(output_base or 'sample')) or 'sample'
    run_method_map = _load_name_mapping_activation_method_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    run_setting_map = _load_name_mapping_activation_setting_ms_by_run(working_dir_guess) if working_dir_guess and os.path.isdir(working_dir_guess) else {}
    # dataset_key -> list[spectrum_df with mz/Intensity plus metadata fields]
    dataset_specs: dict[tuple[str, int, str], list[pd.DataFrame]] = {}
    settings_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    labels_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    source_mzml_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    source_mzml_path_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    fragment_keys_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    fragment_subseq_by_dataset: dict[tuple[str, int, str], set[str]] = {}
    fragment_charge_by_dataset: dict[tuple[str, int, str], set[int]] = {}
    fragment_subclass_by_dataset: dict[tuple[str, int, str], set[str]] = {}

    def _fragment_subclass_token(frag_key: str) -> str:
        s = str(frag_key or '').strip()
        if not s:
            return 'unknown'
        if re.search(r'-(H2O|NH3|CO)(?:$|_|[^A-Za-z0-9])', s, flags=re.IGNORECASE):
            return 'neutral_loss'
        if re.match(r'^\s*\(([cz][+-]\d+)\)', s, flags=re.IGNORECASE):
            return 'radical'
        if re.search(r'_(z\+\d+)$', s, flags=re.IGNORECASE):
            return 'radical'
        return 'normal'

    def _compact_set_token(values: set[str], prefix: str, limit: int = 6) -> str:
        vals = sorted(set(str(v).strip() for v in (values or set()) if str(v).strip()))
        if not vals:
            return f'{prefix}none'
        toks = [_sanitize_name_token(v).lower() for v in vals[:limit]]
        if len(vals) > limit:
            toks.append(f'plus{len(vals) - limit}')
        return f'{prefix}' + '-'.join([t for t in toks if t]) if toks else f'{prefix}none'

    def _compact_int_set_token(values: set[int], prefix: str) -> str:
        vals = sorted(set(int(v) for v in (values or set()) if int(v) > 0))
        if not vals:
            return f'{prefix}none'
        return f"{prefix}" + "-".join([str(v) for v in vals])
    grouped = sdf.groupby(['peptide_sequence', 'charge', 'source_mzml', 'source_mzml_path', 'label_h_or_d'], dropna=False)
    grouped_list = list(grouped)
    _emit(46, f'Preparing grouped spectra series: groups={len(grouped_list)}')
    total_groups = max(1, len(grouped_list))
    for gi, ((pep, z_raw, src_name, src_path, lbl), grp) in enumerate(grouped_list, start=1):
        if pd.isna(z_raw):
            continue
        z = int(z_raw)
        if z <= 0:
            continue
        pep = str(pep or '').strip().upper()
        if not pep:
            continue
        wanted_scans = [int(x) for x in pd.to_numeric(grp['scan'], errors='coerce').dropna().astype(int).tolist() if int(x) > 0]
        if not wanted_scans:
            continue
        spec_map = raw_lookup.get(str(src_path), {})
        raw_dfs = [spec_map.get(sn) for sn in wanted_scans if sn in spec_map]
        raw_dfs = [x for x in raw_dfs if x is not None and not x.empty]
        if not raw_dfs:
            continue

        binned: dict[float, float] = {}
        for rdf in raw_dfs:
            for mz_val, int_val in zip(rdf['mz'].astype(float).values, rdf['Intensity'].astype(float).values):
                if not np.isfinite(mz_val) or not np.isfinite(int_val):
                    continue
                k = round(float(mz_val), 4)
                binned[k] = binned.get(k, 0.0) + max(0.0, float(int_val))
        if not binned:
            continue
        xs = sorted(binned.keys())
        ys = [binned[k] / max(1, len(raw_dfs)) for k in xs]
        spec_df = pd.DataFrame({'mz': xs, 'intensity': ys})
        spec_df = spec_df[(spec_df['mz'] > 0) & (spec_df['intensity'] > 0)].reset_index(drop=True)
        if spec_df.empty:
            continue

        run_stem = os.path.splitext(os.path.basename(str(src_name)))[0]
        method_nm = str(_resolve_activation_method_from_name_map(src_name, src_path, run_method_map) or '').strip().upper()
        setting_ms_nm = _resolve_activation_setting_ms_from_name_map(src_name, src_path, run_setting_map)
        setting_txt_nm = ''
        if setting_ms_nm is not None:
            try:
                ms_f = float(setting_ms_nm)
                setting_txt_nm = f"{int(round(ms_f))}ms" if abs(ms_f - round(ms_f)) < 1e-9 else f"{ms_f:g}ms"
            except Exception:
                setting_txt_nm = ''
        if method_nm and setting_txt_nm:
            frag_setting = f'{method_nm}_{setting_txt_nm}'
        elif method_nm:
            frag_setting = method_nm
        elif setting_txt_nm:
            frag_setting = setting_txt_nm
        elif run_stem in name_map_run_ids:
            frag_setting = _infer_fragmentation_setting_from_run_name(run_stem) or 'UNKNOWN'
        else:
            frag_setting = _infer_fragmentation_setting_from_inventory(str(src_path)) or 'UNKNOWN'
        rep_guess = _infer_rep_from_run_name(run_stem)
        lbl_u = str(lbl or '').upper()
        tval = full_deut_time if lbl_u == 'D' else 0.0

        spec_df = spec_df.rename(columns={'intensity': 'Intensity'}).copy()
        spec_df['time'] = float(tval)
        spec_df['rep'] = int(rep_guess)
        spec_df['sample'] = sample_name
        spec_df['peptide'] = pep
        spec_df['charge'] = float(z)
        spec_df['start_seq'] = 1
        spec_df['end_seq'] = int(max(1, len(pep)))
        spec_df['peptide_range'] = f'{1:04d}-{int(max(1, len(pep))):04d}'
        spec_df['file'] = str(src_name)
        run_id_key = str(src_name)
        if group_by_source_mzml:
            ds_key = (pep, int(z), run_id_key)
        elif split_by_fragmentation_setting:
            ds_key = (pep, int(z), str(frag_setting))
        else:
            ds_key = (pep, int(z), 'ALL_SETTINGS')
        dataset_specs.setdefault(ds_key, []).append(spec_df)
        settings_by_dataset.setdefault(ds_key, set()).add(str(frag_setting))
        labels_by_dataset.setdefault(ds_key, set()).add(str(lbl_u if lbl_u in {'H', 'D', 'UN'} else 'UN'))
        source_mzml_by_dataset.setdefault(ds_key, set()).add(str(src_name))
        source_mzml_path_by_dataset.setdefault(ds_key, set()).add(str(src_path))
        fk_vals = sorted(
            set(
                str(v).strip()
                for v in grp.get('fragment_fit_key', pd.Series('', index=grp.index)).astype(str).tolist()
                if str(v).strip()
            )
        )
        if fk_vals:
            fragment_keys_by_dataset.setdefault(ds_key, set()).update(fk_vals)
            fragment_subclass_by_dataset.setdefault(ds_key, set()).update([_fragment_subclass_token(fk) for fk in fk_vals])
            fragment_charge_by_dataset.setdefault(ds_key, set()).update(
                [int(_fragment_charge_from_ion_identity(fk)) for fk in fk_vals if int(_fragment_charge_from_ion_identity(fk)) > 0]
            )
            subseqs = [
                _fragment_subsequence_from_ion_identity(fk, pep)
                for fk in fk_vals
            ]
            subseqs = [str(ss).strip().upper() for ss in subseqs if str(ss).strip()]
            if subseqs:
                fragment_subseq_by_dataset.setdefault(ds_key, set()).update(subseqs)
        if gi == 1 or gi % 10 == 0 or gi == total_groups:
            _emit(46 + int(18 * (gi / total_groups)), f'Grouped {gi}/{total_groups}: {pep} z{z} -> {frag_setting}')

    if not dataset_specs:
        return False, 'Could not build any spectra series for HX-Express export.', {}
    _emit(66, f'Datasets ready for export: {len(dataset_specs)}')

    ts = _timestamp_token()
    base = _sanitize_name_token(output_base or 'pyhx_input') or 'pyhx_input'
    exported_rows: list[dict[str, object]] = []
    first_out_csv = ''
    ds_items = sorted(dataset_specs.keys(), key=lambda x: (x[0], x[1], x[2]))
    total_ds = max(1, len(ds_items))
    for di, (pep, z, frag_setting) in enumerate(ds_items, start=1):
        raw_df = pd.concat(dataset_specs[(pep, z, frag_setting)], ignore_index=True)
        if raw_df.empty:
            _emit(66 + int(26 * (di / total_ds)), f'Skipping empty dataset {di}/{total_ds}: {pep} z{z} {frag_setting}')
            continue
        raw_df['time'] = pd.to_numeric(raw_df['time'], errors='coerce').fillna(0.0).astype(float)
        raw_df['rep'] = pd.to_numeric(raw_df['rep'], errors='coerce').fillna(1).astype(int)
        raw_df['mz'] = pd.to_numeric(raw_df['mz'], errors='coerce')
        raw_df['Intensity'] = pd.to_numeric(raw_df['Intensity'], errors='coerce')
        raw_df = raw_df.replace([np.inf, -np.inf], np.nan).dropna(subset=['mz', 'Intensity'])
        raw_df = raw_df[(raw_df['mz'] > 0) & (raw_df['Intensity'] >= 0)].copy()
        if raw_df.empty:
            _emit(66 + int(26 * (di / total_ds)), f'Skipping dataset after cleanup {di}/{total_ds}: {pep} z{z} {frag_setting}')
            continue
        raw_df['time_idx'] = 0
        tvals = sorted(set(float(x) for x in raw_df['time'].dropna().tolist()))
        tmap = {tv: i for i, tv in enumerate(tvals)}
        raw_df['time_idx'] = [int(tmap.get(float(tv), 0)) for tv in raw_df['time'].tolist()]
        try:
            hxcols = pyhx_hxex.export_to_hxexpress(raw_df, pd.DataFrame(), save_xls=False, removeUNTDreps=False)
        except ValueError as e:
            if 'list.remove(x): x not in list' in str(e):
                hxcols = _safe_export_to_hxexpress(raw_df, remove_untd_reps=False)
            else:
                raise
        if hxcols is None or hxcols.empty:
            _emit(66 + int(26 * (di / total_ds)), f'export_to_hxexpress returned empty for {pep} z{z} {frag_setting}')
            continue
        labels_tok = _compact_set_token(labels_by_dataset.get((pep, z, frag_setting), set()), 'lbl_')
        frag_count_tok = f"frags_{len(fragment_keys_by_dataset.get((pep, z, frag_setting), set()) or set())}"
        settings_included_for_name = sorted(settings_by_dataset.get((pep, z, frag_setting), set()))
        act_for_name = (
            str(settings_included_for_name[0])
            if len(settings_included_for_name) == 1
            else (str(settings_included_for_name[0]) if settings_included_for_name else str(frag_setting))
        )
        source_names_for_name = sorted(source_mzml_by_dataset.get((pep, z, frag_setting), set()))
        source_name0 = str(source_names_for_name[0]) if source_names_for_name else ''
        source_tok = _sanitize_name_token(os.path.splitext(os.path.basename(source_name0))[0]) if source_name0 else ''
        source_tok_short = (source_tok[:40] if source_tok else '')
        source_sig = hashlib.sha1('|'.join(source_names_for_name).encode('utf-8')).hexdigest()[:10] if source_names_for_name else ''
        ds_tok_raw = (
            f"peptide_sequence_{pep}"
            f"_precursor_charge_{int(z)}"
            f"_activation_setting_from_name_{act_for_name}"
            + (f"_source_mzml_{source_tok_short}" if source_tok_short else '')
            + (f"_source_sig_{source_sig}" if source_sig else '')
            + f"_{labels_tok}_{frag_count_tok}"
        )
        ds_tok = _sanitize_name_token(ds_tok_raw) or f'{_sanitize_name_token(pep) or "pep"}_pz{int(z)}'
        # Keep path-safe filename length while still encoding all variables via a stable signature hash.
        if len(ds_tok) > 160:
            sig_payload = {
                'peptide': str(pep),
                'precursor_charge': int(z),
                'activation_setting_from_name': str(act_for_name),
                'labels': sorted(labels_by_dataset.get((pep, z, frag_setting), set())),
                'fragment_keys': sorted(fragment_keys_by_dataset.get((pep, z, frag_setting), set())),
                'source_mzml': source_names_for_name,
            }
            sig_hash = hashlib.sha1(json.dumps(sig_payload, sort_keys=True).encode('utf-8')).hexdigest()[:12]
            ds_tok = _sanitize_name_token(
                f"peptide_sequence_{pep}_precursor_charge_{int(z)}_activation_setting_from_name_{act_for_name}_{labels_tok}_{frag_count_tok}_sig_{sig_hash}"
            ) or f'{_sanitize_name_token(pep) or "pep"}_pz{int(z)}_sig_{sig_hash}'
        dataset_out_dir = out_dir
        if mirror_tree_mode:
            src_paths = sorted(source_mzml_path_by_dataset.get((pep, z, frag_setting), set()))
            src_path0 = str(src_paths[0]) if src_paths else ''
            src_parent = os.path.dirname(src_path0) if src_path0 else ''
            root_abs = os.path.abspath(str(mirror_tree_root or '').strip()) if mirror_tree_root else ''
            if root_abs and src_parent:
                try:
                    rel = os.path.relpath(src_parent, root_abs)
                    if not rel.startswith('..'):
                        dataset_out_dir = os.path.join(out_dir, rel)
                    else:
                        dataset_out_dir = os.path.join(out_dir, _sanitize_name_token(os.path.basename(src_parent) or 'root'))
                except Exception:
                    dataset_out_dir = os.path.join(out_dir, _sanitize_name_token(os.path.basename(src_parent) or 'root'))
            elif src_parent:
                dataset_out_dir = os.path.join(out_dir, _sanitize_name_token(os.path.basename(src_parent) or 'root'))
        os.makedirs(dataset_out_dir, exist_ok=True)
        base_file_name = _dedup_same_day_dates_in_name(f'{base}_{ds_tok}_hxexpress_input__{ts}')
        out_csv_try = os.path.join(dataset_out_dir, f'{base_file_name}.csv')
        # Final guard for OS path/filename limits.
        if len(out_csv_try) > 235:
            short_sig_payload = {
                'base': base,
                'peptide_sequence': pep,
                'precursor_charge': int(z),
                'activation_setting_from_name': str(act_for_name),
                'source_mzml': source_names_for_name,
                'labels': sorted(labels_by_dataset.get((pep, z, frag_setting), set())),
                'fragment_subclasses': sorted(fragment_subclass_by_dataset.get((pep, z, frag_setting), set())),
                'fragment_charges': sorted(fragment_charge_by_dataset.get((pep, z, frag_setting), set())),
                'fragment_key_count': int(len(fragment_keys_by_dataset.get((pep, z, frag_setting), set()) or set())),
            }
            short_sig = hashlib.sha1(json.dumps(short_sig_payload, sort_keys=True).encode('utf-8')).hexdigest()[:12]
            ds_tok = _sanitize_name_token(
                f"peptide_sequence_{pep}_precursor_charge_{int(z)}_activation_setting_from_name_{act_for_name}_{frag_count_tok}_sig_{short_sig}"
            ) or f'{_sanitize_name_token(pep) or "pep"}_pz{int(z)}_sig_{short_sig}'
            base_file_name = _dedup_same_day_dates_in_name(f'{base}_{ds_tok}_hxexpress_input__{ts}')
        out_csv = os.path.join(dataset_out_dir, _dedup_same_day_dates_in_name(f'{base}_{ds_tok}_hxexpress_input__{ts}.csv'))
        hxcols.to_csv(out_csv, index=False)
        try:
            out_xlsx = os.path.join(dataset_out_dir, f'{base}_{ds_tok}_hxexpress_input__{ts}.xlsx')
            hxcols.to_excel(out_xlsx, index=False)
        except Exception:
            out_xlsx = ''

        if not first_out_csv:
            first_out_csv = out_csv
        exported_rows.append(
            {
                'peptide_sequence': pep,
                'precursor_charge': int(z),
                'activation_setting_from_name': act_for_name,
                'charge': int(z),
                'fragmentation_setting': frag_setting,
                'settings_included': ','.join(sorted(settings_by_dataset.get((pep, z, frag_setting), set()))),
                'labels_present': ','.join(sorted(labels_by_dataset.get((pep, z, frag_setting), set()))),
                'source_mzml': ','.join(sorted(source_mzml_by_dataset.get((pep, z, frag_setting), set()))),
                'source_mzml_path': ','.join(sorted(source_mzml_path_by_dataset.get((pep, z, frag_setting), set()))),
                'fragment_subclasses': ','.join(sorted(fragment_subclass_by_dataset.get((pep, z, frag_setting), set()))),
                'fragment_charges': ','.join([str(v) for v in sorted(fragment_charge_by_dataset.get((pep, z, frag_setting), set()))]),
                'fragment_subsequences': ','.join(sorted(fragment_subseq_by_dataset.get((pep, z, frag_setting), set()))),
                'fragment_key_count': int(len(fragment_keys_by_dataset.get((pep, z, frag_setting), set()))),
                'fragment_keys': '|'.join(sorted(fragment_keys_by_dataset.get((pep, z, frag_setting), set()))),
                'output_directory': dataset_out_dir,
                'hxexpress_input_csv': out_csv,
                'hxexpress_input_xlsx': out_xlsx,
                'n_rows': int(len(hxcols)),
                'n_columns': int(len(hxcols.columns)),
            }
        )
        _emit(66 + int(26 * (di / total_ds)), f'Exported dataset {di}/{total_ds}: {pep} z{z} {frag_setting} (rows={len(hxcols)}, cols={len(hxcols.columns)})')

    if not exported_rows:
        dataset_count = len(dataset_specs)
        return False, (
            'No HX-Express input files were exported (all datasets were empty after cleanup). '
            f'Datasets considered: {dataset_count}.'
        ), {}

    manifest_csv = os.path.join(out_dir, _dedup_same_day_dates_in_name(f'{base}_hxexpress_input_manifest__{ts}.csv'))
    pd.DataFrame(exported_rows).to_csv(manifest_csv, index=False)
    _emit(100, f'Export completed: datasets={len(exported_rows)}, manifest={manifest_csv}')
    return True, f'Exported strict HX-Express input files: datasets={len(exported_rows)}', {'hxexpress_like_csv': first_out_csv, 'hxexpress_manifest_csv': manifest_csv}


def _generate_hdx_fits_diagnostic_plots(
    spectra_input_csv: str,
    report_csv: str,
    out_dir: str,
) -> tuple[bool, str, list[str]]:
    """Generate HDX Fits diagnostic plots from prepared pyHX input/report CSVs."""
    if not spectra_input_csv or not os.path.isfile(spectra_input_csv):
        return False, 'HDX spectra input CSV not found for diagnostics.', []
    try:
        df = pd.read_csv(spectra_input_csv)
    except Exception as e:
        return False, f'Could not read HDX spectra input CSV: {e}', []
    if df is None or df.empty:
        return False, 'HDX spectra input CSV is empty.', []

    diag_dir = os.path.join(out_dir, 'diagnostics')
    os.makedirs(diag_dir, exist_ok=True)
    plot_paths: list[str] = []

    # Normalize core columns.
    if 'source_mzml' not in df.columns and 'source_mzml_path' in df.columns:
        df['source_mzml'] = df['source_mzml_path'].astype(str).apply(lambda p: os.path.basename(str(p)))
    df['source_mzml'] = df.get('source_mzml', pd.Series(['unknown'] * len(df))).astype(str)
    df['label_h_or_d'] = df.get('label_h_or_d', pd.Series(['UN'] * len(df))).astype(str).str.upper()
    df['charge'] = pd.to_numeric(df.get('charge', pd.Series(np.nan, index=df.index)), errors='coerce')
    df['scan'] = pd.to_numeric(df.get('scan', pd.Series(np.nan, index=df.index)), errors='coerce')

    # 1) Run x charge heatmap.
    hmap_df = df.dropna(subset=['charge']).copy()
    if not hmap_df.empty:
        hmap_df['charge_i'] = hmap_df['charge'].round().astype(int)
        piv = (
            hmap_df.groupby(['source_mzml', 'charge_i'], dropna=False)['scan']
            .count()
            .unstack(fill_value=0)
            .sort_index()
        )
        if not piv.empty:
            fig, ax = plt.subplots(figsize=(12, max(4, 0.28 * len(piv.index) + 2)))
            vals = piv.values.astype(float)
            masked_vals = np.ma.masked_where(vals <= 0, vals)
            cmap = plt.cm.viridis.copy()
            cmap.set_bad('white')
            im = ax.imshow(masked_vals, aspect='auto', cmap=cmap)
            ax.set_title('HDX input scan coverage: run vs charge')
            ax.set_xlabel('charge')
            ax.set_ylabel('source_mzml')
            ax.set_xticks(np.arange(len(piv.columns)))
            ax.set_xticklabels([str(c) for c in piv.columns])
            ax.set_yticks(np.arange(len(piv.index)))
            ax.set_yticklabels([str(r) for r in piv.index], fontsize=7)
            fig.colorbar(im, ax=ax, label='scan rows')
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fits_run_charge_heatmap.png')
            fig.savefig(p, dpi=180)
            plt.close(fig)
            plot_paths.append(p)

    # 2) Label composition by charge (stacked bars).
    comp_df = df.dropna(subset=['charge']).copy()
    if not comp_df.empty:
        comp_df['charge_i'] = comp_df['charge'].round().astype(int)
        comp = (
            comp_df.groupby(['charge_i', 'label_h_or_d'], dropna=False)['scan']
            .count()
            .unstack(fill_value=0)
            .sort_index()
        )
        if not comp.empty:
            fig, ax = plt.subplots(figsize=(10, 5))
            bottoms = np.zeros(len(comp.index), dtype=float)
            colors = {'H': '#62c1e5', 'D': '#ef4444', 'UN': '#2563eb'}
            for lbl in comp.columns:
                vals = pd.to_numeric(comp[lbl], errors='coerce').fillna(0).values.astype(float)
                ax.bar(
                    np.arange(len(comp.index)),
                    vals,
                    bottom=bottoms,
                    color=colors.get(str(lbl), '#6b7280'),
                    label=str(lbl),
                )
                bottoms += vals
            ax.set_xticks(np.arange(len(comp.index)))
            ax.set_xticklabels([f'z{int(c)}' for c in comp.index])
            ax.set_xlabel('charge')
            ax.set_ylabel('scan rows')
            ax.set_title('HDX input composition by label and charge')
            ax.legend(title='label_h_or_d', fontsize=8)
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fits_label_charge_stacked.png')
            fig.savefig(p, dpi=180)
            plt.close(fig)
            plot_paths.append(p)

    # 3) Scan distribution by label (boxplot).
    box_df = df.dropna(subset=['scan']).copy()
    if not box_df.empty:
        labels = sorted([str(x) for x in box_df['label_h_or_d'].dropna().unique().tolist()])
        groups = [pd.to_numeric(box_df[box_df['label_h_or_d'] == lbl]['scan'], errors='coerce').dropna().values for lbl in labels]
        groups = [g for g in groups if len(g) > 0]
        labels = [lbl for lbl in labels if len(pd.to_numeric(box_df[box_df['label_h_or_d'] == lbl]['scan'], errors='coerce').dropna()) > 0]
        if groups and labels:
            fig, ax = plt.subplots(figsize=(9, 5))
            ax.boxplot(groups, labels=labels, showfliers=False)
            ax.set_title('HDX input scan index distribution by label')
            ax.set_xlabel('label_h_or_d')
            ax.set_ylabel('scan number')
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fits_scan_distribution_by_label.png')
            fig.savefig(p, dpi=180)
            plt.close(fig)
            plot_paths.append(p)

    # 4) Readiness mapping status from report.
    if report_csv and os.path.isfile(report_csv):
        try:
            rdf = pd.read_csv(report_csv)
        except Exception:
            rdf = pd.DataFrame()
        if rdf is not None and not rdf.empty and 'pyhx_required_field' in rdf.columns and 'status' in rdf.columns:
            tmp = rdf[['pyhx_required_field', 'status']].copy()
            tmp['status'] = tmp['status'].astype(str).str.lower()
            tmp['ready'] = tmp['status'].eq('ready').astype(int)
            stat = (
                tmp.groupby('pyhx_required_field', dropna=False)['ready']
                .mean()
                .reset_index()
                .sort_values('pyhx_required_field')
            )
            if not stat.empty:
                y = np.arange(len(stat))
                vals = stat['ready'].values.astype(float)
                colors = ['#16a34a' if v >= 0.99 else '#ef4444' for v in vals]
                fig, ax = plt.subplots(figsize=(9, max(3.2, 0.5 * len(stat) + 1.5)))
                ax.barh(y, vals, color=colors)
                ax.set_yticks(y, stat['pyhx_required_field'].astype(str).tolist())
                ax.set_xlim(0, 1.0)
                ax.set_xlabel('ready fraction')
                ax.set_title('HDX required-field readiness')
                ax.grid(True, axis='x', linestyle='--', alpha=0.3)
                fig.tight_layout()
                p = os.path.join(diag_dir, 'hdx_fits_required_field_readiness.png')
                fig.savefig(p, dpi=180)
                plt.close(fig)
                plot_paths.append(p)

    if not plot_paths:
        return False, 'No HDX diagnostics were generated (insufficient data).', []
    return True, f'Generated {len(plot_paths)} HDX diagnostics.', plot_paths


def _generate_hdx_fit_output_interpretation_plots(
    data_fits_csv: str,
    run_dir: str,
    out_dir: str,
) -> tuple[bool, str, list[str], dict[str, str]]:
    """Generate fit-output interpretation plots as static diagnostics."""
    if not data_fits_csv or not os.path.isfile(data_fits_csv):
        return False, 'No data_fits CSV available for interpretation diagnostics.', [], {}
    try:
        dff = pd.read_csv(data_fits_csv)
    except Exception as e:
        return False, f'Could not read data_fits CSV: {e}', [], {}
    if dff is None or dff.empty:
        return False, 'data_fits CSV is empty for interpretation diagnostics.', [], {}

    diag_dir = os.path.join(out_dir, 'diagnostics')
    os.makedirs(diag_dir, exist_ok=True)
    out_paths: list[str] = []
    expl: dict[str, str] = {}

    fit_df = dff.copy()
    fit_df['time'] = pd.to_numeric(fit_df.get('time'), errors='coerce')
    fit_df['label'] = np.where(fit_df['time'] > 0, 'D', 'UN')
    fit_df['data_id'] = pd.to_numeric(fit_df.get('data_id'), errors='coerce').astype('Int64')
    fit_df['centroid'] = pd.to_numeric(fit_df.get('centroid'), errors='coerce')
    fit_df['fit_pops'] = pd.to_numeric(fit_df.get('fit_pops'), errors='coerce')
    fit_df['pval'] = pd.to_numeric(
        fit_df['p-value'] if 'p-value' in fit_df.columns else fit_df.get('p_value'),
        errors='coerce',
    )
    agg = (
        fit_df.dropna(subset=['data_id'])
        .groupby(['data_id', 'label'], dropna=False)
        .agg(centroid=('centroid', 'median'), fit_pops=('fit_pops', 'median'), p_value=('pval', 'median'))
        .reset_index()
    )
    if agg.empty:
        return False, 'No grouped fit rows available for interpretation diagnostics.', [], {}
    piv = agg.pivot(index='data_id', columns='label', values=['centroid', 'fit_pops', 'p_value'])
    piv.columns = [f'{a.lower()}_{str(b).lower()}' for a, b in piv.columns]
    piv = piv.reset_index()
    if 'centroid_d' in piv.columns and 'centroid_un' in piv.columns:
        piv['centroid_delta_d_minus_un'] = pd.to_numeric(piv['centroid_d'], errors='coerce') - pd.to_numeric(piv['centroid_un'], errors='coerce')

    # Optional metadata for setting labels.
    meta_df = pd.DataFrame()
    run_csvs = _sort_existing_paths_by_mtime_desc(_find_files(run_dir, ('.csv',))) if run_dir and os.path.isdir(run_dir) else []
    metadf_run_input = next((p for p in run_csvs if '_pyhx_metadf_run_input__' in os.path.basename(p)), '')
    if metadf_run_input and os.path.isfile(metadf_run_input):
        try:
            meta_df = pd.read_csv(metadf_run_input)
        except Exception:
            meta_df = pd.DataFrame()
    if meta_df is not None and not meta_df.empty:
        meta_df['data_id'] = pd.to_numeric(meta_df.get('data_id'), errors='coerce').astype('Int64')
        if 'fragmentation_setting' not in meta_df.columns:
            meta_df['fragmentation_setting'] = meta_df.get('file', pd.Series('', index=meta_df.index)).astype(str).apply(
                lambda x: _infer_fragmentation_setting_from_run_name(os.path.splitext(os.path.basename(str(x)))[0]) or 'UNKNOWN'
            )
    summary_df = piv.copy()
    if meta_df is not None and not meta_df.empty and 'data_id' in meta_df.columns:
        keep_cols = [c for c in ['data_id', 'charge', 'fragmentation_setting'] if c in meta_df.columns]
        summary_df = summary_df.merge(meta_df[keep_cols], on='data_id', how='left')

    # Centroid pairing.
    if {'centroid_un', 'centroid_d'}.issubset(summary_df.columns):
        p_df = summary_df.dropna(subset=['centroid_un', 'centroid_d']).copy()
        if not p_df.empty:
            fig, ax = plt.subplots(figsize=(8.5, 4.5))
            x = np.arange(len(p_df))
            y_un = pd.to_numeric(p_df['centroid_un'], errors='coerce').values
            y_d = pd.to_numeric(p_df['centroid_d'], errors='coerce').values
            for i in range(len(x)):
                ax.plot([x[i], x[i]], [y_un[i], y_d[i]], color='#94a3b8', linewidth=1.2, alpha=0.8)
            ax.scatter(x, y_un, color='#2563eb', s=26, label='UN')
            ax.scatter(x, y_d, color='#ef4444', s=26, label='D')
            ax.set_title('Centroid pairing by dataset (UN vs D)')
            ax.set_xlabel('dataset index')
            ax.set_ylabel('centroid m/z')
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            ax.legend()
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fit_centroid_pairing.png')
            fig.savefig(p, dpi=220)
            plt.close(fig)
            out_paths.append(p)
            expl[os.path.basename(p)] = "- **What this shows:** paired UN and D centroid values per dataset.\n- **Use it for:** spotting settings with larger UN→D shifts."

    # Fit populations by label.
    if {'fit_pops_un', 'fit_pops_d'}.issubset(summary_df.columns):
        p_df = summary_df.dropna(subset=['fit_pops_un', 'fit_pops_d']).copy()
        if not p_df.empty:
            fig, ax = plt.subplots(figsize=(8.5, 4.2))
            x = np.arange(len(p_df))
            ax.bar(x - 0.18, pd.to_numeric(p_df['fit_pops_un'], errors='coerce').fillna(0).values, width=0.34, color='#2563eb', label='UN')
            ax.bar(x + 0.18, pd.to_numeric(p_df['fit_pops_d'], errors='coerce').fillna(0).values, width=0.34, color='#ef4444', label='D')
            ax.set_title('Fitted population count by dataset')
            ax.set_xlabel('dataset index')
            ax.set_ylabel('fit_pops')
            ax.set_ylim(bottom=0)
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            ax.legend()
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fit_populations_by_label.png')
            fig.savefig(p, dpi=220)
            plt.close(fig)
            out_paths.append(p)
            expl[os.path.basename(p)] = "- **What this shows:** fitted `fit_pops` for UN and D by dataset.\n- **Use it for:** identifying complexity mismatches between labels."

    # p-value trend.
    if {'p_value_un', 'p_value_d'}.issubset(summary_df.columns):
        p_df = summary_df.dropna(subset=['p_value_un', 'p_value_d']).copy()
        if not p_df.empty:
            fig, ax = plt.subplots(figsize=(8.5, 4.2))
            x = np.arange(len(p_df))
            ax.plot(x, pd.to_numeric(p_df['p_value_un'], errors='coerce').values, marker='o', color='#2563eb', linewidth=1.2, label='UN p-value')
            ax.plot(x, pd.to_numeric(p_df['p_value_d'], errors='coerce').values, marker='o', color='#ef4444', linewidth=1.2, label='D p-value')
            ax.set_title('Fit p-value trend by dataset')
            ax.set_xlabel('dataset index')
            ax.set_ylabel('p-value')
            ax.set_ylim(bottom=0)
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            ax.legend()
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fit_pvalue_trend_by_label.png')
            fig.savefig(p, dpi=220)
            plt.close(fig)
            out_paths.append(p)
            expl[os.path.basename(p)] = "- **What this shows:** UN and D p-value trends across datasets.\n- **Use it for:** spotting confidence divergence by condition."

    # Delta by setting.
    if 'centroid_delta_d_minus_un' in summary_df.columns:
        p_df = summary_df.dropna(subset=['centroid_delta_d_minus_un']).copy()
        if not p_df.empty:
            x_labels = [
                f"{str(r.get('fragmentation_setting', 'UNKNOWN'))} | z{int(r.get('charge')) if pd.notna(r.get('charge')) else '?'}"
                for _, r in p_df.iterrows()
            ]
            y_vals = pd.to_numeric(p_df['centroid_delta_d_minus_un'], errors='coerce').fillna(0).values
            fig, ax = plt.subplots(figsize=(10, 4))
            ax.bar(np.arange(len(y_vals)), y_vals, color='#62c1e5')
            ax.axhline(0.0, color='#6b7280', linewidth=1)
            ax.set_xticks(np.arange(len(y_vals)))
            ax.set_xticklabels(x_labels, rotation=25, ha='right', fontsize=8)
            ax.set_ylabel('centroid(D) - centroid(UN)')
            ax.set_title('UN-vs-D centroid shift by fragmentation setting')
            ax.grid(True, axis='y', linestyle='--', alpha=0.3)
            fig.tight_layout()
            p = os.path.join(diag_dir, 'hdx_fit_centroid_delta_by_setting.png')
            fig.savefig(p, dpi=220)
            plt.close(fig)
            out_paths.append(p)
            expl[os.path.basename(p)] = "- **What this shows:** centroid shift magnitude (`D - UN`) by setting.\n- **Use it for:** comparing shift patterns across fragmentation conditions."

    # 5) Spectra grid by setting (UN/H left, D right), replicates overlaid.
    deut_run_input = next((p for p in run_csvs if '_pyhx_deutdata_run_input__' in os.path.basename(p)), '')
    if deut_run_input and os.path.isfile(deut_run_input):
        try:
            dinput = pd.read_csv(deut_run_input)
        except Exception:
            dinput = pd.DataFrame()
        if dinput is not None and not dinput.empty and {'mz', 'Intensity'}.issubset(dinput.columns):
            dplot = dinput.copy()
            dplot['mz'] = pd.to_numeric(dplot.get('mz'), errors='coerce')
            dplot['Intensity'] = pd.to_numeric(dplot.get('Intensity'), errors='coerce')
            dplot = dplot.dropna(subset=['mz', 'Intensity'])
            dplot = dplot[(dplot['mz'] > 0) & (dplot['Intensity'] >= 0)].copy()
            if dplot.empty:
                pass
            else:
                # Label normalization: treat H as undeuterated-side for display.
                if 'label_h_or_d' in dplot.columns:
                    dplot['label_h_or_d'] = dplot['label_h_or_d'].astype(str).str.upper()
                else:
                    dplot['label_h_or_d'] = np.where(pd.to_numeric(dplot.get('time'), errors='coerce').fillna(0) > 0, 'D', 'UN')
                dplot['label_side'] = np.where(dplot['label_h_or_d'].isin(['D']), 'D', 'UN')

                if 'rep' in dplot.columns:
                    dplot['rep'] = pd.to_numeric(dplot.get('rep'), errors='coerce').fillna(1).astype(int)
                else:
                    dplot['rep'] = 1

                if 'fragmentation_setting' not in dplot.columns:
                    if 'source_mzml' in dplot.columns:
                        dplot['fragmentation_setting'] = dplot['source_mzml'].astype(str).apply(
                            lambda x: _infer_fragmentation_setting_from_run_name(os.path.splitext(os.path.basename(str(x)))[0]) or 'UNKNOWN'
                        )
                    else:
                        dplot['fragmentation_setting'] = 'UNKNOWN'
                dplot['fragmentation_setting'] = dplot['fragmentation_setting'].astype(str)

                # Centroid map by setting + label.
                centroid_map: dict[tuple[str, str], float] = {}
                if not summary_df.empty and 'fragmentation_setting' in summary_df.columns:
                    if 'centroid_un' in summary_df.columns:
                        c_un = (
                            summary_df[['fragmentation_setting', 'centroid_un']]
                            .copy()
                            .dropna(subset=['fragmentation_setting'])
                        )
                        for _, rr in c_un.iterrows():
                            k = (str(rr['fragmentation_setting']), 'UN')
                            v = pd.to_numeric(pd.Series([rr.get('centroid_un')]), errors='coerce').iloc[0]
                            if pd.notna(v):
                                centroid_map[k] = float(v) if k not in centroid_map else float(np.nanmedian([centroid_map[k], float(v)]))
                    if 'centroid_d' in summary_df.columns:
                        c_d = (
                            summary_df[['fragmentation_setting', 'centroid_d']]
                            .copy()
                            .dropna(subset=['fragmentation_setting'])
                        )
                        for _, rr in c_d.iterrows():
                            k = (str(rr['fragmentation_setting']), 'D')
                            v = pd.to_numeric(pd.Series([rr.get('centroid_d')]), errors='coerce').iloc[0]
                            if pd.notna(v):
                                centroid_map[k] = float(v) if k not in centroid_map else float(np.nanmedian([centroid_map[k], float(v)]))

                settings = sorted([str(x) for x in dplot['fragmentation_setting'].dropna().unique().tolist()])
                if settings:
                    reps = sorted([int(x) for x in dplot['rep'].dropna().unique().tolist()])
                    rep_colors = plt.cm.tab10(np.linspace(0, 1, max(1, len(reps))))
                    rep_color_map = {int(r): rep_colors[i % len(rep_colors)] for i, r in enumerate(reps)}
                    nrows = len(settings)
                    fig, axes = plt.subplots(
                        nrows=nrows,
                        ncols=2,
                        figsize=(12.5, max(3.0 * nrows, 5.5)),
                        squeeze=False,
                    )
                    for i, setting in enumerate(settings):
                        for j, side in enumerate(['UN', 'D']):
                            ax = axes[i, j]
                            sub = dplot[(dplot['fragmentation_setting'] == setting) & (dplot['label_side'] == side)].copy()
                            if sub.empty:
                                ax.text(0.5, 0.5, 'No spectra', ha='center', va='center', transform=ax.transAxes, color='#6b7280')
                                ax.set_xticks([])
                                ax.set_yticks([])
                            else:
                                for rep in sorted(sub['rep'].dropna().unique().tolist()):
                                    sr = sub[sub['rep'] == rep].sort_values('mz')
                                    if sr.empty:
                                        continue
                                    ax.plot(
                                        sr['mz'].astype(float).values,
                                        sr['Intensity'].astype(float).values,
                                        color=rep_color_map.get(int(rep), '#334155'),
                                        linewidth=1.2,
                                        alpha=0.9,
                                        label=f'rep{int(rep)}',
                                    )
                                # Bold centroid marker/label if available.
                                ck = (str(setting), str(side))
                                cval = centroid_map.get(ck, None)
                                if cval is not None and np.isfinite(float(cval)):
                                    ax.axvline(float(cval), color='black', linewidth=1.6, linestyle='--')
                                    y_top = ax.get_ylim()[1] if np.isfinite(ax.get_ylim()[1]) and ax.get_ylim()[1] > 0 else 1.0
                                    ax.text(
                                        float(cval),
                                        y_top * 0.92,
                                        f'centroid={float(cval):.4f}',
                                        rotation=90,
                                        va='top',
                                        ha='right',
                                        fontsize=8,
                                        fontweight='bold',
                                        color='black',
                                        bbox=dict(facecolor='white', alpha=0.75, edgecolor='none', pad=1.2),
                                    )
                                if i == 0 and j == 0:
                                    handles, labels = ax.get_legend_handles_labels()
                                    if handles:
                                        ax.legend(handles, labels, fontsize=7, loc='upper right')
                                ax.grid(True, axis='y', linestyle='--', alpha=0.25)
                                ax.set_xlabel('m/z', fontsize=8)
                                ax.set_ylabel('Intensity', fontsize=8)
                            title_side = 'Undeuterated (UN/H)' if side == 'UN' else 'Deuterated (D)'
                            ax.set_title(f'{setting} | {title_side}', fontsize=9)
                    fig.suptitle('Spectra grid by activation setting (replicates overlaid)', fontsize=12, y=0.998)
                    fig.tight_layout(rect=[0, 0, 1, 0.985])
                    p = os.path.join(diag_dir, 'hdx_fit_spectra_grid_by_setting.png')
                    fig.savefig(p, dpi=220)
                    plt.close(fig)
                    if os.path.isfile(p):
                        out_paths.append(p)
                        expl[os.path.basename(p)] = (
                            "- **Layout:** one row per activation setting, UN/H on left and D on right.\n"
                            "- **Lines:** replicate spectra overlaid with distinct colors.\n"
                            "- **Bold dashed line + label:** fitted centroid for that side/setting."
                        )

    out_paths = [p for p in out_paths if os.path.isfile(str(p))]
    if not out_paths:
        return False, 'No fit-output interpretation diagnostics were generated.', [], {}
    return True, f'Generated {len(out_paths)} fit-output interpretation diagnostics.', out_paths, expl


def _infer_fasta_family(fasta_path: str) -> str:
    base = os.path.splitext(os.path.basename(str(fasta_path or '')))[0]
    return _infer_family_from_text(base)


def _infer_mzml_family(mzml_path: str) -> str:
    base = os.path.splitext(os.path.basename(str(mzml_path or '')))[0]
    return _infer_family_from_text(base)


def _read_fasta_target_sequences(fasta_path: str) -> list[tuple[str, str]]:
    """Return non-decoy FASTA records as (header_id, sequence)."""
    out: list[tuple[str, str]] = []
    if not fasta_path or not os.path.isfile(fasta_path):
        return out
    cur_id = ''
    cur_seq: list[str] = []

    def _flush() -> None:
        nonlocal cur_id, cur_seq, out
        if not cur_id:
            return
        seq = ''.join(cur_seq).strip().upper()
        if not seq:
            return
        hid = str(cur_id).strip()
        low = hid.lower()
        # Skip common decoy labels in local workflows.
        if low.startswith('decoy_') or low.startswith('rev_') or (' decoy' in low):
            return
        out.append((hid, seq))

    try:
        with open(fasta_path, 'r', encoding='utf-8', errors='replace') as fh:
            for raw in fh:
                line = str(raw or '').strip()
                if not line:
                    continue
                if line.startswith('>'):
                    _flush()
                    header = line[1:].strip()
                    cur_id = (header.split()[0] if header else '').strip()
                    cur_seq = []
                else:
                    cur_seq.append(line.replace(' ', '').replace('\t', ''))
        _flush()
    except Exception:
        return []
    return out


def _prepare_single_peptide_comet_params(base_params_path: str, fasta_path: str, out_dir: str) -> tuple[str, str, str]:
    """
    Build a run-specific Comet params file for single-peptide mode.
    Enforces no-cut candidate generation and all ion-series scoring.
    Returns (params_path_or_empty, note, error_or_empty).
    """
    if not base_params_path or not os.path.isfile(base_params_path):
        return '', '', f'Comet params file not found: {base_params_path}'
    if not fasta_path or not os.path.isfile(fasta_path):
        return '', '', f'FASTA file not found: {fasta_path}'
    records = _read_fasta_target_sequences(fasta_path)
    if not records:
        return '', '', 'No non-decoy FASTA sequences were found for single-peptide mode.'
    lengths = sorted(set(len(seq) for _, seq in records if seq))
    if not lengths:
        return '', '', 'Could not resolve peptide lengths from FASTA for single-peptide mode.'
    min_len = int(min(lengths))
    max_len = int(max(lengths))
    target_count = int(len(records))

    try:
        with open(base_params_path, 'r', encoding='utf-8', errors='replace') as fh:
            content = fh.read()
    except Exception as e:
        return '', '', f'Could not read Comet params file: {e}'

    updates: dict[str, str] = {
        'search_enzyme_number': '11',
        'search_enzyme2_number': '0',
        'num_enzyme_termini': '2',
        'allowed_missed_cleavage': '0',
        # Use permissive precursor tolerance in single-peptide comparison mode.
        'peptide_mass_tolerance_upper': '80.0',
        'peptide_mass_tolerance_lower': '-80.0',
        'isotope_error': '5',
        # UVPD fragment matching can be brittle with very tight bins.
        'fragment_bin_tol': '0.05',
        'num_output_lines': '25',
        # Single-peptide UVPD data often target higher isotope peaks (M+N).
        # Include an explicit neutral-mass isotope ladder so Comet can score
        # precursor targets near M+1..M+8, not only strict monoisotopic.
        'mass_offsets': '0.000000 1.003355 2.006710 3.010065 4.013419 5.016774 6.020129 7.023484 8.026839',
        'peptide_length_range': f'{min_len} {max_len}',
        'use_A_ions': '1',
        'use_B_ions': '1',
        'use_C_ions': '1',
        'use_X_ions': '1',
        'use_Y_ions': '1',
        'use_Z_ions': '1',
        'use_Z1_ions': '1',
    }

    for k, v in updates.items():
        pat = rf'(?mi)^\s*{re.escape(k)}\s*=.*$'
        repl = f'{k} = {v}'
        if re.search(pat, content):
            content = re.sub(pat, repl, content, count=1)
        else:
            # Insert before enzyme info block when possible, else append.
            enz_pat = r'(?mi)^\[COMET_ENZYME_INFO\]\s*$'
            m = re.search(enz_pat, content)
            if m:
                content = content[:m.start()] + repl + '\n' + content[m.start():]
            else:
                if not content.endswith('\n'):
                    content += '\n'
                content += repl + '\n'

    safe_dir = out_dir if (out_dir and os.path.isdir(out_dir)) else os.path.dirname(base_params_path)
    ts = _timestamp_token()
    base_stem = _sanitize_name_token(os.path.splitext(os.path.basename(base_params_path))[0]) or 'comet_params'
    out_path = os.path.join(safe_dir, _dedup_same_day_dates_in_name(f'{base_stem}__single_peptide_mode__{ts}.params'))
    try:
        with open(out_path, 'w', encoding='utf-8') as fh:
            fh.write(content)
    except Exception as e:
        return '', '', f'Could not write single-peptide Comet params file: {e}'

    if min_len == max_len:
        len_note = f'exact peptide length={min_len}'
    else:
        len_note = f'peptide length range={min_len}-{max_len} (from {target_count} FASTA entries)'
    note = (
        'Single-peptide mode params prepared '
        f'({len_note}; No_cut + all ion types + permissive ppm/fragment bins + isotope mass_offsets ladder enabled): `{out_path}`'
    )
    return out_path, note, ''


def _is_preferred_p1_lpt_dataset(path_like: str) -> bool:
    s = str(path_like or '').strip().lower()
    if not s:
        return False
    compact = re.sub(r'[^a-z0-9]+', '', s)
    if 'p1uvpdlpt' in compact or 'p1lpt' in compact:
        return True
    has_p1 = bool(re.search(r'(^|[^a-z0-9])p1([^a-z0-9]|$)', s))
    has_lpt = ('lpt' in s)
    return bool(has_p1 and has_lpt)


def _is_preferred_p1_fasta(path_like: str) -> bool:
    s = str(path_like or '').strip().lower()
    if not s:
        return False
    if not s.endswith(FASTA_EXT):
        return False
    b = os.path.basename(s)
    compact = re.sub(r'[^a-z0-9]+', '', b)
    if 'p1' in compact and ('lpt' in compact or 'uvpd' in compact):
        return True
    return bool(re.search(r'(^|[^a-z0-9])p1([^a-z0-9]|$)', b))


def _preferred_index(options: list[str], predicate, fallback_idx: int = 0) -> int:
    try:
        for i, opt in enumerate(options or []):
            if predicate(opt):
                return int(i)
    except Exception:
        pass
    return int(fallback_idx)


def _collect_fasta_file_candidates(
    work_root: str = '',
    data_dir: str = '',
    include_uploads: bool = True,
) -> list[str]:
    """FASTA paths from workspace data/fasta, data_dir, and optional uploads."""
    seen: set[str] = set()
    out: list[str] = []

    def _add_many(paths) -> None:
        for p in paths or []:
            ap = os.path.abspath(str(p or '').strip())
            if not ap or ap in seen or not os.path.isfile(ap):
                continue
            if not any(ap.lower().endswith(ext) for ext in FASTA_EXT):
                continue
            seen.add(ap)
            out.append(ap)

    wr = str(work_root or '').strip()
    if wr and os.path.isdir(wr):
        try:
            ws_dirs = _workspace_tab_dirs(wr) or {}
        except Exception:
            ws_dirs = {}
        fasta_dir = str(ws_dirs.get('fasta') or os.path.join(wr, 'data', 'fasta')).strip()
        if fasta_dir and os.path.isdir(fasta_dir):
            _add_many(_find_files(fasta_dir, FASTA_EXT))

    dd = str(data_dir or '').strip()
    if dd and os.path.isdir(dd):
        _add_many(_list_files_shallow(dd, FASTA_EXT))
        fasta_sub = os.path.join(dd, 'fasta')
        if os.path.isdir(fasta_sub):
            _add_many(_find_files(fasta_sub, FASTA_EXT))

    if include_uploads:
        up = st.session_state.get('uploaded_fasta')
        if up and isinstance(up, (list, tuple)) and len(up) >= 2:
            fname, fval = up[0], up[1]
            fp = str(fval or '').strip()
            if not fp and fname:
                ud = str(st.session_state.get('uploaded_data_dir') or '').strip()
                if ud:
                    fp = os.path.join(ud, str(fname))
            _add_many([fp] if fp else [])

    return _sort_existing_paths_by_mtime_desc(out)


def _is_decoy_protein_label(name: str) -> bool:
    s = str(name or '').strip().upper()
    if not s:
        return False
    return (
        s.startswith('DECOY_')
        or s.startswith('REV_')
        or s.endswith('_DECOY')
        or bool(re.search(r'(^|[^A-Z0-9])DECOY([^A-Z0-9]|$)', s))
    )


def _unique_proteins_from_csv(csv_path: str) -> list[str]:
    path = str(csv_path or '').strip()
    if not path or not os.path.isfile(path):
        return []
    try:
        import pandas as pd
    except ImportError:
        return []
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as fh:
            first = fh.readline()
        skip = 1 if 'CometVersion' in first else 0
        header = pd.read_csv(path, nrows=0, sep=',', skiprows=skip, engine='python')
        col = None
        for c in ('protein', 'Protein', 'protein_id', 'accession', 'protein_name'):
            if c in header.columns:
                col = c
                break
        if not col:
            return []
        series = pd.read_csv(
            path,
            usecols=[col],
            sep=',',
            skiprows=skip,
            engine='python',
            dtype=str,
        )[col]
    except Exception:
        return []
    out: list[str] = []
    seen: set[str] = set()
    for val in series.dropna().astype(str).str.strip():
        if not val or val.lower() == 'nan' or val in seen:
            continue
        seen.add(val)
        out.append(val)
    out.sort(key=lambda x: (_is_decoy_protein_label(x), x.lower()))
    return out


def _sync_sequence_coverage_protein_state(csv_path: str) -> list[str]:
    proteins = _unique_proteins_from_csv(csv_path)
    token = os.path.abspath(str(csv_path or '').strip())
    if st.session_state.get('sequence_coverage_protein_input') != token:
        st.session_state.sequence_coverage_protein_input = token
        st.session_state.sequence_coverage_protein_include = {
            p: not _is_decoy_protein_label(p) for p in proteins
        }
    return proteins


def _render_sequence_coverage_protein_checkboxes(proteins: list[str], input_token: str) -> list[str]:
    if not proteins:
        return []
    include_map = dict(st.session_state.get('sequence_coverage_protein_include') or {})
    st.markdown('**Proteins to include**')
    st.caption('Unchecked proteins are dropped before coverage and plots.')
    n_cols = min(4, max(1, len(proteins)))
    cols = st.columns(n_cols)
    selected: list[str] = []
    token = re.sub(r'[^A-Za-z0-9]+', '_', str(input_token or 'input'))[:24]
    for i, prot in enumerate(proteins):
        default = bool(include_map.get(prot, not _is_decoy_protein_label(prot)))
        slug = re.sub(r'[^A-Za-z0-9]+', '_', str(prot))[:40] or 'protein'
        with cols[i % n_cols]:
            checked = st.checkbox(
                str(prot),
                value=default,
                key=f'seq_cov_prot_{token}_{slug}',
            )
        if checked:
            selected.append(prot)
    st.session_state.sequence_coverage_protein_include = {p: (p in selected) for p in proteins}
    return selected


def _sequence_coverage_protein_cli_args(selected_proteins: list[str] | None = None) -> list[str]:
    selected = list(selected_proteins or [])
    if not selected:
        inc = st.session_state.get('sequence_coverage_protein_include') or {}
        selected = [p for p, on in inc.items() if on]
    if selected:
        return ['--include-proteins', ','.join(str(p) for p in selected)]
    return ['--exclude-decoys']


def _load_sequence_coverage_input_df(csv_path: str) -> pd.DataFrame | None:
    path = str(csv_path or '').strip()
    if not path or not os.path.isfile(path):
        return None
    try:
        return load_csv(path)
    except Exception:
        try:
            with open(path, 'r') as f:
                first = f.readline()
            skip = 1 if 'CometVersion' in first else 0
            return pd.read_csv(path, sep=',', skiprows=skip, engine='python', quotechar='"', on_bad_lines='warn')
        except Exception:
            return None


def _discover_precursor_charges_in_csv(csv_path: str) -> list[int]:
    """Precursor (peptide) charges present in the input CSV charge column."""
    df = _load_sequence_coverage_input_df(csv_path)
    if df is None or df.empty:
        return []
    try:
        from workflow_scripts.compare_unique_peptides_sequence import discover_precursor_charges
    except ImportError:
        from compare_unique_peptides_sequence import discover_precursor_charges
    return discover_precursor_charges(df)


def _precursor_charge_peptide_counts(df: pd.DataFrame | None) -> dict[int, int]:
    """Unique sequence+charge per precursor charge (row count if no peptide column)."""
    if df is None or df.empty or 'charge' not in df.columns:
        return {}
    pep_col = next((c for c in ['peptide_sequence', 'plain_peptide', 'peptide'] if c in df.columns), None)
    ch_series = pd.to_numeric(df['charge'], errors='coerce')
    if pep_col:
        sub = pd.DataFrame({
            '_pep': df[pep_col].astype(str).str.strip(),
            '_ch': ch_series,
        })
        sub = sub[sub['_pep'].astype(str).str.len().gt(0) & sub['_ch'].notna()].copy()
        sub['_ch'] = sub['_ch'].astype(int)
        if sub.empty:
            return {}
        return {int(z): int(n) for z, n in sub.groupby('_ch')['_pep'].nunique().items()}
    vc = ch_series.dropna().astype(int).value_counts()
    return {int(z): int(n) for z, n in vc.items()}


def _format_total_area_threshold(val: float) -> str:
    return f'{float(val):.6g}'


def _sequence_coverage_total_area_retention_table(
    df: pd.DataFrame | None,
    *,
    percentile_step: int = 10,
) -> pd.DataFrame:
    """For binned minimum total_area cutoffs (by percentile), rows retained vs excluded."""
    cols = ['Min total area', 'Percentile', 'Retained', 'Excluded']
    if df is None or df.empty or 'total_area' not in df.columns:
        return pd.DataFrame(columns=cols)
    ta = pd.to_numeric(df['total_area'], errors='coerce')
    n_total = int(len(df))
    if n_total == 0 or not ta.notna().any():
        return pd.DataFrame(columns=cols)
    step = max(1, int(percentile_step or 10))
    percentiles = list(range(0, 101, step))
    if percentiles[-1] != 100:
        percentiles.append(100)
    rows = []
    seen_thr: set[float] = set()
    for p in percentiles:
        thr = float(ta.quantile(p / 100.0))
        thr_key = round(thr, 6)
        if thr_key in seen_thr:
            continue
        seen_thr.add(thr_key)
        kept = int((ta >= thr).sum())
        pct_label = 'min' if p == 0 else ('max' if p == 100 else f'p{p}')
        rows.append({
            'Min total area': _format_total_area_threshold(thr),
            'Percentile': pct_label,
            'Retained': kept,
            'Excluded': n_total - kept,
            '_thr': thr,
        })
    return pd.DataFrame(rows)


def _sequence_coverage_total_area_retention_for_min(
    df: pd.DataFrame | None,
    min_total_area: float,
) -> tuple[int, int]:
    if df is None or df.empty or 'total_area' not in df.columns:
        return 0, 0
    ta = pd.to_numeric(df['total_area'], errors='coerce')
    n_total = int(len(df))
    kept = int((ta >= float(min_total_area)).sum())
    return kept, n_total - kept


def _sequence_coverage_overhang_retention_table(
    df: pd.DataFrame | None,
    ion_types_raw: str | None = None,
) -> pd.DataFrame:
    """For each minimum overhang count, how many rows would be kept vs excluded (after ion-type filter)."""
    cols = ['Min positions', 'Retained', 'Excluded']
    if df is None or df.empty:
        return pd.DataFrame(columns=cols)
    try:
        from workflow_scripts.compare_unique_peptides_sequence import (
            _apply_fragment_filters_df,
            _resolve_overhang_columns,
            _resolved_overhang_protein_position_count,
        )
    except ImportError:
        from compare_unique_peptides_sequence import (
            _apply_fragment_filters_df,
            _resolve_overhang_columns,
            _resolved_overhang_protein_position_count,
        )
    preview = df.copy()
    ion_raw = str(ion_types_raw or '').strip()
    if ion_raw:
        preview = _apply_fragment_filters_df(preview, ion_raw, '')
        if preview is None or preview.empty:
            return pd.DataFrame(columns=cols)
    col_prot, _, _ = _resolve_overhang_columns(preview)
    oh_counts = preview.apply(lambda r: _resolved_overhang_protein_position_count(r, col_prot), axis=1)
    n_total = int(len(preview))
    if n_total == 0:
        return pd.DataFrame(columns=cols)
    max_m = int(oh_counts.max()) if oh_counts.notna().any() else 0
    rows = []
    for m in range(0, max_m + 1):
        kept = int((oh_counts >= m).sum())
        rows.append({'Min positions': m, 'Retained': kept, 'Excluded': n_total - kept})
    return pd.DataFrame(rows)


def _render_sequence_coverage_charge_checkboxes(
    available: list[int],
    *,
    input_token: str,
    key_prefix: str,
    label_prefix: str,
    title: str,
    help_text: str,
    charge_peptide_counts: dict[int, int] | None = None,
) -> set[int]:
    """Render one checkbox per charge; default all selected."""
    charges = sorted({int(z) for z in (available or []) if int(z) > 0})
    if not charges:
        return set()
    counts = {int(k): int(v) for k, v in (charge_peptide_counts or {}).items()}
    st.markdown(title)
    if counts:
        st.caption('Counts in parentheses are unique sequence+charge in the current input CSV.')
    n_cols = min(6, max(1, len(charges)))
    cols = st.columns(n_cols)
    selected: set[int] = set()
    token = re.sub(r'[^A-Za-z0-9]+', '_', str(input_token or 'input'))[:24]
    for i, z in enumerate(charges):
        key = f'{key_prefix}_{token}_{int(z)}'
        n_pep = counts.get(int(z))
        label = f'{label_prefix}{int(z)} ({n_pep})' if n_pep is not None else f'{label_prefix}{int(z)}'
        with cols[i % n_cols]:
            if st.checkbox(
                label,
                value=bool(st.session_state.get(key, True)),
                key=key,
                help=help_text,
            ):
                selected.add(int(z))
    return selected


def _sequence_coverage_precursor_charges_cli_arg(csv_path: str, selected: set[int] | None = None) -> list[str]:
    avail = _discover_precursor_charges_in_csv(csv_path)
    if not avail:
        return []
    sel = sorted(selected) if selected is not None else avail
    if set(sel) >= set(avail):
        return []
    return ['--precursor-charges', ','.join(str(z) for z in sel)]


