    def _terminal_slice(text: str, mode: str, max_lines: int = 500) -> tuple[str, str]:
        lines = str(text or "").splitlines()
        total = len(lines)
        if total <= max_lines:
            return str(text or ""), f"Showing all {total} lines."
        if mode == 'top':
            shown = lines[:max_lines]
            return "\n".join(shown), f"Showing first {max_lines} of {total} lines."
        shown = lines[-max_lines:]
        return "\n".join(shown), f"Showing latest {max_lines} of {total} lines."

    def _terminal_latest_first(text: str, max_lines: int = 500) -> tuple[str, str]:
        """Live-run view: show latest lines in natural top-to-bottom order."""
        lines = str(text or "").splitlines()
        total = len(lines)
        shown = lines[-max_lines:] if total > max_lines else lines
        if total <= max_lines:
            return "\n".join(shown), f"Showing all {total} lines (newest at bottom)."
        return "\n".join(shown), f"Showing latest {max_lines} of {total} lines (newest at bottom)."

    def _humanize_extraction_terminal_text(text: str) -> str:
        """
        Improve readability of Extraction terminal output for the app panel.
        Adds spacing, friendlier labels, and indentation for key/value lines.
        """
        raw_lines = str(text or '').splitlines()
        out_lines: list[str] = []

        def _emit_break() -> None:
            if out_lines and str(out_lines[-1]).strip():
                out_lines.append('')

        for raw in raw_lines:
            line = str(raw or '').rstrip()
            if not line:
                if out_lines and str(out_lines[-1]).strip():
                    out_lines.append('')
                continue

            # Strip noisy prefix in this view and map to friendlier text.
            if line.startswith('[Step 6]'):
                line = line[len('[Step 6]'):].strip()

            if line.startswith('Run context'):
                _emit_break()
                out_lines.append('Extraction Run Context')
                out_lines.append('')
                continue
            if line.startswith('Active gate configuration'):
                _emit_break()
                out_lines.append('Active Gate Configuration')
                out_lines.append('')
                continue
            if line.startswith('Starting chromatogram extraction'):
                _emit_break()
                out_lines.append('Starting Chromatogram Extraction')
                continue

            # Translate common key/value snippets.
            line = line.replace('local_snr_mode:', 'Local SNR mode:')
            line = line.replace('adaptive_snr_cap:', 'Adaptive SNR cap:')
            line = line.replace('local_snr_threshold:', 'Local SNR threshold:')
            line = line.replace('safety_floor:', 'Safety floor apex:')
            line = line.replace('input_csv:', 'Input CSV:')
            line = line.replace('output_dir:', 'Output directory:')
            line = line.replace('plots_dir:', 'Plots directory:')
            line = line.replace('Output CSV saved to:', 'Saved output CSV:')

            # Indent relation/key-value lines for scanability.
            if (':' in line) and not line.startswith('Error'):
                out_lines.append(f'  {line}')
            else:
                out_lines.append(line)

        return '\n'.join(out_lines).strip()

    def _render_terminal_text_with_controls(
        panel_key: str,
        text_value: str,
        height_px: int = 260,
        empty_caption: str = 'Run a step to print logs here.',
    ) -> None:
        mode_key = f'terminal_view_mode_{panel_key}'
        if mode_key not in st.session_state:
            st.session_state[mode_key] = 'latest'
        has_output = bool(str(text_value or '').strip())
        c_top, c_latest, c_note = st.columns([1.3, 1.0, 5.7])
        with c_top:
            if st.button('Show from top', key=f'terminal_show_top_{panel_key}', disabled=not has_output):
                st.session_state[mode_key] = 'top'
        with c_latest:
            if st.button('Latest', key=f'terminal_show_latest_{panel_key}', disabled=not has_output):
                st.session_state[mode_key] = 'latest'
        if has_output:
            view_mode = str(st.session_state.get(mode_key, 'latest'))
            shown_text, shown_note = _terminal_slice(str(text_value or ''), view_mode, max_lines=500)
            with c_note:
                st.caption(shown_note)
            st.markdown(
                _terminal_html_box(shown_text, height_px=height_px),
                unsafe_allow_html=True,
            )
        else:
            with c_note:
                st.caption('Terminal view toggle appears here when output is available.')
            st.caption(str(empty_caption or ''))

    def _render_terminal(panel_key: str = 'default'):
        term_header = f"Terminal — {st.session_state.script_step}" if st.session_state.script_step else "Terminal"
        with st.expander(term_header, expanded=False, icon='▶'):
            mode_key = f'terminal_view_mode_{panel_key}'
            if mode_key not in st.session_state:
                st.session_state[mode_key] = 'latest'
            has_output = bool(st.session_state.script_output)
            controls_locked = bool(st.session_state.get('script_running', False))
            c_top, c_latest, c_note = st.columns([1.3, 1.0, 5.7])
            with c_top:
                if st.button('Show from top', key=f'terminal_show_top_{panel_key}', disabled=(not has_output) or controls_locked):
                    st.session_state[mode_key] = 'top'
            with c_latest:
                if st.button('Latest', key=f'terminal_show_latest_{panel_key}', disabled=(not has_output) or controls_locked):
                    st.session_state[mode_key] = 'latest'
            if controls_locked:
                with c_note:
                    st.caption('Terminal view toggles are temporarily locked while a run is active.')
            if st.session_state.script_output:
                view_mode = str(st.session_state.get(mode_key, 'latest'))
                shown_text, shown_note = _terminal_slice(st.session_state.script_output, view_mode, max_lines=500)
                if str(panel_key).strip().lower() == 'extraction':
                    shown_text = _humanize_extraction_terminal_text(shown_text)
                with c_note:
                    st.caption(shown_note)
                st.markdown(
                    _terminal_html_box(shown_text, height_px=420),
                    unsafe_allow_html=True,
                )
            else:
                with c_note:
                    st.caption("Terminal view toggle appears here when output is available.")
                st.caption("Run a pipeline step (Step 1–8) to see the latest terminal output here.")

