    def _render_significance_metrics():
        st.markdown('### Filter MS2 matched frags by signal significance')
        sig_fragment_mode = str(st.session_state.get('filter_tab_mode', _filter_mode_default) or _filter_mode_default).startswith('Peptide mode')
        if sig_fragment_mode:
            st.session_state['enable_sig'] = True
        c1, c2, c3, c4 = st.columns(4)
        with c1:
            mode = st.selectbox(
                'MS2 tolerance mode',
                options=['ppm', 'da'],
                key='significance_tol_mode',
                help='Choose one matching unit mode for Significant fragmentation.',
            )
        with c2:
            if mode == 'ppm':
                st.selectbox(
                    'Significance ppm (MS2)',
                    options=ppm_options,
                    key='ppm_thresh',
                    help='PPM tolerance for fragment matching in Significant fragmentation.',
                )
            else:
                st.selectbox(
                    'Significance Da (MS2)',
                    options=da_options,
                    key='significance_da_thresh',
                    help='Absolute Da tolerance for fragment matching in Significant fragmentation.',
                )
        with c3:
            st.number_input(
                'Min % of max peak',
                min_value=0.0,
                max_value=5.0,
                step=0.01,
                key='sig_frac',
                format='%.2f',
                help='Min % of max MS2 for fragment (noise filter)',
            )
        with c4:
            if sig_fragment_mode:
                st.session_state['min_sig'] = 0
            else:
                st.number_input('Min sig frags', 0, 50, 5, 1, key='min_sig')
        c5, c6 = st.columns([1.3, 1.7])
        with c5:
            st.checkbox(
                'Enable minimum MS2 peak intensity filter (M0 only)',
                key='enable_min_peak_intensity_filter',
                help='Require the monoisotopic (M0) peak of each matched fragment to exceed an absolute intensity threshold. Isotopic companions (M+1/M+2/M+3) only need positive signal.',
            )
        with c6:
            st.number_input(
                'Minimum MS2 M0 peak intensity',
                min_value=0.0,
                max_value=1e12,
                step=100.0,
                key='min_peak_intensity_filter',
                format='%.3g',
                disabled=not bool(st.session_state.get('enable_min_peak_intensity_filter', True)),
                help='Absolute minimum intensity for the monoisotopic (M0) fragment peak in summed MS2 (0 disables this gate). Isotopic companions are not subject to this threshold.',
            )
        c7, c8 = st.columns([1.5, 1.5])
        with c7:
            st.checkbox(
                'Require fragment in >=N activation settings',
                key='enable_min_activation_settings_filter',
                help='Keep a fragment only if it is detected across at least N distinct activation settings.',
            )
        with c8:
            st.number_input(
                'Min activation settings (N)',
                min_value=1,
                max_value=64,
                step=1,
                key='min_activation_settings_filter_n',
                disabled=not bool(st.session_state.get('enable_min_activation_settings_filter', False)),
                help='Default N=4.',
            )
        st.checkbox(
            'Require M0 and M+1 in fragment matching',
            key='significance_require_m0_m1',
            help=(
                'Apply fragment-level isotope-envelope gate on the summed MS2 spectrum (not individual scans): '
                'require at least one companion peak (M+1 or M+2 or M+3). '
                'If M+2 or M+3 exists, require each to be below M0.'
            ),
        )
        st.checkbox(
            'Strict envelope filter (M0/M+1/M+2 with M0 > M+1 > M+2)',
            key='significance_strict_envelope_m012',
            help=(
                'Optional stricter gate on summed MS2 matched fragments: '
                'require M+1 and M+2, then enforce M0 > M+1 > M+2.'
            ),
        )
        st.caption(
            'Filter interaction note: the minimum MS2 peak intensity threshold is applied first '
            '(along with tolerance / min-%-of-max / min-sig-frags / min-overhang gates) to define '
            '`significant_frags` per row. The activation-settings gate is then applied to those surviving '
            'fragments. In batch mode, activation-settings gating is applied globally after batch outputs are merged.'
        )
        st.divider()

    def _render_channels_metrics():
        st.markdown('### Channels settings')
        st.selectbox('Number of channels', options=[1, 2, 3, 4, 5], key='channels_count')
        st.divider()

    def _render_envelope_metrics() -> tuple[str, bool, bool]:
        st.markdown('### Envelope settings')
        _sync_envelope_rule_session_label()
        envelope_rule_label = st.selectbox(
            'Envelope rule',
            ENVELOPE_RULE_LABELS,
            key='envelope_rule',
            help='Choose strict M+3-required, M+3-optional, or ignore-M+3 envelope filtering.',
        )
        if envelope_rule_label.startswith('Strict'):
            mode = 'strict_m3_required'
        elif envelope_rule_label.startswith('Ignore M+3'):
            mode = 'm3_ignore'
        else:
            mode = 'm3_optional'
        st.caption(
            f"Active Envelope filter mode: `{mode}`. "
            "Default remains Optional M+3."
        )
        require_m0_m1 = bool(
            st.checkbox(
                'Require M0 and M+1 present',
                key='envelope_require_m0_m1',
                help='When enabled, Envelope step explicitly requires both M0 and M+1 signal before applying envelope shape rules.',
            )
        )
        use_theoretical_h = bool(
            st.checkbox(
                'For H/UN, use theoretical envelope scaled from observed M0',
                key='envelope_theoretical_for_h',
                help=(
                    'When enabled, H/UN rows can use theoretical M+1/M+2/M+3 intensities scaled from observed M0 '
                    'as effective companion peaks during envelope gating.'
                ),
            )
        )
        st.divider()
        return mode, require_m0_m1, use_theoretical_h

    # ─── Apply filters in pipeline order ────────────────────────────────────
    df_filtered = df.copy()
    n_prev = len(df_filtered)
    step_counts = []  # (step_name, passed, total) for summary

    # Step 4: Prefilter (Proline, Modifications, Q/PEP; PPM via Step 5 script)
    xcorr_plot_threshold = float(xcorr_min)
    if enable_conf:
        # Proline: peptide starts/ends with P, or prev_aa/next_aa is P
        if reject_proline:
            mask_pro = pd.Series(True, index=df_filtered.index)
            if 'plain_peptide' in df_filtered.columns:
                def _peptide_has_proline_terminus(seq):
                    if pd.isna(seq) or not seq:
                        return True
                    s = str(seq).strip()
                    return s and (s[0].upper() == 'P' or s[-1].upper() == 'P')
                mask_pro = mask_pro & ~df_filtered['plain_peptide'].apply(_peptide_has_proline_terminus)
            if 'prev_aa' in df_filtered.columns and 'next_aa' in df_filtered.columns:
                def _flank_is_proline(row):
                    prev = str(row.get('prev_aa', '')).strip().upper()
                    next_ = str(row.get('next_aa', '')).strip().upper()
                    return prev == 'P' or next_ == 'P'
                mask_pro = mask_pro & ~df_filtered.apply(_flank_is_proline, axis=1)
            df_filtered = df_filtered[mask_pro].copy()
        # Modifications
        if reject_mods and 'modifications' in df_filtered.columns:
            mask_mods = ~df_filtered['modifications'].apply(_has_modifications)
            df_filtered = df_filtered[mask_mods].copy()
    # Confidence / quality gates honor individual toggles (not gated by enable_conf).
    if (use_q_filter or use_pep_filter) and has_confidence and (qcol or pepcol):
        mask_conf = df_filtered.apply(
            lambda r: _pass_confidence(
                r, df_filtered, qcol, pepcol, q_thresh, pep_thresh,
                use_q=use_q_filter, use_pep=use_pep_filter
            ),
            axis=1
        )
        df_filtered = df_filtered[mask_conf].copy()
    # Optional XCorr / Sp filters
    xcorr_col_runtime = _resolve_col(df_filtered, XCORR_COLS)
    if enable_xcorr_filter and xcorr_col_runtime and xcorr_col_runtime in df_filtered.columns:
        xv = pd.to_numeric(df_filtered[xcorr_col_runtime], errors='coerce')
        if xcorr_threshold_mode == 'auto':
            _pf_diag_dirs = [
                os.path.join(str(out_dir or ''), 'prefilter', 'protein_mode'),
                os.path.join(str(out_dir or ''), 'prefilter'),
                str(out_dir or ''),
            ]
            _auto_xcorr_map = _load_prefilter_auto_xcorr_threshold_map(*_pf_diag_dirs)
            _xcorr_thr_series = _prefilter_xcorr_threshold_series(df_filtered, _auto_xcorr_map, xcorr_min)
            mask_xcorr = xv.isna() | (xv >= _xcorr_thr_series)
            _finite_thr = pd.to_numeric(_xcorr_thr_series, errors='coerce').dropna()
            if not _finite_thr.empty:
                xcorr_plot_threshold = float(_finite_thr.median())
        else:
            mask_xcorr = xv.isna() | (xv >= float(xcorr_min))
            xcorr_plot_threshold = float(xcorr_min)
        df_filtered = df_filtered[mask_xcorr].copy()
    sp_col_runtime = _resolve_col(df_filtered, SP_COLS)
    if enable_sp_filter and sp_col_runtime and sp_col_runtime in df_filtered.columns:
        mask_sp = pd.to_numeric(df_filtered[sp_col_runtime], errors='coerce') >= sp_min
        mask_sp = mask_sp | pd.isna(df_filtered[sp_col_runtime])
        df_filtered = df_filtered[mask_sp].copy()
    # Optional MS1 precursor m/z error filter (ppm or Da)
    mzerr_col_runtime = 'MS1_mz_error_ppm' if 'MS1_mz_error_ppm' in df_filtered.columns else ('MS1_mz_error' if 'MS1_mz_error' in df_filtered.columns else None)
    mzerr_theoretical_col = 'theoretical_mz' if 'theoretical_mz' in df_filtered.columns else ('mz' if 'mz' in df_filtered.columns else None)
    if enable_ms1_mz_error_filter and mzerr_col_runtime:
        if 'MS1_mz_within_5ppm' in df_filtered.columns and ms1_mz_error_tol_mode == 'ppm':
            within = df_filtered['MS1_mz_within_5ppm']
            mask_mzerr = within.fillna(False).astype(bool)
        elif ms1_mz_error_tol_mode == 'da' and mzerr_theoretical_col:
            mzerr_ppm_vals = pd.to_numeric(df_filtered[mzerr_col_runtime], errors='coerce').abs()
            theo_vals = pd.to_numeric(df_filtered[mzerr_theoretical_col], errors='coerce')
            mzerr_da_vals = mzerr_ppm_vals * theo_vals * 1e-6
            mask_mzerr = mzerr_da_vals <= float(ms1_mz_error_da_thresh)
            mask_mzerr = mask_mzerr | mzerr_da_vals.isna()
        else:
            mzerr_vals = pd.to_numeric(df_filtered[mzerr_col_runtime], errors='coerce')
            mask_mzerr = mzerr_vals.abs() <= float(ms1_mz_error_ppm_thresh)
            mask_mzerr = mask_mzerr & mzerr_vals.notna()
        df_filtered = df_filtered[mask_mzerr].copy()
    # Optional ion-type evidence filter (matches prefilter script behavior).
    if prefilter_use_ion_types and prefilter_ion_types:
        matched_frag_col_runtime = _prefilter_matched_frag_col(df_filtered)
        allowed_ion_types = {
            str(x).strip().lower()
            for x in prefilter_ion_types
            if str(x).strip().lower() in {'a', 'b', 'c', 'x', 'y', 'z', 'z1'}
        }
        if matched_frag_col_runtime and allowed_ion_types:
            mask_ions = df_filtered[matched_frag_col_runtime].apply(
                lambda v: len(_prefilter_row_ion_types(v).intersection(allowed_ion_types)) > 0
            )
            df_filtered = df_filtered[mask_ions].copy()
    step_counts.append(('Prefilter', len(df_filtered), n_prev))
    n_prev = len(df_filtered)

    # Step 6: Extraction (apex, coelution, shape)
    if enable_apex and has_extraction and 'apex_intensity' in df_filtered.columns:
        mask_apex = pd.to_numeric(df_filtered['apex_intensity'], errors='coerce') >= apex_min
        mask_apex = mask_apex | pd.isna(df_filtered['apex_intensity'])
        df_filtered = df_filtered[mask_apex].copy()
    if enable_shape and 'shape_corr' in df_filtered.columns:
        mask_shape = pd.to_numeric(df_filtered['shape_corr'], errors='coerce') >= shape_min
        mask_shape = mask_shape | pd.isna(df_filtered['shape_corr'])
        df_filtered = df_filtered[mask_shape].copy()
    if enable_coelution and has_coelution and 'coelution_score' in df_filtered.columns:
        mask_coel = pd.to_numeric(df_filtered['coelution_score'], errors='coerce') >= coelution_min
        mask_coel = mask_coel | pd.isna(df_filtered['coelution_score'])
        df_filtered = df_filtered[mask_coel].copy()
    step_counts.append(('Extraction', len(df_filtered), n_prev))
    n_prev = len(df_filtered)

    # Step 5 (after extraction): Significant fragmentation (5ppm, min sig frags, 1% max peak)
    if enable_sig_frags and has_sig_frags:
        def _count_sig(row):
            # Use significant_frags (pass all 3 criteria) only.
            val = row.get(SIGNIFICANT_FRAGS_COL)
            if pd.isna(val) or val is None or str(val).strip() == '':
                return 0
            parts = [p.strip() for p in str(val).replace(',', ' ').split() if p.strip()]
            return len(parts)
        def _count_overhangs(row):
            val = row.get('single_aa_overhangs_protein_positions')
            if pd.isna(val) or val is None or str(val).strip() == '':
                return 0
            return len([p.strip() for p in str(val).split(',') if p.strip()])
        counts = df_filtered.apply(_count_sig, axis=1)
        overhang_counts = df_filtered.apply(_count_overhangs, axis=1)
        effective_min = 0 if filter_tab_is_peptide_mode else max(1, min_sig_frag_count)
        effective_overhang_min = 0 if filter_tab_is_peptide_mode else 2
        mask_sig = (counts >= effective_min) & (overhang_counts >= effective_overhang_min)
        df_filtered = df_filtered[mask_sig].copy()
    step_counts.append(('Significance', len(df_filtered), n_prev))
    n_prev = len(df_filtered)

    n_final = len(df_filtered)
    df = df_filtered

    # Diagnostic helpers (use df_orig = data before any filtering)
    passed_all = set(df.index)  # rows that passed ALL filters — use for Pass/Fail color in all stage plots
    def _status_all(idx):
        return 'Pass' if idx in passed_all else 'Fail'
    def _pass_conf(r):
        return _pass_confidence(r, df_orig, qcol, pepcol, q_thresh, pep_thresh, use_q=use_q_filter, use_pep=use_pep_filter)
    def _count_sig(r):
        val = r.get(SIGNIFICANT_FRAGS_COL)
        if pd.isna(val) or val is None or str(val).strip() == '': return 0
        return len([p for p in str(val).replace(',', ' ').split() if p.strip()])

    def _reorder_traces_smaller_on_top(fig, plot_df, color_col):
        """Put smaller category trace last so it's drawn on top."""
        if color_col not in plot_df.columns:
            return
        counts = plot_df[color_col].value_counts()
        if len(counts) >= 2:
            smaller, larger = counts.idxmin(), counts.idxmax()
            fig.data = sorted(fig.data, key=lambda t: (0 if getattr(t, 'name', None) == larger else 1))

    # Helper to make Plotly or matplotlib scatter (compact for grid layout)
    PLOT_HEIGHT = 280
    def _scatter_plotly(x, y, color=None, title='', xlabel='', ylabel='', log_x=False, log_y=False, hline=None, vline=None, height=None):
        try:
            import plotly.express as px
            h = height if height is not None else PLOT_HEIGHT
            d = {'x': x, 'y': y}
            if color is not None:
                d['color'] = color
            plot_df = pd.DataFrame(d)
            if color is not None:
                fig = px.scatter(plot_df, x='x', y='y', color='color', log_x=log_x, log_y=log_y,
                                 title=title, labels={'x': xlabel or 'x', 'y': ylabel or 'y', 'color': 'Status'},
                                 color_discrete_map={'Fail': 'red', 'Pass': 'dodgerblue'})
                _reorder_traces_smaller_on_top(fig, plot_df, 'color')
            else:
                fig = px.scatter(plot_df, x='x', y='y', log_x=log_x, log_y=log_y, title=title,
                                 labels={'x': xlabel or 'x', 'y': ylabel or 'y'})
            if hline is not None:
                fig.add_hline(y=hline, line_dash='dash', line_color='red')
            if vline is not None:
                fig.add_vline(x=vline, line_dash='dash', line_color='orange')
            fig.update_traces(marker=dict(opacity=0.5, line=dict(color='black', width=1)))
            fig.update_layout(template='plotly_dark', height=h, margin=dict(l=40, r=20, t=40, b=40))
            return fig
        except ImportError:
            return None

    def _plot_grid(items):
        """Render a list of (fig, key) in a 2-column grid. items: list of (fig or None, unique_key)."""
        for i in range(0, len(items), 2):
            pair = items[i:i+2]
            cols = st.columns(2)
            for j, (fig, _) in enumerate(pair):
                if fig is not None:
                    with cols[j]:
                        st.plotly_chart(fig, width='stretch')

    # ─── Shared diagnostic plot builders (used by Fragment Search + Prefilter) ─
    def _build_ion_variant_df(df_in: pd.DataFrame) -> pd.DataFrame | None:
        """Parse ion-variant composition from a dataframe with ion_identity / ion_type columns."""
        ion_rows_loc: list[dict[str, object]] = []
        for _, row in df_in.iterrows():
            src = str(row.get('source_mzml', '') or '').strip()
            row_ion_type_norm = str(row.get('ion_type', '') or '').strip().lower()
            ids: list[str] = []
            if 'ion_identity' in df_in.columns:
                ion_val = str(row.get('ion_identity', '') or '').strip()
                if ion_val:
                    ids = [ion_val]
            if (not ids) and COMET_MATCHED_FRAGS_COL in df_in.columns:
                ids = [t.strip() for t in str(row.get(COMET_MATCHED_FRAGS_COL, '') or '').split(',') if t.strip()]
            if not ids:
                continue
            for ion_id in ids:
                ion_s = str(ion_id or '').strip()
                if not ion_s:
                    continue
                ion_low = ion_s.lower()
                base_m = re.match(r'^\(?\s*([abcxyz])', ion_low)
                if not base_m:
                    continue
                base_ion = str(base_m.group(1)).lower()
                z_m = re.search(r'(?:^|[_\s-])(\d+)\+$', ion_s)
                try:
                    ion_charge = int(z_m.group(1)) if z_m else 1
                except Exception:
                    ion_charge = 1
                if ion_charge <= 0:
                    ion_charge = 1
                is_neutral = bool(re.search(r'-(h2o|nh3|co)(?:$|_|[^a-z0-9])', ion_low, flags=re.IGNORECASE))
                is_radical = bool(
                    (row_ion_type_norm in {'c-1', 'c+1', 'c+2', 'z-1', 'z+1', 'z+2', 'z+3'})
                    or bool(re.search(r'^[cz][+-]\d+$', row_ion_type_norm))
                    or re.search(r'^\(?\s*[cz][+-]\d+\s*\)?', ion_low)
                    or re.search(r'^[cz](?:\d+)?[+-]\d+', ion_low)
                    or re.search(r'^[cz]\d+[+-]\d+(?:$|[_\s-])', ion_low)
                    or re.search(r'^[cz][+-]\d+', ion_low)
                    or re.search(r'^[cz]\d+_\d+(?:$|[_\s-])', ion_low)
                )
                neutral_loss_subclass = ''
                m_loss = re.search(r'-(h2o|nh3|co|h3po4|hpo3)(?:$|_|[^a-z0-9])', ion_low, flags=re.IGNORECASE)
                if m_loss:
                    neutral_loss_subclass = '-' + str(m_loss.group(1)).upper()
                radical_subclass = ''
                m_rad_type = re.match(r'^([cz][+-]\d+)$', row_ion_type_norm)
                if m_rad_type:
                    radical_subclass = str(m_rad_type.group(1)).lower()
                else:
                    m_rad_paren = re.match(r'^\(?\s*([cz][+-]\d+)\s*\)?', ion_low)
                    if m_rad_paren:
                        radical_subclass = str(m_rad_paren.group(1)).lower()
                    else:
                        m_rad_std = re.match(r'^([cz])\d+([+-]\d+)', ion_low)
                        if m_rad_std:
                            radical_subclass = f"{str(m_rad_std.group(1)).lower()}{str(m_rad_std.group(2))}"
                        elif ion_low.startswith('z1_'):
                            radical_subclass = 'z+1'
                if is_neutral:
                    variant_class = 'Neutral loss'
                elif is_radical:
                    variant_class = 'Free radical variant'
                else:
                    variant_class = 'Normal'
                ion_rows_loc.append({
                    'source_mzml': src, 'ion_identity': ion_s,
                    'base_ion': base_ion, 'ion_charge': int(ion_charge),
                    'ion_group': f'{base_ion}{int(ion_charge)}+',
                    'variant_class': variant_class,
                    'radical_subclass': radical_subclass,
                    'neutral_loss_subclass': neutral_loss_subclass,
                })
        if not ion_rows_loc:
            return None
        idf = pd.DataFrame(ion_rows_loc)
        idf = idf.drop_duplicates(subset=['source_mzml', 'ion_identity', 'variant_class']).copy()
        return idf

    def _build_ion_variant_plots(df_in: pd.DataFrame, key_prefix: str) -> list[tuple]:
        """Build prefilter-style ion-variant plots from any dataframe with ion data.
        Returns list of (fig, key) tuples for _plot_grid."""
        import plotly.graph_objects as go
        import plotly.express as px
        plots: list[tuple] = []
        ion_df = _build_ion_variant_df(df_in)
        if ion_df is None or ion_df.empty:
            return plots
        classes = ['Normal', 'Free radical variant', 'Neutral loss']
        color_map_var = {'Normal': '#60a5fa', 'Free radical variant': '#e879f9', 'Neutral loss': '#fbbf24'}
        counts = (
            ion_df.groupby(['base_ion', 'ion_charge', 'ion_group', 'variant_class'], dropna=False)
            .size().reset_index(name='count')
        )
        if counts.empty:
            return plots
        all_groups = counts[['base_ion', 'ion_charge', 'ion_group']].drop_duplicates().sort_values(['base_ion', 'ion_charge'])
        ion_group_order = [f'{str(r.base_ion)}{int(r.ion_charge)}+' for r in all_groups.itertuples(index=False)]
        x_positions: list[float] = []
        pos = 0.0
        prev_base = None
        for r in all_groups.itertuples(index=False):
            base_now = str(r.base_ion)
            if prev_base is None:
                pos = 0.0
            elif base_now == prev_base:
                pos += 1.0
            else:
                pos += 2.4
            x_positions.append(float(pos))
            prev_base = base_now
        x_by_group = {g: x for g, x in zip(ion_group_order, x_positions)}
        full_rows = []
        for _, g in all_groups.iterrows():
            for cl in classes:
                full_rows.append({'base_ion': str(g['base_ion']), 'ion_charge': int(g['ion_charge']),
                                  'ion_group': str(g['ion_group']), 'variant_class': cl})
        full_df = pd.DataFrame(full_rows)
        ratio_df = full_df.merge(counts[['base_ion', 'ion_charge', 'ion_group', 'variant_class', 'count']],
                                 on=['base_ion', 'ion_charge', 'ion_group', 'variant_class'], how='left')
        ratio_df['count'] = pd.to_numeric(ratio_df['count'], errors='coerce').fillna(0).astype(int)
        totals = ratio_df.groupby(['base_ion', 'ion_charge', 'ion_group'], dropna=False)['count'].transform('sum')
        ratio_df['ratio_pct'] = np.where(totals > 0, (ratio_df['count'] / totals) * 100.0, 0.0)
        fig_ratio = go.Figure()
        for cl in classes:
            sub = ratio_df[ratio_df['variant_class'] == cl].set_index('ion_group', drop=False)
            ys = []
            counts_hover = []
            for g in ion_group_order:
                if g in sub.index:
                    row_g = sub.loc[g]
                    if isinstance(row_g, pd.DataFrame):
                        row_g = row_g.iloc[0]
                    ys.append(float(pd.to_numeric(row_g.get('ratio_pct'), errors='coerce') or 0.0))
                    counts_hover.append(int(pd.to_numeric(row_g.get('count'), errors='coerce') or 0))
                else:
                    ys.append(0.0)
                    counts_hover.append(0)
            fig_ratio.add_trace(go.Bar(
                x=[x_by_group[g] for g in ion_group_order], y=ys, name=cl, width=[0.98] * len(ion_group_order),
                marker_color=color_map_var.get(cl, '#cccccc'),
                customdata=np.array(list(zip(ion_group_order, counts_hover)), dtype=object),
                hovertemplate='Ion family: %{customdata[0]}<br>Variant class: ' + str(cl) + '<br>Count: %{customdata[1]}<br>Composition: %{y:.2f}%<extra></extra>',
            ))
        fig_ratio.update_layout(template='plotly_dark', height=PLOT_HEIGHT, margin=dict(l=40, r=20, t=48, b=60),
                                barmode='stack', bargap=0.0, bargroupgap=0.0)
        fig_ratio.update_yaxes(range=[0, 100], ticksuffix='%')
        fig_ratio.update_xaxes(tickmode='array', tickvals=x_positions, ticktext=ion_group_order, tickangle=35,
                               title_text='Ion family (letter + charge)')
        plots.append((fig_ratio, f'{key_prefix}_variant_ratio_by_ion_charge'))
        ion_df_u = ion_df.drop_duplicates(subset=['source_mzml', 'ion_identity']).copy()
        rad_df = ion_df_u[ion_df_u['base_ion'].isin({'c', 'z'}) & (ion_df_u['radical_subclass'].str.strip() != '')]
        if not rad_df.empty:
            rad_counts = (rad_df.groupby(['base_ion', 'ion_charge', 'ion_group', 'radical_subclass'], dropna=False)
                          .size().reset_index(name='count').sort_values(['base_ion', 'ion_charge', 'radical_subclass']))
            cz_order = rad_counts[['base_ion', 'ion_charge', 'ion_group']].drop_duplicates().sort_values(['base_ion', 'ion_charge'])['ion_group'].astype(str).tolist()
            fig_rad_sub = px.bar(rad_counts, x='ion_group', y='count', color='radical_subclass', barmode='group',
                                 title='c/z radical sub-subclasses by ion family',
                                 labels={'ion_group': 'Ion family', 'count': 'Unique ion identities', 'radical_subclass': 'Radical sub-subclass'},
                                 category_orders={'ion_group': cz_order},
                                 color_discrete_map=dict(_HDX_RADICAL_ION_COLOR_MAP))
            fig_rad_sub.update_xaxes(tickangle=35)
            plots.append((fig_rad_sub, f'{key_prefix}_radical_subsubclass_cz'))
        nl_df = ion_df_u[ion_df_u['neutral_loss_subclass'].str.strip() != '']
        if not nl_df.empty:
            nl_counts = (nl_df.groupby(['base_ion', 'ion_charge', 'ion_group', 'neutral_loss_subclass'], dropna=False)
                         .size().reset_index(name='count').sort_values(['base_ion', 'ion_charge', 'neutral_loss_subclass']))
            nl_order = nl_counts[['base_ion', 'ion_charge', 'ion_group']].drop_duplicates().sort_values(['base_ion', 'ion_charge'])['ion_group'].astype(str).tolist()
            fig_nl_sub = px.bar(nl_counts, x='ion_group', y='count', color='neutral_loss_subclass', barmode='group',
                                title='Neutral-loss sub-subclasses by ion family',
                                labels={'ion_group': 'Ion family', 'count': 'Unique ion identities', 'neutral_loss_subclass': 'Neutral-loss sub-subclass'},
                                category_orders={'ion_group': nl_order},
                                color_discrete_map={'-NH3': '#f97316', '-H2O': '#22c55e', '-CO': '#14b8a6', '-H3PO4': '#eab308', '-HPO3': '#84cc16'})
            fig_nl_sub.update_layout(template='plotly_dark', height=PLOT_HEIGHT, margin=dict(l=40, r=20, t=48, b=60))
            fig_nl_sub.update_xaxes(tickangle=35)
            plots.append((fig_nl_sub, f'{key_prefix}_neutral_loss_subsubclass'))
        return plots

    def _shared_activation_ms(source_name: object) -> float | None:
        src = os.path.basename(str(source_name or '').strip())
        if not src:
            return None
        stem = os.path.splitext(src)[0]
        try:
            setting = _infer_fragmentation_setting_from_run_name(stem)
            m = re.search(r'_(\d+)ms$', str(setting or ''), flags=re.IGNORECASE)
            if m:
                return float(int(m.group(1)))
        except Exception:
            pass
        m2 = re.search(r'(\d+(?:\.\d+)?)\s*ms', stem, flags=re.IGNORECASE)
        if m2:
            try:
                return float(m2.group(1))
            except Exception:
                return None
        return None

    def _shared_activation_method(source_name: object) -> str:
        src = os.path.basename(str(source_name or '').strip())
        if not src:
            return ''
        stem = os.path.splitext(src)[0]
        setting = str(_infer_fragmentation_setting_from_run_name(stem) or '').strip().upper()
        if not setting:
            return ''
        return setting.split('_')[0]

    def _build_activation_trend_plots(df_in: pd.DataFrame, key_prefix: str) -> list[tuple]:
        """Build fragment-search-style activation trend plots from any dataframe with source_mzml + ion_identity.
        Also handles packed fragment_matched_frags column by exploding it.
        Returns list of (fig, key) tuples for _plot_grid."""
        import plotly.graph_objects as go
        plots: list[tuple] = []
        if 'source_mzml' not in df_in.columns:
            return plots
        has_ion_id = 'ion_identity' in df_in.columns
        has_packed = COMET_MATCHED_FRAGS_COL in df_in.columns
        if not has_ion_id and not has_packed:
            return plots
        if has_ion_id:
            d = df_in.copy()
            d['source_mzml'] = d['source_mzml'].astype(str).str.strip()
            d['ion_identity'] = d['ion_identity'].astype(str).str.strip()
            d = d[(d['source_mzml'] != '') & (d['ion_identity'] != '')].copy()
        else:
            rows_exp: list[dict] = []
            for _, row in df_in.iterrows():
                src = str(row.get('source_mzml', '') or '').strip()
                packed = str(row.get(COMET_MATCHED_FRAGS_COL, '') or '').strip()
                if not src or not packed:
                    continue
                extra = {}
                if 'ion_type' in df_in.columns:
                    extra['ion_type'] = str(row.get('ion_type', '') or '').strip()
                if 'plain_peptide' in df_in.columns:
                    extra['plain_peptide'] = str(row.get('plain_peptide', '') or '').strip()
                for tok in packed.split(','):
                    tok = tok.strip()
                    if tok:
                        rows_exp.append({'source_mzml': src, 'ion_identity': tok, **extra})
            if not rows_exp:
                return plots
            d = pd.DataFrame(rows_exp)
        if d.empty:
            return plots
        d['hdx_label'] = d['source_mzml'].map(
            lambda s: _infer_hdx_label_from_run_name(os.path.splitext(os.path.basename(str(s)))[0])
        ).astype(str).str.upper()
        d = d[d['hdx_label'].isin({'H', 'UN'})].copy()
        if d.empty:
            return plots
        d['activation_ms'] = d['source_mzml'].map(_shared_activation_ms)
        d = d[pd.to_numeric(d['activation_ms'], errors='coerce').notna()].copy()
        if d.empty:
            return plots
        d['activation_method'] = d['source_mzml'].map(_shared_activation_method).astype(str).str.upper()
        d = d[d['activation_method'] == 'UVPD'].copy()
        if d.empty:
            return plots
        d['activation_ms'] = pd.to_numeric(d['activation_ms'], errors='coerce').astype(float)
        if 'ion_type' in d.columns:
            ion_type_norm = d['ion_type'].astype(str).str.strip().str.lower()
        else:
            ion_type_norm = (d['ion_identity'].astype(str).str.extract(r'^([A-Za-z](?:[+-]\d+)?)', expand=False)
                             .fillna('').astype(str).str.lower())
        d['ion_type_norm'] = ion_type_norm
        d['base_ion'] = d['ion_type_norm'].str.extract(r'^([abcxyz])', expand=False).fillna('')
        d['is_neutral_loss'] = d['ion_identity'].astype(str).str.contains(
            r'-(H2O|NH3|CO|H3PO4|HPO3)(?:$|_|[^A-Za-z0-9])', regex=True, na=False, case=False)
        if 'is_radical_variant' in d.columns:
            d['is_radical_variant'] = d['is_radical_variant'].astype(str).str.strip().str.lower().isin({'1', 'true', 't', 'yes', 'y'})
        else:
            d['is_radical_variant'] = (
                d['ion_type_norm'].isin({'c-1', 'c+1', 'c+2', 'z-1', 'z+1', 'z+2', 'z+3'})
                | d['ion_type_norm'].str.contains(r'^[cz][+-]\d+$', regex=True, na=False)
                | d['ion_identity'].astype(str).str.contains(
                    r'^\(?\s*[cz][+-]\d+\s*\)?|^z1_|^\(?\s*[cz]\d+[+-]\d+', regex=True, na=False, case=False))
        base_ions = ['a', 'b', 'c', 'x', 'y', 'z']
        categories = ['a', 'b', 'c', 'x', 'y', 'z', 'neutral_loss', 'radical_variant']
        run_rows: list[dict[str, object]] = []
        for (src_name, act_ms), g in d.groupby(['source_mzml', 'activation_ms'], dropna=False):
            row: dict[str, object] = {'source_mzml': str(src_name), 'activation_ms': float(act_ms),
                                      'total_unique_identities': int(g['ion_identity'].nunique())}
            for base in base_ions:
                row[base] = int(g.loc[g['base_ion'] == base, 'ion_identity'].nunique())
            row['neutral_loss'] = int(g.loc[g['is_neutral_loss'], 'ion_identity'].nunique())
            row['radical_variant'] = int(g.loc[g['is_radical_variant'], 'ion_identity'].nunique())
            for base in base_ions:
                row[f'{base}_neutral_loss'] = int(g.loc[(g['base_ion'] == base) & (g['is_neutral_loss']), 'ion_identity'].nunique())
                row[f'{base}_radical_variant'] = int(g.loc[(g['base_ion'] == base) & (g['is_radical_variant']), 'ion_identity'].nunique())
            run_rows.append(row)
        if not run_rows:
            return plots
        run_df = pd.DataFrame(run_rows)
        for cat in categories:
            denom = pd.to_numeric(run_df['total_unique_identities'], errors='coerce').replace(0, np.nan)
            run_df[f'{cat}__ratio'] = pd.to_numeric(run_df[cat], errors='coerce') / denom
        agg = run_df.groupby('activation_ms', dropna=False).agg(
            n_runs=('source_mzml', 'nunique'),
            **{f'{cat}__mean': (cat, 'mean') for cat in categories},
            **{f'{cat}__ratio_mean': (f'{cat}__ratio', 'mean') for cat in categories},
        ).reset_index().sort_values('activation_ms')
        x_tick_vals = sorted({float(v) for v in pd.to_numeric(agg['activation_ms'], errors='coerce').dropna().tolist()})
        use_log_x = bool(x_tick_vals) and min(x_tick_vals) > 0
        x_tick_text = [(str(int(v)) if abs(float(v) - round(float(v))) < 1e-9 else f'{float(v):g}') for v in x_tick_vals]
        color_map_act = {'a': '#1f77b4', 'b': '#ff7f0e', 'c': '#2ca02c', 'x': '#d62728', 'y': '#9467bd', 'z': '#8c564b',
                         'neutral_loss': '#17becf', 'radical_variant': '#e377c2'}
        def _apply_x(fig):
            if x_tick_vals:
                fig.update_xaxes(type='log' if use_log_x else 'linear', tickmode='array',
                                 tickvals=x_tick_vals, ticktext=x_tick_text, ticks='outside', ticklen=6)
        fig_abs = go.Figure()
        for cat in categories:
            fig_abs.add_trace(go.Scatter(x=agg['activation_ms'], y=agg[f'{cat}__mean'], mode='lines+markers', name=cat,
                                         line=dict(color=color_map_act.get(cat, '#bbbbbb'), width=2), marker=dict(size=7)))
        fig_abs.update_layout(template='plotly_dark', height=430, title='Unique fragment identities vs activation (ms)',
                              xaxis_title='Activation (ms)', yaxis_title='Unique identities (mean)', legend_title='Fragment class')
        _apply_x(fig_abs)
        plots.append((fig_abs, f'{key_prefix}_activation_abs'))
        fig_ratio = go.Figure()
        for cat in categories:
            y_vals = pd.to_numeric(agg[f'{cat}__ratio_mean'], errors='coerce') * 100.0
            fig_ratio.add_trace(go.Scatter(x=agg['activation_ms'], y=y_vals, mode='lines+markers', name=cat,
                                            line=dict(color=color_map_act.get(cat, '#bbbbbb'), width=2), marker=dict(size=7)))
        fig_ratio.update_layout(template='plotly_dark', height=430, title='Fragment-class ratio vs activation (ms)',
                                xaxis_title='Activation (ms)', yaxis_title='Ratio (%)', legend_title='Fragment class')
        _apply_x(fig_ratio)
        plots.append((fig_ratio, f'{key_prefix}_activation_ratio'))
        fig_nl = go.Figure()
        for base in base_ions:
            y_mean = run_df.groupby('activation_ms', dropna=False)[f'{base}_neutral_loss'].mean().reset_index()
            fig_nl.add_trace(go.Scatter(x=y_mean['activation_ms'], y=y_mean[f'{base}_neutral_loss'], mode='lines+markers',
                                        name=f'{base} neutral-loss', line=dict(color=color_map_act.get(base, '#bbbbbb'), width=2), marker=dict(size=7)))
        fig_nl.update_layout(template='plotly_dark', height=420, title='Ion-type neutral-loss counts vs activation (ms)',
                             xaxis_title='Activation (ms)', yaxis_title='Unique neutral-loss identities (mean)', legend_title='Ion type')
        _apply_x(fig_nl)
        plots.append((fig_nl, f'{key_prefix}_activation_neutral_by_ion'))
        fig_rv = go.Figure()
        for base in base_ions:
            y_mean = run_df.groupby('activation_ms', dropna=False)[f'{base}_radical_variant'].mean().reset_index()
            fig_rv.add_trace(go.Scatter(x=y_mean['activation_ms'], y=y_mean[f'{base}_radical_variant'], mode='lines+markers',
                                        name=f'{base} radical-variant', line=dict(color=color_map_act.get(base, '#bbbbbb'), width=2), marker=dict(size=7)))
        fig_rv.update_layout(template='plotly_dark', height=420, title='Ion-type radical-variant counts vs activation (ms)',
                             xaxis_title='Activation (ms)', yaxis_title='Unique radical-variant identities (mean)', legend_title='Ion type')
        _apply_x(fig_rv)
        plots.append((fig_rv, f'{key_prefix}_activation_radical_by_ion'))
        return plots

